window.__D("text/torat-shmuel/c038",{"p":[[2002180329,"<b>וזהו</b> שביוהכ\"פ מתירין נדרים, ובנוסח שלנו אומרים מיוכ\"פ זה עד יוהכ\"פ הבא, ובפוסקים יש מחלוקת<sup data-n=\"1050\">5</sup> אם על שנה העברה או על שנה הבא, הגם דעשי\"ת הם בבינה ושם מקום הנדר, אך הנה ביוהכ\"פ ניתנו הלוחות שניות והוא יום הארבעים, וכמו שמפרש רבינו ז\"ל כיפורים ופורים חד דרגא, הארת יסו\"א<sup data-n=\"1051\">6</sup> בנוק' עד בבי\"ע, לכן אז זמן התרת נדרים.\n<b>והנה</b> כמו שנת\"ל<sup data-n=\"1052\">7</sup> ענין נדרים והיתר נדרים כמו\"כ ענין נדרים וקרבנות, דקרבן הוא שמקריב בהמה ע\"ג מזבח הרי מקריב אותה ונכלל בבחי' ארי' דאכיל קורבנין, ארי' הוא אור י', ולכן ההקרבה הוא ע\"י הכהן שהוא בחי' חכ' וכמ\"ש ואתה כהן לעולם*, שע\"י חכ' יכולים להקריב אותם. וכמו ע\"ד דוגמא הנה כל שאור וכל דבש לא תקטירו ממנו אשה לה', דהנה ארז\"ל כל המנחות באות מצה חוץ מחמץ שבתודה ושתי הלחם באות חמץ, דשתי הלחם הם בשבועות שאז הי' מ\"ת והוא מדרי' גבוה לכן נתעלה חמץ ג\"כ, וכן לחמי תודה שהוא הודאה ד\"ע איך שכולא קמי' כלא חשיב ומצד בחי' זו אפשר שיתעלה חמץ ג\"כ, ונאכל לכהנים דאכילת כהנים מעורר אכילת אדם בגימ' מ\"ה, שהוא בחי' מ\"ה דחכ' כח מ\"ה, דאכילת כהנים גבוה במעלה מאכילת מזבח בעצם.\n<b>ובעבודה</b> הו\"ע תורה ותפלה, דהנה בתפלה אומרים סלח לנו אבינו כי חטאנו, ואחר שמ\"ע אומרים וידויים אשמנו כו', ולכאורה הי' צריכים להתחיל התפלה בסלח לנו כו', דהו\"ע בקשת מחילה וסליחה דמה יכול להיות גרוע יותר מחטאנו. והענין דהנה מיד כשניעור משנתו ולא עשה עבירה בפו\"מ, ובפרט כשעשה איזה מצוה, הרי נדמה לו שהוא מקורב, ואח\"כ כשמתפלל פסוד\"ז שהוא לזמר עריצים, כמו אילן כשרוצים שיהא נגדל יפה חותכין הענפים היבשים כמו\"כ פסוד\"ז\n\n)בגוכי\"ק נרשמה כאן הגה\"ה, ובצידי הגליון נרשם ע\"ז אצ\"ל [ אין צריך להעתיק], וז\"ל: (ע' בסי' ח' א' בפי' ב\"ש, וע' בפה\"מ<sup data-n=\"1231\">8</sup> פצ\"ד (בהג\"ה) פי' כמ\"ש כאן וע' בד\"ה בהעלותך (טל) פ\"ג. ובד\"ה ובראשי חדשיכם פ\"א נראה שמפרש כן מאמר הז' יתרו דס\"ז ב' (והכל הולך למקום א') דהכהן משמש למלך דאיהו רזא דקדה\"ק כתר א\"א רב חסד (ואפ\"ל כה\"ג רב חסד<sup data-n=\"1232\">9</sup> וההקרבה הי' ע\"י כהן הדיוט חכ' ואפ\"ל שכ\"ד הרמ\"ז) (ומוכרח לפרש כן דכפה\"נ דהכל ד' א') וע' בהרמ\"ז שמפרש מאה\"ז הנ\"ל באופן אחר וצ\"ע).",[["1050","5","<b>ובנוסח שלנו אומרים מיוכ\"פ זה עד יוהכ\"פ הבא ובפוסקים יש מחלוקת</b>: ראה תוס' ושא\"ר נדרים כג, ב."],["1051","6","<b>וכמו שמפרש רבינו ז\"ל כיפורים ופורים . . הארת יסו\"א</b>: לעיל במאמר (ע' תעז) מביא ע\"ז מד\"ה כי אברהם לא ידענו — בת\"א צג, ג."],["1052","7","<b>והנה כמו שנת\"ל</b>: בהבא לקמן ראה גם אוה\"ת מטות ע' א'שי."],["1231","8","בסי' ח' א' בפי' ב\"ש, וע' בפה\"מ פצ\"ד: בסידור עם דא\"ח בדף לט, ג. ובס' פירוש המלות לאדהאמ\"צ ס, א."],["1232","9","ואפ\"ל כה\"ג רב חסד . . שכ\"ד הרמ\"ז: שורה זו ניתוספה אח\"כ בין השיטין באותיות קטנות."]]],[2002180330,"הוא לזמר החוחים וקוצים, ואח\"כ ברכת ק\"ש ברכה ראשונה הוא נגד ה' אחד שע\"פ פשוט הוא ז\"ר וארץ וד' רוחות העולם והוא ביטול דמלאכי', וברכה שני' הוא נגד ה' אלקינו, ואח\"כ מס\"נ באחד, אז אומר סלח לנו אבינו כי חטאנו שמרגיש אפי' דקות הרע, והעיקר הוידוים אשמנו בגדנו כו' שאח\"כ שהוא דחיות הרע כדי שיהי' אח\"כ נפ\"א שהוא ביטול היותר גבוה, וא\"כ הו\"ע נדרים.\n<b>והנה</b> נדרים והיתר נדרים הם בדיבור<sup data-n=\"1053\">10</sup>, וקרבנות צריכים ג\"כ להקדיש אותו בדיבור, דהנה כתי' ה' בחכ' יסד ארץ, אבא יסד ברתא, שהוא עולם הדיבור שרשו מבחי' חכ', לכן אפשר להקדיש בדיבור היינו שממשיך מקיף מחכ' על אותו דבר ומעלה אותה מגשמיותה, וכן בנדרים שממשיך מקיף, וחכם שמתיר הנדר היינו ג\"כ שממשיך מקיף מבחי' חכ', ותורה הו\"ע היתר נדרים.\n<b>וזהו</b> וידבר משה אל ראשי המטות<sup data-n=\"1054\">11</sup> דיחיד מומחה יכול להתיר את הנדר, הנה מטות הם י\"ב גבולי אלכסונים, ראשי המטות הם מוחין שבמדות, ומשה הוא מוחין בעצם, וכמו ע\"ד דוגמא ישראל מתקשראין באורייתא, ישראל הם לי ראש ומהו\"ע מתקשראין באורייתא, וההפרש דישראל הם מוחין שבמדות, ואורייתא הם מוחין בעצם, ומשה הוא נותן כח להתיר הנדר. והענין דהנה סנהדרין הם ע\"א ולמדים זה ממשה דכתי' אספה לי שבעים איש מזקני ישראל ומשה על גביהם הרי ע\"א, דמשה א' מאין לי בשר שאפי' בבשר שכבר נתברר לא הי' יכול להשפיל א\"ע כ\"א זקנים הי' יכולים להשפיל א\"ע. דהנה כתי' ואצלתי מן הרוח אשר עליך<sup data-n=\"1055\">12</sup>, שהם הפרשת הארה ממשה, כמו אור הנפש שמחי' את הגוף לא כל הנשמה מתלבשת בגוף דמלאך בשליש עולם עומד וכ\"ש נשמה שגבוה ממלאך אינו שייך שתתלבש בגוף כ\"א הארה ומקצת מהנשמה מתלבשת בגוף, ובהנשמה אינו שייך התחלקות האברי' ואפי' בההארה ג\"כ אינו שייך התחלקות כ\"א בהארה דהארה, כמו\"כ זקנים הם הפרשת הארה ממשה, וכמו אצילות אין לו השגה בא\"ס עצמות המאציל, דאצי' הוא ממוצע בין א\"ס עצמות המאציל ובין בי\"ע ולא יש לו השגה בא\"ס עצמות המאציל, כמו\"כ הע' זקנים לא הי' להם השגה ברוח משה, דיש מדרי' דלא ידע ולא אתידעא, לכן נתן כח להתיר הנדר שהוא הי' מופלא שבב\"ד.\n<b>וזהו</b> וידבר משה כו' זה הדבר, דהנה כל הנביאים נתנבאו בכה ומשה נתנבא בזה, דכה הוא כדמותינו וכמו אספקלרי' שאינה מאירה שאינו רואה עצם הדבר כלל כ\"א רק הדמות, וזה הוא אספה\"מ שרואה מהות הדבר, וזהו זה הדבר שהמשיך בחי' ראי', איזה חכם הרואה, דאינו דומה ראי' לשמיעה דכשמספרים לאדם איזה",[["1053","10","<b>והנה נדרים והיתר נדרים הם בדיבור</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380651\" data-slug=\"likkutei-torah\" data-id=\"4001380651\">לקו\"ת מטות פב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380655\" data-slug=\"likkutei-torah\" data-id=\"4001380655\">פג, ב</a> ואילך."],["1054","11","<b>וזהו וידבר משה אל ראשי המטות</b>: בהבא לקמן ראה אוה\"ת מטות שם ע' א'שיא ואילך."],["1055","12","<b>דהנה כתי' ואצלתי מן הרוח אשר עליך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370010\" data-slug=\"torah-or\" data-id=\"3901370010\">תו\"א בראשית ג, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370063\" data-slug=\"torah-or\" data-id=\"3901370063\">וירא יד, א</a>. סה\"מ תרל\"ב ח\"א ע' מב. וש\"נ. ועוד."]]],[2002180331,"דבר כמו שהוא מ\"מ כשרואה אותו דבר נעשה ההנחה בנפש באופן אחר דאינו דומה ראי' לשמיעה, והוא ההפרש בין שמע ישראל שהוא שמיעה למ\"ש שאו מרום עיניכם וראו שהוא ראי', וזהו שהמשיך ראי' שיראו בהקצה שיהפוך זה ג\"כ<sup data-n=\"1056\">13</sup>.\n<b>אך</b> צ\"ל דהנה בנדרים כתי' ג\"כ מופלא כמ\"ש איש כי יפליא לנדור נדר. והענין דהנה כתי' אאלפך חכ' אאלפך בינה, דמ\"ש איש כי יפליא הוא מופלא הסמוך לאיש והיינו הארת החכ' בבינה והו\"ע וחכם בבינה, ומופלא שבב\"ד הוא חכ' בעצם וכמ\"ש והחכ' מאין תמצא כמו מציאה שראובן מצא מה ששמעון אבד, דאל\"כ אין זה מציאה, כמו\"כ חכ' הוא הוא האין דכתר<sup data-n=\"1057\">14</sup>, וזהו\"ע מופלא שבב\"ד וכמ\"ש במופלא ממך אל תדרוש ובמכוסה ממך אל תחקור, לכן נתן כח להתיר הנדר. וזהו היתר נדרים פורחין באויר<sup data-n=\"1045\">15</sup> שהוא אור יוד, יוד הוא חכ' ואור יוד הוא מדרי' היותר גבוה ושרשו הוא אוירא דכיא. וזהו וידבר משה אל ראשי המטות זה הדבר כו', משה הוא חכ' בעצם לכן נתן כח להתיר הנדר.",[["1056","13","<b>שיראו בהקצה שיהפוך זה ג\"כ</b>: לע\"ע צ\"ב תיבות אלו בהכת\"י."],["1057","14","<b>הוא הוא האין דכתר</b>: כ\"ה בגוכתי\"ק."],["1045","15","<b>היתר נדרים פורחין באויר</b>: ל' המשנה חגיגה י, א. וברש\"י שם: התרת נדרים שאמרו חכמים שהחכם מתיר את הנדר מעט רמז יש במקרא ואין על מה לסמוך אלא שכן מסור לחכמים בתושבע\"פ."]]],[2002180332,"<h3>אז תשמח בתולה במחול (ש\"פ ראה)</h3>\n<b></b><b>ש\"פ ראה, על מז\"ט אצל גיסי הרמ\"ל, טל לפ\"ק</b>\n<b>אז</b> תשמח<sup data-n=\"1058\">1</sup> בתולה במחול, אז קאי על לעתיד<sup data-n=\"1059\">2</sup> וקאמר שלעתיד תשמח בתולה במחול. והענין דהנה בקידוש לבנה אומרים כשם שאני רוקד כנגדך ואיני יכול לנגוע בך כך כו', הנה יש ריקוד שהוא כנגד, וצ\"ל מה שייך ריקוד ללבנה, ומהו\"ע הריקוד. הנה יש ב' אופני הריקוד א' ריקוד שהוא כנגד, ב' הנק' מחול שקורין בל\"א ק„ראהד, והנה הריקוד שכנגד דרך הריקוד הוא שנים עומדים בקצה הבית זה במזרח זה במערב ואח\"כ הם מתקרבין מעט מעט עד שבאמצע הבית הם מתקרבין זה לזה ואח\"כ הם מתרחקים וזה שעמד תחילה במזרח עומד אח\"כ במערב כו' והם",[["1058","1","<b>אז תשמח</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע. (ונדפס ג\"כ בתור הוספה בסוף סה\"מ תרנ\"ד ע' שלז). תוכן מאמר זה לא נמצא לעיל במאמרי אדמו\"ר מהר\"ש (שרשם בעצמו), אך נמצא ג\"כ לקמן בהנחה נוספת (ולע\"ע לא נודע מיהו המניח).\nהמאמר מיוסד על ד\"ה זה בסה\"מ תקס\"ה ח\"א ע' ריד ואילך. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תר ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650155\" data-slug=\"or-hatorah-hb\" data-id=\"8316650155\">אוה\"ת נ\"ך כרך ב' ע' תתפד</a>.\nבראש המאמר כאן נרשמה כותרת בגוכי\"ק כ\"ק אדמו\"ר מהורש\"ב נ\"ע: ”ש\"פ ראה, על מז\"ט אצל גיסי הרמ\"ל\". וראה רשימת כ\"ק אדמו\"ר מוהריי\"צ נ\"ע (נדפס להלן בהוספות) אשר מאמר זה נאמר בעת שנולדה בת אצל בתו של כ\"ק אדמו\"ר מהר\"ש הרבנית דבורה לאה עם בעלה הרה\"ח ר' משה ארי' ליב גינזבורג (ראה אודותם בס' תורת שמואל דרושי חתונה ע' ריט)."],["1059","2","<b>אז קאי על לעתיד</b>: ראה גם לקו\"ת שמע\"צ פח, א-ב: וכמ\"ש אז תשמח בבחי' אז שהוא בבחי' קדם כו'."]]],[2002180333,"אז אב\"א, והריחוק הוא לצורך הקירוב<sup data-n=\"1060\">3</sup> שאח\"כ הם מתהפכין והם מתקרבין וסוף מעשה עלה במח' תחילה והעיקר הוא הקירוב שבאמצע הבית וזה עלה במח' תחילה. וכמו\"כ יובן בלבנה דהלבנה היא עצם חשוך ורק מקבלת אור השמש, בתחילה היא מרוחקת מהשמש ואינה מקבלת רק הארה לבד וזהו\"ע מולד הלבנה ואח\"כ נתקרב מעט מעט עד שבאמצע החדש היא מתקרבת לגמרי. וזהו\"ע קידוש לבנה שהוא כשהלבנה במלואה היינו שיהיה ניכר בה אור השמש, אומרים אז כשם שאני רוקד כנגדך ואיני יכול לנגוע בך כמו הריקוד שהוא כנגד<sup data-n=\"1061\">4</sup> בתחילה הוא מקורב ואח\"כ מתרחק ואח\"כ מתקרב כמו\"כ בלבנה בתחילה היא מתמלאת היינו שהיא בקירוב ואח\"כ היא נחסרת מעט מעט מפני שהיא מתרחקת, ובפרט יש כ\"ח עתים ללבנה י\"ד לטובה וי\"ד להיפך<sup data-n=\"1062\">5</sup>.\n<b>כמו\"כ</b> בעבודה הנה כתי' שמש ומגן הוי' אלקים וישראל מונין ללבנה היינו שמקבלין אור השמש, כתי' פנים בפנים דיבר ה' עמכם שיהי' ניכר פעולת שם הוי' בכאו\"א מישראל, דהנה בכאו\"א מישראל יש שם הוי' י' הוא הביטול שלמעלה מטו\"ד ה' התבוננות ו' תורה ה' אחרונה תפלה, אך שיהי' ניכר שם הוי', וזהו שמקבלין אור השמש. ולכן מצינו בהם שינויים, דקודם מ\"ת כתי' ויחן ישראל נגד ההר וארז\"ל כולם כאיש אחד והוא כמשל שבלבנה קודם המולד היא נקודה תחת היסוד<sup data-n=\"1063\">6</sup>, וכמו\"כ הוא ביטול דלפני אחד מה אתה סופר, דמה אפשר להיות פחות מאחד, ואח\"כ במ\"ת הנה ארז\"ל על כל דיבור ודיבור פרחה נשמתן שהוא ביטול שיוצא מגדר הכלי לגמרי, וכנגד זה הנה כתי' וירד ה' על הר סיני שהי' גילוי אלקות והי' עשרת הדברות ונתנו הלוחות שעליהם כתי' כתובים משני עבריהם מזה ומזה הם כתובים, ואי' בירושלמי שהי' כתובים בד' רוחות ומעלה מטה לא רק בפנים ואחור שהיו כולה פנים, ולכך צריכים לשאת אותם בכתף<sup data-n=\"1064\">7</sup> לחבר אותם עם הכתף, וזהו פנים בפנים שע\"י הבטה בפנים שלמטה לגבי מעלה והיינו הביטול עי\"ז פנים העליון מאיר למטה וזהו פנים בפנים, ואח\"כ ע\"י חטא העגל נתרחקו והיו בבחי'",[["1060","3","<b>והם אז אב\"א </b> [ אחור באחור]<b> והריחוק הוא לצורך הקירוב</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">לקו\"ת פקודי ז, א</a>, וז\"ל: ובמ\"א ע\"פ אז תשמח בתולה במחול נתבאר שכדי שיהי' עלי' מבחי' פב\"ב לבחי' פב\"פ במדרגה יותר גבוה כי יש כמה מדרגות בבחי' פב\"פ כו' הנה צ\"ל בתחלה אב\"א ואח\"כ נעשים נקודה תחת היסוד ואח\"כ נגדלת בבחי' פב\"פ במדרגה יותר גבוהה כו' ושם נתבאר הענין ג\"כ בעבודת ה'. ע\"כ.\nוראה גם לקו\"ת דרושים לשמע\"צ פו, ג: כמו ע\"ד משל שמרקדים במחול שמתרחק האחד מחבירו כו'. וראה בכ\"ז ס' מאמרי אדהאמ\"צ דרושי חתונה ע' תר ואילך."],["1061","4","<b>אומרים אז כשם שאני רוקד כנגדך . . כמו הריקוד שהוא כנגד</b>: ראה גם (בנוסף להנסמן לעיל בתחילת המאמר) תו\"ח שמות (הוצאת תשס\"ב) תצה, ב. תצו, ב. ס' מאמרי אדהאמ\"צ דרושי חתונה שם."],["1062","5","<b>ובפרט יש כ\"ח עתים ללבנה י\"ד לטובה וי\"ד להיפך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380382\" data-slug=\"likkutei-torah\" data-id=\"4001380382\">לקו\"ת במדבר יח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380387\" data-slug=\"likkutei-torah\" data-id=\"4001380387\">יט, ד</a>. סה\"מ תרל\"ב ח\"ב ע' תמא."],["1063","6","<b>כמשל שבלבנה קודם המולד היא נקודה תחת היסוד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370265\" data-slug=\"torah-or\" data-id=\"3901370265\">תו\"א וארא נט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">תצוה פה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380324\" data-slug=\"likkutei-torah\" data-id=\"4001380324\">לקו\"ת פקודי ז, א</a> (בשם הע\"ח). במדבר ד, א. יט, ד. סה\"מ תרכ\"ז ע' קכד. תרל\"ג ח\"א ע' רמח. רנ. ובכ\"מ."],["1064","7","<b>ולכך צריכים לשאת אותם בכתף</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380382\" data-slug=\"likkutei-torah\" data-id=\"4001380382\">לקו\"ת במדבר יח, ג</a>. דרמ\"צ מב, ב. סה\"מ תרכ\"ז ע' מו. רצה. שצב. תסד."]]],[2002180334,"אחור באחור ואח\"כ ע\"י תשובה נתקרבו וכמ\"ש ואנכי עמדתי בהר כימים הראשונים מה הראשונים ברצון אף האחרונים ברצון.\n<b>ובפרט</b> כמו שבלבנה יש כ\"ח עתים כמו\"כ בישראל הי' כ\"ח עתים בימי שפוט השופטים ובימי יהושע ובכלל מיצ\"מ עד אחר ב\"ר הי' בבחי' פב\"פ, ואח\"כ היו בבחי' אב\"א, וע\"י תשובה לאחר ע' שנה הי' בית שני, ואח\"כ נתרחקו והריחוק הוא בשביל הקירוב וכמ\"ש גדול יהי' כבוד הבית הזה האחרון מן הראשון שהבית דלעתיד יהי' עוד גבוה יותר, דהעיקר הוא בשביל הקירוב וכמ\"ש בצר לך ומצאוך [ובקשתם משם], והריחוק הוא כמ\"ש כי פנו אלי עורף ולא פנים, אפי' מה שפנה אלי הוא רק בבחי' עורף, דעיקר הרצון הוא בתאוות זרות רק שמוכרח להתפלל ומוכרח ללמוד תורה מעט. ובכלל הוא ההפרש בין אתכפייא לאתהפכא, והוא חפץ ורצון הוא שבפנימיות הוא רוצה תאוות זרות ובחיצוניות יש לו רצון לאלקות ג\"כ, וחפץ הוא שעיקר חפצו ומגמתו אפי' בפנימיות הוא רק לאלקות וזהו אתהפכא. מ\"מ גם כי פנה אלי כו' הוא מל' פנים דעי\"ז יכולים לבוא לבחי' פנים, וזהו\"ע הריקוד שהוא כנגד ששייך בו ריחוק וקירוב.\n<b>והנה</b> יש עוד אופן ריקוד שהוא במחול הנק' בל\"א קראהאד שאינו שייך בו ריחוק והוא משארז\"ל עתיד הקב\"ה לעשות מחול לצדיקים לע\"ל<sup data-n=\"1065\">8</sup> שהוא שיתקרבו לאלקות ואינו שייך שם ריחוק כלל. ובד\"כ ההפרש הוא בין ממכ\"ע לסוכ\"ע, דהנה בממכ\"ע יש שינויים כמו ראש גוף רגל מעלה ומטה שיש בו התחלקות, דאפי' מי שהוא עובד ובשעת התפלה הוא מקושר לאלקות מ\"מ לאחר התפלה חולף ועובר, דבממכ\"ע יש שינויים והתחלקות ושייך שם פנים ואחור, ולכן כל חושים המעולים הם בפנים, וסוכ\"ע שם אינו שייך התחלקות כלל ולא פנים ואחור וזהו\"ע ראש מחול שמאיר הארת הסוכ\"ע.\n<b>וזהו</b> אז תשמח בתולה במחול, אז הוא א' על ז'<sup data-n=\"1066\">9</sup>, שמא' נמשך בז' והוא מספר ח' וכמארז\"ל כינור שלעתיד של ח' נימין<sup data-n=\"1067\">10</sup>, דשל בהמק\"ד של ז' נימין שהוא כסדר המדריגות והוא בחי' ממכ\"ע וכמו ז' ימי בראשית, אך כינור שלעתיד הוא של ח' נימין הוא הארת סוכ\"ע, וזהו אז היינו כשיאיר הארת אוא\"ס הסוכ\"ע תשמח שיהי' גילוי השמחה וכמ\"ש ישמח ישראל בעושיו, שמח לא נאמר<sup data-n=\"1068\">11</sup> אלא ישמח עתידים ישראל לשמוח, וכן על למעלה כתי' ישמח ה' במעשיו שמח לא נאמר אלא ישמח עתיד",[["1065","8","<b>והוא משארז\"ל עתיד הקב\"ה לעשות מחול לצדיקים לע\"ל</b>: ראה גם לקו\"ת ואתחנן ז, ב. ובכ\"מ."],["1066","9","<b>אז הוא א' על ז'</b>: ראה גם לקו\"ת שמע\"צ פח, ב. סה\"מ תרכ\"ט ע' קנ. תרל\"ב ח\"א ע' קמא. וש\"נ."],["1067","10","<b>וכמארז\"ל כינור של עתיד של ח' נימין</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380167\" data-slug=\"likkutei-torah\" data-id=\"4001380167\">לקו\"ת תזריע כא, ד</a>. אוה\"ת חנוכה שכו, ב ואילך. סה\"מ תרכ\"ז ע' קד. תרכ\"ט ע' יד. תרל\"ב ח\"א ע' קמא. סה\"מ תרח\"ץ ס\"ע קפב ואילך. לקו\"ש ח\"ג ע' 812. וש\"נ."],["1068","11","<b>וכמ\"ש ישמח ישראל בעושיו שמח לא נאמר</b>: ראה גם סה\"מ תרל\"ב ח\"ב ע' תקמב. תרל\"ג ח\"א ע' רנד. רסח. ובכ\"מ."]]],[2002180335,"הקב\"ה לשמוח במעשיהם, ואז יהי' גילוי השמחה במחול היינו שיהי' קירוב, וריחוק לא יהי' עוד. ומ\"ש בתולה, הנה כתי' בתולה ואיש לא ידעה כמו שיש איש בקדושה וכמ\"ש ה' איש מלחמה והוא מדרי' גבוה שהוא אש יו\"ד כמו\"כ יש איש בלעו\"ז שהוא איש יודע ציד איש שדה, איש מדנים, איש תהפוכות, הוא שמהפך מקדושה לסט\"א, איש מדון הוא כמ\"ש ונרגן מפריד אלוף, וכשאיש לא ידעה תשמח במחול. ומ\"ש בתולה דוקא, דזכר צ\"ל מילה שהוא מ\"ש ומלתם את ערלת לבבכם, דטמטום הלב הוא שהלב אטום מלקבל דבר חכ' והוא ערלת הלב וצריכים לימול ערלת הלב וזהו\"ע מילה, והנה מילה הוא בשמיני דתחילה צ\"ל ז' ימים שהם כסדר המדרי' ז' ימי בראשית ואח\"כ כשיעבור עליו שבת<sup data-n=\"1069\">12</sup> היינו שיאיר בו הארת סוכ\"ע שהוא ע\"י שבת אותיות תשב אז ומל הוי' אלקיך את לבבך, מל ל' גילוי שמאיר בו הארת הסוכ\"ע, אבל איתתא כמאן דמהילא דמי ומיד כשנולדה אפשר להאיר בה הארת אוא\"ס. וזהו אז תשמח בתולה במחול, בתולה דכמאן דמהילא דמי ומאיר בה בחי' אז שהוא הארת סוכ\"ע, תשמח במחול היינו שיהי' קירוב ולא יהי' עוד ריחוק כלל וכלל.",[["1069","12","<b>והנה מילה הוא בשמיני . . כשיעבור עליו שבת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380164\" data-slug=\"likkutei-torah\" data-id=\"4001380164\">לקו\"ת תזריע כא, א</a>. סה\"מ תרכ\"ט ע' יב. וש\"נ. תרל\"ב ח\"א ע' קמא. סה\"מ מלוקט ח\"ה ע' טו ואילך וע' רלח. וש\"נ."]]],[2002180336,"<h3>ברזל בברזל יחד (ש\"פ הנ\"ל)</h3>\n<b>ש\"פ הנ\"ל</b>\n<b>ברזל</b> בברזל יחד<sup data-n=\"1070\">1</sup> ואיש יחד פני רעהו, ברזל הוא כמ\"ש ארץ אשר אבני' ברזל ואמרז\"ל כל ת\"ח שאינו קשה כברזל<sup data-n=\"1071\">2</sup> אינו ת\"ח א\"ת אבני' אלא בוני', דת\"ח נק' בונים, וצ\"ל ברזל, וגם בברזל יחד שהוא ושננתם שינון דשני ת\"ח שעוסקים ומחדדין זה את זה בהלכה וזה מקשה וזה מתרץ יוצא חידוש דין. וזהו שנים שיושבים ועוסקים בתורה שכינה שרוי' ביניהם ומנין אפי' אחד שהקב\"ה קובע לו שכר ופי' רבינו ז\"ל דאחד הקב\"ה קובע כו'<sup data-n=\"1072\">3</sup> הוא לבוש הנעשה ע\"י לימוד התורה משפיעים לו הארת אוא\"ס בכדי שיוכל לקבל בפנימיות, אבל שנים כו' שרוי' ביניהם הוא כמאמר אכל בי' עשרה שכינתא שריא שהוא בחי' מקיף שאינו יכול להאיר בפנימיות, דמה שאפשר לימשך בפנימיות נמשך בפנימיות ומה שא\"א להאיר בפנימיות נשאר בבחי' מקיף, וזהו\"ע ושננתם.",[["1070","1","<b>ברזל בברזל יחד</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מן הנדפס לעיל ע' תפז [בתוך ד\"ה ושננתם לבניך] וע' תצג ואילך."],["1071","2","<b>ואמרז\"ל כל ת\"ח שאינו קשה כברזל</b>: כ\"ה בגמ' תענית ד, א. ושם ז, א: מאי דכתיב ברזל בברזל יחד לומר לך מה ברזל זה אחד מחדד את חבירו אף שני תלמידי חכמים מחדדין זה את זה בהלכה. וראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600632\" data-slug=\"or-hatorah-hb\" data-id=\"8316600632\">אוה\"ת ואתחנן ע' שי</a> ואילך. וראה גם אוה\"ת נ\"ך (כרך א) ע' תרלב-ג. סה\"מ תרנ\"ט ע' סא, ובהוספות ע' רטז."],["1072","3","<b>ופי' רבינו ז\"ל דאחד הקב\"ה קובע כו'</b>: תניא אגה\"ק סכ\"ג (קלו, א)."]]],[2002180337,"<b>ולהבין</b> זה הנה כתי' ואהי' אצלו אמון שעשועים יום יום, שהתורה היא כלי אומנתו של הקב\"ה דאסתכל באורייתא וברא עלמא, דכדי שיהי' מא\"ס הבבע\"ג עולמות נבראים מוגבלים שאין ערוך כלל, ואפי' עולם האצי' הוא עולם ל' העלם. וצ\"ל מה שייך אצי' שהוא אצלו וסמוך מה שייך לומר העלם, ואפי' להפי' דאצי' הוא הפרשת הארה מאלקות מה שייך שיאמר עליו כי הוא העלם. והענין שהוא כמו אלוקה געטלעך, הרי הוא אלקות ומ\"מ מאחר שנופל עליו שם אלוקה ה\"ה העלם, וכמו\"כ עולם האצי' הוא העלם (ע' בד\"ה וככה (לז) ערך פע\"ב שאצי' הוא אלוקה לכן נק' העלם<sup data-n=\"1073\">4</sup>), וכדי שיתהווה זה מאוא\"ס צ\"ל ממוצע וזהו\"ע התורה שהיא ממוצע בין מאציל לנאצלים, וידוע שממוצע צ\"ל כלול מב' מדרי' וזהו\"ע תושב\"כ ותושבע\"פ, תושב\"כ העיקר האותיות שבהם מלובש חכ' הנעלמה ולכן אותיות ותמנע היתה פלגש שוים עם מ\"ש וידבר ה'<sup data-n=\"1074\">5</sup> אל משה לאמר, ותושבע\"פ הוא כמאמר מל' פה תושבע\"פ קרינן לה שהוא מקור הנבראים.\n<b>והנה</b> בתושב\"כ ותושבע\"פ גופא יש ב' מדריגות<sup data-n=\"1075\">6</sup>, והוא מ\"ש ועל תורתך שלמדתנו, שיש תורתך תורה שלמעלה<sup data-n=\"1076\">7</sup> אינו כמו תורה למטה שמלובש בדברים גשמיים ציצית בצמר גשמי תפילין בקלף גשמי שנים אוחזין בטלית הלכות גשמיים, אבל למעלה היא באופן אחר. וענין ושננתם הוא לחבר ב' בחי' אלו<sup data-n=\"1077\">8</sup>, וכמו מ\"ט אמר קרא וזה מדייק כן וזה מדייק כן, והיינו שממשיכים מתושב\"כ לתושבע\"פ, וכן לחבר ב' בחי' תורה שלמעלה עם תורה שלמטה, וזהו ביום חתונתו זו מ\"ת כמו חתונה הוא יחוד חו\"כ ועי\"ז נולד דבר חדש מה שלא הי' תחילה כך ע\"י יחוד וחבור תושב\"כ ותושבע\"פ נולד דין חדש. ולא זו בלבד אלא שעי\"ז נתוסף הארת אוא\"ס בח\"ע מה שלא הי' תחילה, וכמאמר יפה כח הבן מכח האב<sup data-n=\"1078\">9</sup>. הנה אומרו כח הנה מובן שיש כח ופועל וההפרש הוא, כח הוא העלם ופועל גילוי, וקאמר יפה כח הבן מכ\"ח כו' מובן שיש בבן מה שלא יש אפי' בהעלם האב, ומאין זה בהבן. וע\"פ פשוט אפ\"ל שהוא",[["1073","4","<b>ע' בד\"ה וככה (לז) ערך פע\"ב שאצי' הוא אלוקה לכן נק' העלם</b>: ראה המשך וככה תרל\"ז פע\"ח (התחלת הביאור שם בענין עולמות אצי' ובי\"ע הוא שם בפע\"ב), וז\"ל שם: ואמנם קריאת שם אלקות על עולם האצי' ה\"ה אינו כמו קריאת שם הבורא שנק' אלק', שיש הבדל רב בין מה שהבורא נק' אלק' ובין מה שאצי' נק' אלקות, שענין קריאת שם אלק' שנק' הבורא היינו לפי שהוא יחיד ומיוחד וברא הכל ויצר הכל ועשה הכל ואצל אצי' העליון שהוא התפשטות הארתו כו'. ע\"ש. וראה גם דרמ\"צ מח, א. מט, ב. סה\"מ תרל\"ג ח\"ב ע' תקג וע' תקו. [ובהמ\"מ שם]."],["1074","5","<b>ולכן אותיות ותמנע היתה פלגש שוים עם מ\"ש וידבר ה'</b>: ראה גם לקמן בהנחת חסיד של מאמר זה. וש\"נ."],["1075","6","<b>והנה בתושב\"כ ותושבע\"פ גופא יש ב' מדריגות</b>: מכאן ואילך מיוסד על המאמר לעיל ע' תצג ואילך."],["1076","7","<b>והוא מ\"ש ועל תורתך שלמדתנו שיש תורתך תורה שלמעלה</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380783\" data-slug=\"likkutei-torah\" data-id=\"4001380783\">לקו\"ת עקב יז, ב</a>. דרושים לחה\"ס פא, ד. סה\"מ תרל\"ד ע' רעח. וש\"נ. ה'ש\"ת ע' 68. וש\"נ."],["1077","8","<b>וענין ושננתם הוא לחבר ב' בחי' אלו</b>: בהבא לקמן, ראה אוה\"ת ואתחנן ע' שי ואילך."],["1078","9","<b>וכמאמר יפה כח הבן מכח האב</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370324\" data-slug=\"torah-or\" data-id=\"3901370324\">תו\"א יתרו עג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231222\" data-slug=\"likkutei-sichot\" data-id=\"1300231222\">לקו\"ש חכ\"ג ע' 222</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261182\" data-slug=\"likkutei-sichot\" data-id=\"1300261182\">חכ\"ו ע' 182</a>. חל\"ט ע' 125. וש\"נ."]]],[2002180338,"מצד שהקב\"ה נותן בו נשמה<sup data-n=\"1079\">10</sup>, ע\"ז אינו שייך לומר בן, וצ\"ל שהוא מחלק אב ואם, והאיך זה. אלא שלצורך ההשפעה נמשך מהאב כח שאין הגילוי בהאב כ\"א בהבן, כמו\"כ בתורה ע\"י חידוש דין נמשך אור חדש בח\"ע. ואפשר להבין זה ממ\"ש המחדש בטובו בכל יום ובכל עת ובכל שעה נמשך חיות חדש, דבי\"ב שעות היום מאיר י\"ב צירופי הוי'<sup data-n=\"1080\">11</sup> ובכל שעה מאיר צירוף חדש, ואינו שייך לומר שהוא במדריגה א' אלא שבכל שעה מאיר צירוף גבוה במעלה יותר והוא שנתחדש בכ\"י, וזהו בזיווג חיצוני דחו\"ב ומכ\"ש תושב\"כ ותושבע\"פ שהוא יחוד פנימי דחו\"ב שנתחדש בח\"ע מה שלא הי' תחילה, והגם שנת\"ל דתושבע\"פ הוא מל' אך פעמים מפרשים שהוא בינה. ועפ\"ז יובן דהלא נשמות שיושבין בג\"ע יותר מג' אלפי' שנה ולומדים תורה מה הם לומדים ושם אינו שייך שיתוסף. אך הענין הנה אי' בתניא ונהנים מזיו תורתן ועבודתן<sup data-n=\"1081\">12</sup>, והיינו דע\"י לימוד התורה בעוה\"ז המשיכו אור חדש בח\"ע, וזה הם לומדים בג\"ע שנמשך מהמקור, וזהו\"ע ושננתם שהו\"ע שינון שעי\"ז ממשיכים מהמקיף, וזהו שנים שיושבין ועוסקין בתורה שכינה שרוי' ביניהם שהוא בחי' מקיף ואומרו ביניהם משמע שהמקיף נמשך בפנימי ג\"כ.\n<b>ואח\"כ</b> כתי' ודברת בם<sup data-n=\"1082\">13</sup> בשבתך בביתך ובלכתך בדרך, ענין ביתך הנה כתי' גדול הוי' ומהולל מאד בעיר אלקינו<sup data-n=\"1083\">14</sup> אימתי הוא גדול כשהוא בעיר אלקינו, דאותיות הם כמו אבנים וזהו שהם דוממים שאין שייך בהם צמיחה, שתי אבנים בונים שתי בתים, שלשה אבנים בונים שלשה בתים, ומקיבוץ אבנים הרבה נעשה בית, ומקבוץ בתים הרבה נעשה עיר, וצריכים להמשיך מש' הוי' לעיר אלקינו, וזהו ודברת בם מל' ידבר עמים תחתינו שהוא ל' הנהגה והמשכה<sup data-n=\"1084\">15</sup>.\n<b>והנה</b> אמרז\"ל ודברת בם ולא בתפלה, וצ\"ל והלא תפלה היא מדריגה גבוה ולמה ולא בתפלה. והענין דהנה תפלה העיקר בחשאי ותורה בדיבור וכמו שאם ערוכה בכל שמורה, אם ערוכה ברמ\"ח אברים שמורה, שכל הרמ\"ח ידברו פי' שיתנענעו. והענין דהנה כתי' במ\"ת וידבר אלקים את כל הדברים האלה לאמר וצ\"ל מהו\"ע ב' פעמים והול\"ל וידבר לו, או ויאמר אלקים כו'. אך הענין דהנה יש ב'",[["1079","10","<b>וע\"פ פשוט אפ\"ל שהוא מצד שהקב\"ה נותן בו נשמה</b>: ראה גם ס' מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' נד וע' רח. סה\"מ תרל\"ב ח\"ב ע' תצה. ובכ\"מ."],["1080","11","<b>דבי\"ב שעות היום מאיר י\"ב צירופי הוי'</b>: ראה בהמ\"מ לעיל בהמאמר ע' תצג."],["1081","12","<b>אך הענין הנה אי' ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא</a> ונהנים מזיו תורתן ועבודתן</b>: פל\"ט (נב, ב): הנשמות כו' עומדות בהיכלות ומדורין דבריאה או יצירה ונהנין מזיו השכינה הוא אור א\"ס ב\"ה המיוחד בי\"ס דבריאה או דיצירה והוא זיו תורתן ועבודתן ממש [ע' זהר ויקהל דר\"י] כי שכר מצוה היא מצוה עצמה."],["1082","13","<b>ואח\"כ כתי' ודברת בם</b>: בהבא לקמן ראה אוה\"ת ואתחנן ע' שיב."],["1083","14","<b>הנה כתי' גדול הוי' ומהולל מאד בעיר אלקינו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370103\" data-slug=\"torah-or\" data-id=\"3901370103\">תו\"א ויצא כא, א</a>. כב, א. ובכ\"מ."],["1084","15","<b>וזהו ודברת בם . . ל' הנהגה והמשכה</b>: ראה אוה\"ת ואתחנן שם ע' שיב. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380218\" data-slug=\"likkutei-torah\" data-id=\"4001380218\">לקו\"ת אמור לג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380834\" data-slug=\"likkutei-torah\" data-id=\"4001380834\">ואתחנן ב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381019\" data-slug=\"likkutei-torah\" data-id=\"4001381019\">ט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381197\" data-slug=\"likkutei-torah\" data-id=\"4001381197\">ראה כט, ג</a>. האזינו עד, א. שה\"ש יז, א."]]],[2002180339,"מדריגות דיבור ואמירה<sup data-n=\"1085\">16</sup>, וההפרש דיבור הוא כשא' דובר בפנימיות מה שנוגע לו, ואמירה הוא כשאמר ואינו נוגע למעשה בל\"א זאגט זיך, ובד\"כ הוא ההפרש בין עשרה מאמרות ועשרת הדברות, ע\"מ נאמר לשון מאמרות דלאו אורחי' דמלכא לאשתעי במילין דהדיוטא דאינו תופס מקום כלל, ועה\"ד הוא בבחי' דבר, דבתורה צ\"ל בדיבור, וזהו שארז\"ל קול ה' בכח הוא תורה<sup data-n=\"1086\">17</sup>, וזהו שארז\"ל וענו הלוים ואמרו בקול רם<sup data-n=\"1087\">18</sup>.\n(ע\"כ נרשם בגוכי\"ק, וחסר סיום)",[["1085","16","<b>דהנה יש ב' מדריגות דיבור ואמירה</b>: ראה במ\"מ לעיל במאמר ס\"ע תצד."],["1086","17","<b>וזהו שארז\"ל קול ה' בכח הוא תורה</b>: ראה במ\"מ לעיל שם."],["1087","18","<b>ואמרו בקול רם</b>: ראה המשך הענין לעיל במאמר ר\"ע תצה ואילך. ולקמן בהנחות ד\"ה זה (פיסקא: ”והנה רז\"ל דרשו\" ואילך)."]]],[2002180340,"<h3>כרע שכב (ש\"פ שופטים)</h3>\n<b>ש\"פ שופטים טל, לפ\"ק</b>\n<b>כרע</b> שכב כארי<sup data-n=\"1088\">1</sup> וכלביא מי יקימנו, ואמרז\"ל בקשו לקבוע פ' בלק בק\"ש דכאן נא' שכב ובפ' ק\"ש נא' ובשכבך, וצ\"ל מה שייך זה לק\"ש, גם צ\"ל דהנה גבי יעקב כתי' כרע רבץ כארי וצ\"ל ההפרש בין כרע רבץ לכרע שכב. והענין דהנה בזמן שבהמק\"ד קיים זהו כרע רבץ והו\"ע ארי' דאכיל קורבנין, ובזמן שאין בהמק\"ד זהו כרע שכב, דהנה שכיבה גורם שינה כמ\"ש וישכב וירדם, ושינה הוא משל לגלות<sup data-n=\"1089\">2</sup> כמו בעת השינה הנה יש כל הכחות ראי' שמיעה טעם השגת המוחין רק שהם בהעלם וכידוע מענין החלומות דאפשר להרכיב ב' ענינים נפרדים ואינם מורכבים ע\"פ השכל כלל והיינו מפני שהשכל הוא בהעלם, וכמו\"כ ענין הגלות הגם שנמשך כל ההמשכות אך אינם מאירים בגילוי וכמ\"ש אותותינו לא ראינו, הגם דכתיב לעושה נפלאות גדולות לבדו אין בעל הנס מכיר בניסו הרי נמשך המשכת אלקות שיהי' נסים ג\"כ, אך אינו מאיר בגילוי שהוא מוסתר ונעלם. וזהו מ\"ש אני ישנה ולבי ער, אני ישנה בגלותא, דגלות נמשל לשינה כמו בעת השינה כל הכחות מוסתרים ונעלמים כמו\"כ בזמן הגלות המשכת אלקות הוא מוסתר ונעלם, ולבי ער לבי זה הקב\"ה וכמ\"ש צור לבבי וחלקי אלקי' לעולם ופי' בזהר למה נק' הקב\"ה לב כמו הלב הוא פליג לכל שייפין כמו\"כ אוא\"ס הוא מקור סוכ\"ע וממכ\"ע ונמשך בכל עולם",[["1088","1","<b>כרע שכב כארי</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה ובשכבך ובקומך, הנדפס לעיל ע' תצו. וע\"ש בהמ\"מ בתחילת המאמר."],["1089","2","<b>ושינה הוא משל לגלות</b>: ראה בהמ\"מ לעיל ע' תצו שם."]]],[2002180341,"ועולם לפי ערכו. והנה במדריגה זו אינו שייך שום שינה וכמ\"ש הנה לא ינום ולא יישן שומר ישראל, וזהו\"ע יוחנן כה\"ג ביטל את המעוררים<sup data-n=\"1090\">3</sup> ואת הנוקפים וכי יש שינה לפני המקום, דהנה שורש המקום הוא המדות וכמ\"ש כי אמרתי עולם חסד יבנה, וגם סדר זמנים הוא מדות, והנה במדות שייך שינה דמאחר דשייך שם שינוי שייך שם שינה ג\"כ, אבל לפני המקום היינו שלמעלה משרש מקום וזמן שם אינו שייך שינה כלל.\n<b>והנה</b> בעבודה יש ג\"כ ענין אני ישנה ולבי ער, דהנה כאשר יתבונן האדם איך דאני הוי' לא שניתי שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה, אתה הוא קודם שנבה\"ע ואתה הוא לאחר שנבה\"ע, והי' צריך ליכלל וליבטל באוא\"ס ולהמשיך גילוי אוא\"ס למטה כמו למעלה, ואינו נמשך בגילוי. דהנה ממכ\"ע הוא מובן בהשגה ואינו שייך לדרוש מאדם שיהי' לו השגה בעולם יותר מההשגה בעצמו, שהוא כשרואה שהוא חי מבין שיש חיות המחי' אותו, וכמו\"כ בעולם שהוא גוף גדול ורואין שכל דבר הוא חי יודעין שיש חיות אלקי המחי' אותו, אבל סוכ\"ע אינו מושג כלל. וזהו אני ישנה ולבי ער הוא רעותא דליבא פנימיות הלב, יש בכאו\"א מישראל, והו\"ע אהבה מוסתרת הגם שהיא מוסתרת מ\"מ ישנה בכל אחד ואחד מישראל. וזהו כרע שכב כארי, אפי' בזמן ששכב היינו בזמן הגלות מ\"מ כארי, וכמו ארי הוא מלך שבחיות והוא גבור וכמו גבור כארי, הנה בעת שהוא רובץ ניכר גבורתו אבל בעת שהוא ישן אינו ניכר גבורתו, מ\"מ מפני שם ארי' שיש עליו יראים להגיש אליו, כמו\"כ כאן אפי' בעת הגלות מ\"מ נמשך לאגנא עלייהו. דהנה בזמן שבהמק\"ד קיים הנה כתי' וישכון ישראל בטח בדד עין יעקב, עין יעקב הם נביאים<sup data-n=\"1091\">4</sup> ובהם יש מדריגות אספקלרי' המאירה ואספקלרי' שאינה מאירה ומ\"מ ה\"ז גילויים, אבל עכשיו אותותינו לא ראינו אין עוד נביא שלא יש גילוים כלל, רק שנמשך לאגנאה עלייהו. וזהו בשכבך שהו\"ע ך\"ב אותיות התורה, דישכב הוא יש ך\"ב, שע\"י ך\"ב אותיות התורה נמשך לאגנאה עלייהו.\n<b>ואח\"כ</b> כתי' ובקומך וזהו קאי על לעתיד, דהנה כתי' נפלה ולא תוסיף קום בתולת ישראל, וצ\"ל והלא כתי' ביום ההוא אקים<sup data-n=\"1092\">5</sup> את סוכת דוד הנופלת, ותי' בזהר שלא יהי' עוד קימה מעצמו. והענין דהנה כל הגליות היו על זמן, כמו על ע' שנה הי' זמן שכיבה זמן שינה, ואחר ע' שנה בא זמן הקימה והי' הקימה מעצמו ושייך בה שינויים, אבל לעתיד שיהי' אקים ע\"י הקב\"ה לא יהי' שינויים (ע' בד\"ה וככה ט\"ל<sup data-n=\"1093\">6</sup>),",[["1090","3","<b>וזהו\"ע יוחנן כה\"ג ביטל את המעוררים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370418\" data-slug=\"torah-or\" data-id=\"3901370418\">תו\"א צג, א</a>. ובכ\"מ."],["1091","4","<b>וישכון ישראל בטח בדד עין יעקב, עין יעקב הם נביאים</b>: ראה אוה\"ת ברכה (כרך ו) ע' ב'תקנט (ע\"פ שמו\"ר פל\"ח)."],["1092","5","<b>דהנה כתי' נפלה ולא תוסיף קום בתולת ישראל . . ביום ההוא אקים</b>: ראה בכ\"ז אוה\"ת בלק ע' א'מט. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380863\" data-slug=\"likkutei-torah\" data-id=\"4001380863\">לקו\"ת תצא לו, ג</a>."],["1093","6","<b>ע' בד\"ה וככה ט\"ל</b>: לעיל ח\"א ע' קלח ואילך, וע\"ש בהמ\"מ."]]],[2002180342,"וזהו נפלה ולא תוסיף שלא יהי' עוד נפילה, דכל הגליות היו קום היינו קימה מעצמו אבל לעתיד שיהי' אקים לא יהי' עוד נפילה. וזהו ובקומך שהוא קאי על מ\"ש גדול יהי' כבוד הבית הזה האחרון מן הראשון.\n<b>אך</b> הנה כ\"ז כמו עכשיו שתלמוד גדול שמביא לידי מעשה<sup data-n=\"1094\">7</sup>, אבל לעתיד יהי' מעשה גדול. וזהו\"ע פ' שני' דק\"ש שבה מרומז ממ\"ת עד לעתיד, והי' אם שמוע תשמעו הוא מ\"ת, השמרו לכם פן כו' וחרה אף הוא העונש לזה, ואח\"כ ושמתם דסוף כל סוף כאו\"א יבוא לתשובה, אך סיבה הגורמת לזה, לזה באופן זה ולזה באו\"א, אבל כאו\"א יעשה תשובה, וכאן תחילה וקשרתם שהוא מצות ואח\"כ ולמדתם שהוא תורה. והענין דהנה על לעתיד כתי' אשת חיל עטרת בעלה וכתי' והי' ביום ההוא יצאו מים חיים מירושלים חצים אל ים הקדמוני, ירושלים הוא יראה שלם בחי' מל' והו\"ע מצות המלך, וים הקדמוני הוא ים החכ', ויומשך ממעשה המצות לים הקדמוני. דהנה עכשיו ראשית הגילוים הוא מחכ' שהוא ראשית השתל' אבל מלמעלה מחכ' היינו מבחי' כתר שהוא כותרת ומקיף אינו נמשך למטה, ולעתיד יומשך מבחי' כתר ויומשך ע\"י בחי' מל' שהו\"ע מעשה המצות, דכתר עליון הוא כתר מל', ובכהאריז\"ל אי' ג\"כ דמל' שרשה ברדל\"א<sup data-n=\"1095\">8</sup>, וזהו\"ע סיג לחכ' שתיקה פי' סיג הוא גדר, גדר לחכ' הוא בבחי' שתיקה פי' שאינו נמשך למטה, אבל לעתיד יאיר ויתגלה בחי' כתר.\n<b>וביאור</b> הענין דהנה כתי' מכון לשבתך<sup data-n=\"1096\">9</sup> פעלת ה' ואמרז\"ל גדול מה שנא' במקדש ממה שנא' במע\"ב, דבמע\"ב כתי' ויאמר אלקים הכל בל' אמירה, ובמקדש נא' ל' פעולה ועשי'. דהנה אנו רואין על ריבוי הטוב וההשפעה נא' ל' פעולה ועשי' כמו מה רב טובך אשר צפנת ליראיך פעלת לחוסים בך, דעכשיו הוא רק זכר רב טובך אבל כדי שיומשך בחי' רב טובך וכמ\"ש רב טוב לבנ\"י והו\"ע צפנת בגימטריא כתר נא' בו פעולה, וכן כתי' עדן עין לא ראתה אלקי' זולתך יעש\"ה למחכה לו, וכן כאשר השמים החדשים והארץ החדשה אשר אני עוש\"ה עומדים לפני. וצ\"ל והלא כתי' כל הנק' בשמי ולכבודי בראתיו יצרתיו אף עשיתיו ואף הוא הפסיק הענין, ר\"ל שאין ערוך עשי' ליצי' יותר משאין ערוך יצי' לגבי' בריאה, דהנה בריאה הוא עולם המח' עולם הנשמות ויצי' הוא עולם הדיבור עולם המלאכים, ועז\"נ יוצר אור ובורא חשך, בריאה לעוצם מעלתו הוא חשך ויצי' מגלה העלם הבריאה, והו\"ע חומר וצורה שהצורה מגלה העלם החומר, וכמו דיבור ומח' הדיבור מגלה העלם המח', אבל מעשה לגבי דיבור אין ערוך כלל, הרי שעשי' פחות במעלה מדיבור. אך הנה באמת הם ב' ענינים ואינם סותרים זל\"ז.",[["1094","7","<b>אך הנה כ\"ז כמו עכשיו שתלמוד גדול שמביא לידי מעשה</b>: בהבא לקמן ראה אוה\"ת ואתחנן ס\"ע רמז ואילך."],["1095","8","<b>ובכהאריז\"ל אי' ג\"כ דמל' שרשה ברדל\"א</b>: ראה לעיל בהמאמר ע' תצח בשם המק\"מ. ובהמ\"מ לשם."],["1096","9","<b>וביאור הענין דהנה כתי' מכון לשבתך</b>: בהבא לקמן ראה אוה\"ת ואתחנן שם ע' רמט וע' רנא."]]],[2002180343,"<b>והענין</b> דהנה במעשה יש כחות פנימים יותר מבדיבור, וכמו דיבור האדם הוא מהבל הלב נמשך לדיבור והנה הוא רק הארה, וכמו\"כ למעלה הנה אמרז\"ל לא בעמל ויגיעה ברא הקב\"ה את עולמו כ\"א במאמר וברוח פיו, בעשרה מאמרות נבה\"ע, וכתי' בהבראם בה' בראם אתא קלילא דלית בי' מששא, אבל במעשה יש כחות עצמיים, וכמו למטה באדם כשאומר איזה דבר הוא רק שאומר, בל\"א ער זגט זיך, אבל [לעצמיות] אינו נוגע אבל כשעושה יש בזה כחות עצמיים, ולכן לאו שאין בו מעשה אין לוקין עליו הגם שדיבר אין זה כלום<sup data-n=\"1097\">10</sup>, וכן מעשה רב הגם שפסק ההלכה מ\"מ מעשה רב, דמה שפסק הלכה כא' היינו דאלו ואלו דברי אלקים חיים ומ\"מ למעשה צריכים לעשות באופן אחר, וכמו ב\"ש וב\"ה הלכה כב\"ה<sup data-n=\"1098\">11</sup> בכ\"מ ומ\"מ לומדים גם דברי ב\"ש וקודם לדברי ב\"ה ומ\"מ ההלכה היינו ההילוך בזה העולם וכמ\"ש הליכות עולם לו והיינו עבודת הבירורים צ\"ל כב\"ה דוקא, והיינו דאלו ואלו דא\"ח שהוא בחי' בינה, מ\"מ הלכה שהוא י' דש' הוי' שהו\"ע הלכה כמותו בכ\"מ הוא כב\"ה, וזהו\"ע מעשה שיש בזה כחות עצמיים יותר, ולמעלה הו\"ע הקב\"ה מניח תפילין הוא המשכת מוחין לז\"א הוא המשכה פנימיות. ואינו סותר למ\"ש אף עשיתיו, ששם כוונה אחרת. דהנה אנו רואין כשאדם צריך לעשות איזה דבר תחילה הוא ברק המבריק וגם הוא עצמו אינו יודע עדיין וצריכים להתלבש בלבוש המח' עד שיבין את הדבר ואח\"כ נעשה מדה ואח\"כ בא לדיבור וקודם לדיבור צ\"ל מח', דמח' הנ\"ל היא גילוי העלם עצמי וגילוי עצמי ומח' זו הוא איך לדבר ואח\"כ עושה אותה, והנה מח' הוא רק לעצמו ודיבור הוא לזולתו ג\"כ, דדיבור הוא מחבר עצמיות עם זולת ומעשה הוא<sup data-n=\"1099\">12</sup>.\n(ע\"כ נרשם בגוכי\"ק, וחסר סיום)",[["1097","10","<b>ולכן לאו שאין בו מעשה אין לוקין עליו הגם שדיבר אין זה כלום</b>: ראה גם לקו\"ת שמע\"צ פד, ג (מגמ' ב\"מ צ, ב ועוד)."],["1098","11","<b>וכמו ב\"ש וב\"ה הלכה כב\"ה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830237\" data-slug=\"or-hatorah-hb\" data-id=\"8158830237\">אוה\"ת בלק ע' תתקכג</a>. תתקלט. סה\"מ תרכ\"ז ע' שז וע' שיד. ובכ\"מ."],["1099","12","<b>ומעשה הוא</b>: לא נרשם יותר בגוכי\"ק. וראה המשך הענין לעיל בהמאמר ס\"ע תצט ואילך: שהמעשה הוא סוף ההשתלשלות כו'."]]],[2002180344,"<h3>ולא אבה (ש\"פ תצא)</h3>\n<b></b><b>ש\"פ תצא טל לפ\"ק (ביאור על ד\"ה ולא אבה שבלקו\"ת)</b>\n<b>ולא</b> אבה<sup data-n=\"1100\">1</sup> ה' אלקיך לשמוע אל בלעם ויהפוך ה' אלקיך לך את הקללה לברכה כי אהבך ה' אלקיך. הנה כתיב כאן ג\"פ ה' אלקיך, א' ולא אבה ה' אלקיך, ב' ויהפוך ה' אלקיך, ג' כי אהבך ה' אלקיך. וצ\"ל מה\"ע הג\"פ ה' אלקיך. ועוד צ\"ל מה\"ע ויהפוך ה' מאחר דלא אבה לשמוע, כששומעין שייך שמהפכין אח\"כ, אבל כשאינו שומעין לכתחילה מה שייך לומר ויהפוך. והענין דהנה יש מקטרגים שמקטרגים על כללות נש\"י ומלמדים חובה עליהם, וזהו\"ע תקיעת שופר בר\"ה לערבב השטן, והנה מקור המקטרגים למטה הוא בלעם והוא קטרג על ישראל שראה ברוח נבואה שעתידים ישראל לחטוא באותו מקום כמו מול בית פעור הנשקפה ע\"פ ישימון וכן וישת אל המדבר פניו, היינו שקטרג עליהם באותם מקומות, אך לא אבה ה' אלקיך לשמוע אל בלעם. והנה פי' תי' בלעם<sup data-n=\"1101\">2</sup> הוא בלא עם או בלע עם.\n<b>והענין</b> דהנה כתי' לעברך בברית ה' אלקיך כו' למען הקים אותך לו לעם והוא יהי' לך לאלקים, והנה על מה שהוא יהי' לך לאלקים שייך כריתות ברית שאפי' בזמן שלא כו' מ\"מ לא יחליפנו באומה אחרת, אך מה שהם יהיו לו לעם מה שייך ע\"ז כריתות ברית. והענין דהנה אין מלך בלא עם, והם צ\"ל בדומה לו<sup data-n=\"1102\">3</sup> והוא מרומם ומנושא מהם ומושל ושולט עליהם, אבל על בהמות וחיות אינו שייך מלוכה דמנהיגי הבהמות נק' רועים, וכמו\"כ למעלה צ\"ל בדומה לו, וצ\"ל מה שייך בדומה לו, דנשמות הם בע\"ג ואוא\"ס הוא בלתי בע\"ג ואין ערוך כלל יותר משאין ערוך חי לגבי מדבר ונת\"ל דאינו שייך דמדבר יהי' מלך על חי ואיך שייך לומר מלך על עם, וזהו\"ע הכריתות ברית שמ\"מ יהי' עם, אך צ\"ל האיך הם בבחי' עם.\n<b>והענין</b> דהנה כתי' נעשה אדם בצלמינו כדמותינו<sup data-n=\"1103\">4</sup> שהוא בצלם ודמות אדם שלמעלה, וזה ג\"כ צ\"ל איך שייך בצלם ודמות אדם שלמעלה. אך הנה כתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה<sup data-n=\"1104\">5</sup>, וכתי' אדם אתם אתם קרוים אדם, ונתצמצם הארת אוא\"ס בבחי' כמראה אדם שיומשך אדם למטה. ענין אדם למעלה הוא ג' קוין חסד דרועא ימינא כמו באדם למטה עיקר השפעה ביד ימין",[["1100","1","<b>ולא אבה</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה לעיל ע' תקב ואילך. וע\"ש בהמ\"מ בתחילת המאמר."],["1101","2","<b>והנה פי' תיבת בלעם הוא בלא עם או בלע עם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830213\" data-slug=\"or-hatorah-hb\" data-id=\"8158830213\">אוה\"ת בלק ע' תתצט</a>. סה\"מ תרכ\"ט ע' ערב."],["1102","3","<b>דהנה אין מלך בלא עם והם צ\"ל בדומה לו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380944\" data-slug=\"likkutei-torah\" data-id=\"4001380944\">לקו\"ת</a> דרושים לר\"ה נו, ב-ג. מאמרי אדה\"ז כתובים ח\"א ע' עו ואילך. אוה\"ת דרושים לר\"ה ע' א'שלה ואילך. סה\"מ תר\"ס ע' ה ואילך."],["1103","4","<b>והענין דהנה כתי' נעשה אדם בצלמינו כדמותינו</b>: ראה גם סה\"מ תר\"ל ע' רמב ואילך. רנ ואילך."],["1104","5","<b>אך הנה כתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370323\" data-slug=\"torah-or\" data-id=\"3901370323\">תו\"א יתרו עב, ד</a> ואילך. סה\"מ תרל\"ב ח\"א ע' יב וע' טז-יז."]]],[2002180345,"וכן מלאכה עושין ביד ימין כמו\"כ למעלה עיקר ההשפעה הוא בחסד מכלכל חיים בחסד, וגבורה דרועא שמאלא דבהנהגת המלוכה צ\"ל גבו' ג\"כ וכמ\"ש והוכן בחסד כסא, מלך במשפט יעמיד ארץ, דאלמלא מוראה כו', ות\"ת גופא שצ\"ל רחמים ג\"כ וכמ\"ש רחם ארחמנו, וכמו באדם יש שכל בעצם ושכל שבמדות כמו\"כ למעלה ג\"כ. והנה לגבי אוא\"ס בחי' כי לא אדם הוא אינו בערך כלל, אלא שנתצמצם שיהי' בחי' כמראה אדם שיומשך אח\"כ בחי' אדם אתם, וזהו\"ע נעשה אדם. אך ע\"י מה נמשך שיהי' בחי' אדם ועם, זהו בצלמינו כדמותינו, בצלמינו הוא יחו\"ע איך שכולא קמי' כלא חשיב ביטול אמיתי ביטול במציאות למס\"נ באחד, וכדמותינו הוא ביטול היש ברוך שם כו'. הגם שיחו\"ע שלמטה אינו בערך כלל לגבי למעלה, אך הנה כתי' ואנכי עפר ואפר<sup data-n=\"1105\">6</sup>, דאברהם שלמטה שרשו בבריאה אמר אנכי עפר ואפר לגבי אברהם דאצי' שהוא מרכבה למדת החסד הרי שאין ערוך כלל, מ\"מ ה\"ז קצת ערך כמו עפר ואפר לגבי איזה ענין כמו\"כ כאן ג\"כ. אך צ\"ל ומלכותו ברצון קבלו עליהם, דהנה ארז\"ל למה קדמה שמע לוהי' אם שמוע כדי שיקבל עליו עומ\"ש תחילה ואח\"כ יקבל עליו עול מצות, וע\"י קבעומ\"ש אפשר להגיע למדרי' ומלכותו ברצון קבלו עליהם, וזהו מ\"ש כה אמר ה' מלך ישראל וגואלו, אך על לע\"ל כתי' כי מלך כל הארץ אלקים, דאז אהפוך אל העמים שפה ברורה לקרוא כולם בשם ה', אך עתה הוא מלך ישראל.\n<b>אך</b> הנה בלעם הוא בלא עם, שאינו מקבל עליו עומ\"ש מ\"מ רצונו שיומשך לו ריבוי השפעה והוא מצד בחי' רם על כל גוים ה', דאם צדקת מה תתן לו ורבו פשעיך מה תעשה לו אם חטאת מה תפעול בו ומה מידך יקח, שאינו נוגע כלל מעשה התחתונים דכחשיכה כאורה, ומה עשה קטרג על ישראל באותן מקומות שעתידים לחטוא שם ונמצא שהם ג\"כ אינן מקבלים עליהם עומ\"ש. אך לא אבה ה' אלקיך לשמוע אל בלעם, דכך עלה ברצונו שיתצמצם הארת אוא\"ס בבחי' כמראה אדם שיומשך בחי' אדם אתם, דנתאווה הקב\"ה להיות לו דירה בתחתונים, וכמו כד סליק ברעותא למברי עלמא. אך מפני מה לא אבה לשמוע מפני הוי' אלקיך, שיש שם הוי' בכאו\"א מישראל וכמ\"ש כי חלק הוי' עמו, ומזה גופא מה שנק' אדם מובן כן. דהנה כתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה הוא מראה דמות כבוד הוי', הרי שאדם הוא הוי', ומאחר שנק' אדם הרי יש בהם הוי'.\n<b>והוא</b> דהנה הוי' הוא י' ה' ו' ה' ובי' יש קוצו של י'. וענין קצש\"י<sup data-n=\"1106\">7</sup> דהנה כתי' והחכ' מאין תמצא שמציאת החכ' הוא מאין שאינו מושג, והענין דהנה מדות הם באים משכל כשמבין בשכלו שטוב לו הדבר הוא רוצה בה, וכן יש מדות שבשכל שבשכל גופא יש הטי', וכן בריקת וסקירת השכל הרי יש לו מקור שמשם נמשך",[["1105","6","<b>אך הנה כתי' ואנכי עפר ואפר</b>: ראה אגה\"ק סי' טו (קכא, א ואילך). סה\"מ תר\"ל ע' נו ואילך. תש\"ב ע' 84. ועוד."],["1106","7","<b>וענין קצש\"י</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת פ' ראה יח, א</a> ואילך (הובא לעיל במאמר ע' תקד)."]]],[2002180346,"השכל, אך אינו מורגש שאינו מרגיש מאין נפל לו השכל. וזהו בשכל חדש וכמו\"כ בשכל ישן עד\"מ כשלומד איזה מס' ויודע אותה בטוב<sup data-n=\"1107\">8</sup> ואח\"כ לומד מס' אחרת וכשרוצה להזכר איזה דבר ממס' שלמד כבר ה\"ה זוכר אותו דבר, וצ\"ל היכן הי' תחילה, אם לא הי' תחילה כלל, מאין בא לו עתה, ואם הי' תחילה ג\"כ היכן הי', אלא שיש העלם השכל שאינו בהרגש כלל, וזהו\"ע קוש\"י, ולכן הוא רק קוץ, דהנה אות הוא גילוי וכמ\"ש אמר שומר אתא בוקר, דאותיות הם גילוים, ויש אותיות המח' דהוא גילוי העלם העצמי לגבי עצמו ויש אותיות הדיבור שהם גילוי לזולת, אך קוץ הוא כמו די לחכימא ברמיזא<sup data-n=\"1108\">9</sup>.\n<b>ובעבודה</b> הוא האהבה מוסתרת שיש לכאו\"א מישראל<sup data-n=\"1109\">10</sup> שיהי' [לו] משיכה לאלקות, הגם שאפשר שיעשה היפך רצה\"ע הנה ארז\"ל אין אדם עובר עבירה אא\"כ נכנס בו רוח שטות<sup data-n=\"1110\">11</sup>, שמכסה ונדמה לו שאף אם יעשה דבר זה מ\"מ לא יהי' נפרד ועודנו ביהדותו, אבל אם הי' יודע שבזה יהי' נפרד לא הי' עושה זאת בשום אופן, וראי' דאפי' קל שבקלים יש בו כח למס\"נ, רק שהרוח שטות מכסה על האמת נדמה לו שעודנו ביהדותו, אבל כשמעורר את האהבה מוסתרת יהי' לו אהבה ורצון לאלקות למס\"נ ממ\"ש<sup data-n=\"1111\">12</sup>* שלמעלה מטו\"ד, דע\"פ השכל מחייב אהבה דכתי' גבי' לאהבה את ה' אלקיך כי הוא חייך אבל מס\"נ הוא למעלה מטו\"ד. וזהו מ\"ש נר ה' נשמת אדם כמו הנר טבעו לעלות למעלה כמו\"כ נשמה יש לו תמיד רצון לאלקות, וזהו\"ע קוש\"י.\n<b>ויו\"ד</b> הוא כמו שכל למטה שהו\"ע ברק המבריק כמו\"כ למעלה הוא בחי' חכ' כח מ\"ה שבו שורה אוא\"ס, ובד\"כ קאי על כללות עולם אצי' דאבא מקננא באצי' שהוא הפרשת הארה מאוא\"ס<sup data-n=\"1112\">13</sup>. אך צ\"ל דמאחר שאצי' הוא הפרשת הארה מאוא\"ס ה\"ה בדומה לו והוא ג\"כ אוא\"ס ואי' בזהר דלית מח' תפיסא בי' כלל, מח' הוא חכ' כמו מח' ויובלא לא אתפרש לעלמין, אינו בערך כלל לגבי אוא\"ס וכמ\"ש כולם בחכ' עשית. אך הענין הוא דהנה כשם שהוא אין סוף כמו\"כ ההארה ג\"כ א\"ס, ואם הי' נאצל עולם האצי' מהארה זו הי' הכל בבחי' א\"ס, וכדי שיהי' ההגבלה חו\"ב וחו\"ג וחסד אינו גבורה וגבורה אינו חסד צ\"ל צמצום שיתצמצם הארת אוא\"ס ולכן אין",[["1107","8","<b>עד\"מ כשלומד איזה מס' ויודע אותה בטוב</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380302\" data-slug=\"likkutei-torah\" data-id=\"4001380302\">לקו\"ת ויקרא הוספות נב, ג</a>-ד. מאמרי אדה\"ז ענינים ע' שכא. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תתקכא. דרך מצותיך קלו, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940301\" data-slug=\"or-hatorah-hb\" data-id=\"8159940301\">אוה\"ת ויקרא (כרך ב) ע' תשג</a> וע' תשו-ז. סה\"מ תרמ\"ז ע' מח."],["1108","9","<b>אך קוץ הוא כמו די לחכימא ברמיזא</b>: ראה בהמ\"מ לעיל במאמר ס\"ע שי ואילך."],["1109","10","<b>ובעבודה הוא האהבה מוסתרת שיש לכאו\"א מישראל</b>: בהבא להלן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380871\" data-slug=\"likkutei-torah\" data-id=\"4001380871\">לקו\"ת תצא לח, ג</a>. סה\"מ תרכ\"ט (הוצאת תשנ\"ב) ע' רצט ואילך. ובשינויים בסה\"מ תרל\"ב ח\"א ע' רצג."],["1110","11","<b>הנה ארז\"ל אין אדם עובר עבירה אא\"כ נכנס בו רוח שטות</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח-י\"ט (כד, א</a> ואילך)."],["1111","12","<b>למס\"נ ממ\"ש</b>: כ\"ה בגוכתי\"ק. ולפעמים סימון הר\"ת הוא להדגשת התיבה."],["1112","13","<b>שהוא הפרשת הארה מאוא\"ס</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370010\" data-slug=\"torah-or\" data-id=\"3901370010\">תו\"א בראשית ג, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370063\" data-slug=\"torah-or\" data-id=\"3901370063\">וירא יד, א</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' רצב ואילך. אוה\"ת ואתחנן ע' קפו ואילך. סה\"מ תרל\"ב ח\"א ע' מב וע' רד. ובכ\"מ."]]],[2002180347,"ערוך ולית מחשבה תפיסא בי' כלל, וזהו\"ע אבא יונק ממזלא, דמזלא הם מזלות והם כמו שערות שיונקים מהמוח אך הוא רק חיות מצומצם שהם מותרי מוחין, דעל מוח יש ב' קרומים ואויר ביניהם וגולגלתא ואח\"כ צומחין השערות ולכן כשגוזזין השערות אינו מרגיש כאב וכשחותכין אבר מרגיש והוא מפני שהוא חיות מצומצם כמו\"כ מזלות הם רק הארה מועטת, ואבא יונק ממזלא לכן אין ערוך כלל. ובעבודה הו\"ע בטל רצונך והוא הצמצום שעושה בנפשו במחדו\"מ, מח' הוא כמ\"ש רבות מחשבות בלב איש ועצת ה' היא תקום, הם ריבוי המח' הטורדות ומבלבלות, אך באמת עצת ה' היא תקום וא\"כ מה יועיל לו הריבוי מח', ובזה הוא מדחה אותם, דעיקר בריאתן הוא כדי לדחות אותם, וכן דיבור הוא שומר פיו ולשונו שומר מצרת נפשו, וכ\"ש מעשה הוא מ\"ש עוצם עיניו מראות ברע, וע\"י הצמצום שעושה בנפשו במחדו\"מ גורם למעלה ג\"כ שיהי' צמצום שיהי' בחי' חכ'. אך למעלה הצמצום הוא ירידה והשפלה ולמטה הצמצום הוא שלא יהי' ירידה בדברים הבליים אלו, וזהו\"ע יו\"ד.\n<b>ה'</b>, הנה ה' עושין מיו\"ד ממשיכים לאורך ורוחב והיינו כמו שברק המבריק נמשך בהשגה והבנה באורך ורוחב אריכות ההתבוננות איך דמה גדלו מעשיך הוי' והיינו ריבוי גדולי הנבראים שנתהווה, ועיקר רצונו דוקא באדם למטה, ועי\"ז יהי' שמחת הנפש בה' עושה, וזהו\"ע תשובה עילאה מלמטלמ\"ע, וע\"ז נתקן ענין התפלה תחילה פסוד\"ז הללו את ה' מן השמים כו' כי נשגב שמו לבדו שאפי' בחי' נשגב הוא רק שם והארה בעלמא ואח\"כ ברכת ק\"ש ועי\"ז ואהבת שיהי' לאלקות<sup data-n=\"1113\">14</sup>*. ו\"ה הם תומ\"צ, תורה הוא ו' דכתי' הקול קול יעקב קלא קדמאה חסר ו' הוא קול תפלה וקלא בתראה הוא קול תורה שהוא בחי' ו' וכמ\"ש קול קורא במדבר, וכן כל הקורא ושונה הקב\"ה קורא ושונה כנגדו, וכן כל הקורא בתורה כאילו קורא בשמותיו של הקב\"ה כמו כשקוראין לראובן בשמו ה\"ה בא כמו\"כ ע\"י התורה ממשיכים הארת אוא\"ס. וה' הוא מצות המלך, ובכלל הוא צדקה צדק ה' שנמשך למטה<sup data-n=\"1114\">15</sup>.\n<b>וזהו\"ע</b> שם הוי' שבכאו\"א מישראל ולכן לא אבה לשמוע אל בלעם, ויהפוך ה' אלקיך לך את הקללה לברכה, וצ\"ל מאחר דלא אבה לשמוע איך שייך ויהפוך כו'. והענין דהנה זה לא קאי על בלעם דלא מצינו כלל שקלל את ישראל כ\"א ברמז כמו וישת אל המדבר פניו, אך הענין דהנה כתי' בפ' ראה את הברכה אשר תשמעו ואת הקללה אם לא תשמעו, דהנה מ\"ש ולא אבה קאי על צדיקים דהנה נת\"ל שהו\"ע ביטול שלמעלה מטו\"ד ובחי' בטל רצונך והתבוננות ותומ\"צ שהוא מדרי' הצדיק, ומ\"ש ויהפוך הוא קאי על בע\"ת שפגם וזהו הקללה אם לא תשמעו ועז\"נ ויהפוך כו'.",[["1113","14","<b>שיהי' לאלקות</b>: חסר כאן בגוכי\"ק: ואוצ\"ל שיהי' לו אהבה לאלקות."],["1114","15","<b>ובכלל הוא צדקה צדק ה' שנמשך למטה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380925\" data-slug=\"likkutei-torah\" data-id=\"4001380925\">לקו\"ת נצבים נא, סע\"ג</a>. סידור עם דא\"ח עח, ד. שערי אורה כה, ב ואילך."]]],[2002180348,"<b>דהנה</b> כתי' שובה ישראל עד הוי' אלקיך<sup data-n=\"1115\">16</sup>, פי' עד ה' אלקיך דהנה כתי' וירא כל העם ויפלו על פניהם ויאמרו הוי' הוא אלקים הוי' הוא אלקים, וצ\"ל מהו\"ע ב\"פ הוי' הוא אלקים. והענין דהנה כל האורות הם הוי', דשם הוי' הוא מקור האורות ושם אלקים מקור הכלים, והוא כמ\"ש שמש ומגן הוי' אלקים כמו המגן הוא מכסה ומסתיר על השמש כמו\"כ שם אלקים מכסה ומסתיר על שם הוי', וכמו בשמש בלתי מגן לא היו יכולים כלל לקבל אור השמש דלעתיד דמוציא הקב\"ה חמה מנרתקה לא יוכלו לקבל כמו\"כ ע\"י צמצום דשם אלקים יכולים לקבל אור הוי', דצמצום הוא צורך הגילוי, וכמו צמצם שכינתו בין שני בדי ארון, וזהו הוי' הוא אלקים דע\"י שם אלקים מאיר ומתגלה שם הוי'. אך כ\"ז הוי' ל' מהווה שהוא מקור על התהוות ועז\"נ המחדש בטובו בכ\"י תמיד מע\"ב, שבכ\"י נמשך חיות חדש, וכן בכ\"ע ובכל רגע, אבל יש מדרי' היותר עליונה דשם הוי' כאלקים יחשב. דהנה כתי' ויקרא הוי' הוי' שיש שני שמות הוי' הא' שם הוי' דסדר השתל' הב' שם הוי' שלמעלה מסדר השתל', דלגבי שם הוי' שלמעלה מסדר השתל' השם דסדר השתל' כאלקים יחשב, וזהו הוי' הוא אלקים פ\"ב דהוי' כאלקים יחשב. וזהו שובה ישראל עד ה' אלקיך, שיהי' בחי' תשובה דהיינו כשיתבונן במחדו\"מ אשר לא לה' המה ועי\"ז ויצעקו אל ה' בצר הוא הצעקה מפנימיות מעומקא דליבא, עד ה' אלקיך היינו שהוי' כאלקים יחשב, ומשם נמשך שאף אם פגם בשם הוי' היינו במל\"ת שתלויים בי\"ה ומ\"ע התלויים בו\"ה יתמלאו כל הפגמים. וזהו ויהפוך ה' אלקיך לך את הקללה, היינו דזדונות נעשו לו כזכיות.\n<b>ובכלל</b> מרומז כאן ר\"ה ויוהכ\"פ<sup data-n=\"1116\">17</sup> ובסוף מרומז סוכות ג\"כ. מ\"ש ולא אבה ה' הוא ר\"ה<sup data-n=\"1117\">18</sup> דבר\"ה ליכא סליחת עוונות רק הסליחה מופקדת אצלך עד (ר\"ה)* יוה\"כ, ואז לא אבה כו' ולכן בר\"ה מתחילים הימים נוראים שהוא בחי' יראה עילאה ביטול, ויהפוך ה' הוא יוהכ\"פ שאז נמשך סליחת עוונות להיות נושא עון ועובר על פשע, ואח\"כ כתי' כי אהבך ה' אלקיך הוא האהבה עליונה שנמשך בסכות. דהנה כתי' הלא אח עשו ליעקב ואוהב את יעקב, דהנה יש מקום ששם אח עשו ליעקב אם צדקת מה תתן לו ורבו פשעיך מה תעשה לו אם חטאת מה תפעל בו ומה מידך יקח, שם עשו ויעקב שוין ומ\"מ ואוהב את יעקב וכמ\"ש אהבתי אתכם אמר הוי', היינו האהבה העליונה שנמשך ע\"י מקיפים דסוכות. דהנה כתי' שמאלו תחת לראשי וימינו תחבקני<sup data-n=\"1118\">19</sup>, שמאלו תחת לראשי הוא ר\"ה ויוהכ\"פ שהוא בחי' שמאל דוחה וזהו\"ע הוידויים שאומרים אז אשמנו כו' ע\"ח, שאם זולתו הי' אומר עליו כן לא הי' יכול לקבל, והו\"ע הדחי' שמדחה א\"ע (וימינו תחבקני)*, וע\"י ענן הקטרת דיוהכ\"פ ועכשיו",[["1115","16","<b>דהנה כתי' שובה ישראל עד הוי' אלקיך</b>: ראה בכ\"ז ד\"ה שובה ישראל בלקו\"ת ש\"ש סד, ג ואילך. סה, ד ואילך."],["1116","17","<b>ובכלל מרומז כאן ר\"ה ויוהכ\"פ</b>: ראה בסה\"מ ה'ש\"ת ע' 159 ואילך."],["1117","18","<b>(ר\"ה)</b>: כ\"ה בגוכי\"ק. וכנראה המוסגרים כאן הם סימן למחיקה."],["1118","19","<b>(וימינו תחבקני)</b>: כ\"ה בגוכי\"ק. וכנראה גם כאן המוסגרים הם סימן למחיקה."]]],[2002180349,"ע\"י התשובה נמשך ענני הכבוד דסוכות ואז ימינו תחבקני שהוא האהבה העליונה. וזהו ולא אבה הוי' אלקיך לשמוע אל בלעם הוא ר\"ה, ויהפך ה' אלקיך לך את הקללה לברכה הוא יוהכ\"פ דזדונות נעשו לו כזכיות, כי אהבך הוי' אלקיך הוא סוכות שיהי' כמ\"ש אהבתי אתכם אמר הוי'."],[2002180350,"<h3>את ה' האמרת (ש\"פ תבוא)</h3>\n<b>ש\"פ תבוא טל לפ\"ק</b>\n<b>את</b> ה' האמרת<sup data-n=\"1119\">1</sup> היום להיות לך לאלקים וללכת בדרכיו ולשמור חוקיו ומצותיו, וה' האמירך היום להיות לו לעם סגולה גו' ולשמור כל מצותיו, הקשה באור החיים מה\"ע אומרו ולשמור מצותיו בפסוק וה' האמירך, דהנה מה שא' את ה' האמרת כו' הוא מה שישראל משבחין את הקב\"ה ושייך שם לומר ולשמור מצותיו הוא שמקבלין עומ\"ש, אבל מ\"ש וה' האמירך הוא מה שהקב\"ה משבח לישראל ומהו\"ע לשם מ\"ש ולשמור מצותיו כו', דהנה מלמטלמ\"ע שייך זה, אבל מלמעלמ\"ט מה שייך זה.\n<b>והענין</b> דהנה בתי' האמרת יש ג' פירושים (א) ל' שבח וגדולה ורוממות וכמ\"ש יתאמרו כל פועלי און שמתגדל ומתרומם, (ב) ל' לבוש דאי' במדרש ע\"פ בצע אמרתו בזע פורפירא דילי', ופורפירא הם לבושים, ומאחר דאמרתו הם לבושים האמרת ג\"כ לבושים (בצע אמרתו אשר ציוה מימי קדם ע' בד\"ה את ה' האמרת (של כ\"ק אאזמו\"ר זצוללה\"ה<sup data-n=\"1120\">2</sup>) פורפירא הוא לבוש מל' ששרשה מימי קדם הם י\"ג ת\"ד (וצ\"ע ע' בלקו\"ת בביאור לד\"ה אני לדודי הב'<sup data-n=\"1121\">3</sup> שימי קדם הוא עומקא דחשוכא מל' דא\"ק שמשם שרש הי\"ג ת\"ד, וע' בק\"י<sup data-n=\"1122\">4</sup> ערך ים פי' ימי קדם ספי' דעתיקא וצ\"ע) וע\"י קבעומ\"ש עושין הלבוש היינו שיומשך בלבוש זה, דמצד א\"ס אפשר שיומשך גם לחיצונים וכמ\"ש אם צדקת כו' כחשכה כאורה, וצ\"ל לבוש שיומשך לקדושה דוקא וע' במק\"מ ובהרמ\"ז בזח\"א דס\"א ע\"ב, וע' בס' קינת סתרים למהר\"ם גאלאנטי<sup data-n=\"1123\">5</sup> אמרתו הוא בחי' לבוש מל' אשר ציוה מימי קדם שנמשכת מי\"ג ת\"ד מתיקון הי\"ג (הוא ונקה דאימא יונק ממזלא הי\"ג ונקה) (ובמ\"א פי' ימי קדם ו\"ק דזעיר<sup data-n=\"1124\">6</sup> כ\"ה בק\"י",[["1119","1","<b>את ה' האמרת</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה, הנדפס לעיל ע' תקי. וראה בהמ\"מ בתחילת המאמר שם."],["1120","2","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080171\" data-slug=\"or-hatorah-hb\" data-id=\"8160080171\">ע' בד\"ה</a> את ה' האמרת (של כ\"ק אאזמו\"ר זצוללה\"ה)</b>: ראה אוה\"ת תבוא ע' תתרס ואילך. שם כרך ה' ע' ב'ע. וראה בכ\"ז אוה\"ת אמור (כרך א) ע' קעא."],["1121","3","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380854\" data-slug=\"likkutei-torah\" data-id=\"4001380854\">לקו\"ת</a> בביאור לד\"ה אני לדודי הב'</b>: פ' ראה לד, ד."],["1122","4","<b>בק\"י</b>: בקהלת יעקב (ערכים בקבלה לבעהמ\"ס מלוא הרועים)."],["1123","5","<b>וע' בס' קינת סתרים למהר\"ם גאלאנטי</b>: ס' קינת סתרים (להר\"א בר\"מ גאלאנטי) נדפס בווינצי' שמ\"ט."],["1124","6","<b>ובמ\"א פי' ימי קדם ו\"ק דזעיר</b>: ראה גם אוה\"ת אמור שם. [וראה במובא בס' הליקוטים — דא\"ח דהצ\"צ ערך יום ס\"ע שמ ואילך]."]]],[2002180351,"ע' הנ\"ל והוא כמו שפי' המק\"מ ע\"ש), ואפ\"ל הפי' כך דהנה כתי' ביום ההוא יהי' הוי' אחד ושמו אחד שנק' כמו שנכתב שהגילוי יהי' ג\"כ שם הוי' (ואפ\"ל כמשנת\"ל בד\"ה ולא אבה דהוי' כאלקים יחשב), וזהו את ה' האמרת היום, ואפ\"ל כדי שיהי' האמרת היינו הוי' אחד ושמו אחד זהו דוקא ע\"י עבודה דהיום היינו קבעומ\"ש דעכשיו עי\"ז יהי' לע\"ל הוי' אחד ושמו אחד, ע\"כ). (ג) ל' אמירה ודיבור. והנה בת\"י מפ' ל' שבח וא' שהוא משארז\"ל אתם עשוני חטיבה א' בעולם אף אני אעשה לכם חטיבה א' בעולם, אתם עשוני חטיבה כמ\"ש שמע ישראל ה' אלקינו ה' אחד אף [אני] אעשה לכם חטיבה אחת בעולם מי כעמך כישראל גוי אחד בארץ, וצ\"ל תחילה פי' תי' אחד.\n<b>הנה</b> באחד יש כמה פי', אך יש ג' פירושים שהם ג' פי' שונים. (א) הנה אי' במדרש אחד אין כיוצא בו, דהנה כתי' ויהי כל הארץ שפה אחת ודברי' אחדי' ואי' במדרש דברים על ב' אחדים ה' אחד ואחד הי' אברהם<sup data-n=\"1125\">7</sup>, וצ\"ל דהנה על אברהם שייך לומר אחד אין כיוצא בו אבל על הקב\"ה איך שייך לומר אחד אין כיוצא בו, דאיך שייך ליפול על לב איש שיש כיוצא בו ח\"ו שצריכים לומר אין כיוצא בו, איך עולה על הדעת לומר כו', וגם מאחר שאומרים דה' אחד אין כיוצא וא\"כ צ\"ל בישראל ג\"כ אין כיוצא וצ\"ל מהו\"ע אין כיוצא בו בישראל, וע\"י מה יכולים לבוא לבחי' זו.\n(ב) <b>הנה</b> אי' במדרש מהיכן זכו ישראל לק\"ש ממ\"ת דבשעה שפתח הקב\"ה בסיני אמר שמע ישראל אנכי הוי' אלקיך ענו ואמרו ה' אלקינו, ואח\"כ א\"ל לא יהי' לך כו' ענו ואמרו ה' אחד (ז\"ל המד\"ר<sup data-n=\"1126\">8</sup> דברי' פ\"ב ומהיכן זכו כו' א\"ל שמע ישראל אנכי ה' אלקיך נענו כולן ואמרו ה' אלקינו ה' אחד וצ\"ע), הרי דה' אלקינו ה' אחד הוא קבלה על הב' מאמרי' אנכי ולא יהי' לך שהם כלליות כל התורה דתרי\"ג מצות נאמרו למשה מסיני כמנין תור\"ה מפיו שמענו<sup data-n=\"1127\">9</sup>, אנכי ולא יהי' לך מפי הגבורה שמענו ובהם נכלל כל התורה, הרי ה' אחד הוא קבלה על דיבור לא יהי' לך, וזהו אחד להוציא ע\"ז.\n(ג) <b>דמצות</b> ליחדו הוא מפסוק שמע כו' ה' אחד, והוא להוציא ענין השיתוף. דהנה ברמ\"א סי' קנ\"ו פסק דבני נח אינם מוזהרים על שיתוף ועל ע\"ז הם מוזהרים דכתי' ויצו כו' על האדם אין צו אלא ע\"ז, אבל על שיתוף אינם מוזהרים, והוא לשיטת התוס' והר\"ן, הגם שיש חולקים עליהם מ\"מ הרמ\"א פסק כמותם. וזהו יותר ממשנת\"ל להוציא ע\"ז דאף שמוציא ע\"ז מ\"מ שיתוף אינו מוציא והראי' דבני נח מוזהרים על ע\"ז ועל שיתוף אינם מוזהרים, ועפ\"ז מוציא שיתוף ג\"כ.",[["1125","7","<b>ואי' במדרש דברים על ב' אחדים ה' אחד ואחד הי' אברהם</b>: ראה גם אוה\"ת נח (כרך ו) תתרסה, סע\"א ואילך. וש\"נ."],["1126","8","<b>ז\"ל המד\"ר דברים פ\"ב ומהיכן זכו כו' נענו כולן ואמרו ה' אלקינו ה' אחד וצ\"ע</b>: ראה לעיל במאמר זה מכ\"ק אדמו\"ר מהר\"ש ובהערת כ\"ק אדמו\"ר זי\"ע שנדפס בשולי העמוד שם, שמתרץ זה."],["1127","9","<b>כמנין תורה מפיו שמענו</b>: ראה מכות כג, סע\"ב: מאי קרא תורה צוה לנו משה מורשה, תורה בגימטריא תרי\"א הוי, אנכי ולא יהי' לך מפי הגבורה שמענום."]]],[2002180352,"<b>והנה</b> להבין זה צ\"ל ההפרש בין שיתוף לע\"ז<sup data-n=\"1128\">10</sup> (ית' שע\"י ששוללים ענין ע\"ז ושיתוף באים לאחד אין כיוצא בו כנ\"ל). דהנה ע\"ז הוא דקרו לי' אלקא דאלקייא, דרם על כל גוים ה' על השמים כבודו ועזב את הארץ בידי המזלות ומערכת אלקות, דהוא השפלה וירידה לגבי' שישגיח על עלולים השפלים להשגיח על כל פרטי פרטי מדריגות, דהם אומרים דברה\"ע הוא ע\"י השתל' עו\"ע. הגם דהנה אמרז\"ל אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל, הרי כל עשב ועשב יש לו שרש ומקור למעלה, זהו על ההגדלה והצמיחה מקטנות לגדלות אבל גוף דבר הצומח הוא מא\"ס הסוכ\"ע, דהמגביהי לשבת המשפילי לראות בשמים וארץ, דהם אומרים על השמים כבודו דשמים לרום אבל על הארץ הוא השפלה לגבי', ובאמת כמו שהארץ הוא השפלה כמו\"כ השמים ג\"כ השפלה וכדאי' בזהר ע\"פ היושבי בשמים מהו תוס' יו\"ד אלא שהארת היו\"ד בשמים הוא בבחי' ישיבה כמו אדם היושב הוא משפיל קומתו דבעת עמידה הוא בעל קומה אבל בעת ישיבה הוא משפיל קומתו, הרי שגם השמים הוא השפלה לגבי' וכמו\"כ הוא משגיח על הארץ ג\"כ.\n<b>וזהו</b> ר\"י כד הוה חזי שלך אמר משפטיך תהום רבה וכד הוה חזי נמלה אמר צדקתך תהום רבה ופירש\"י כד הווה חזי נמלה שהוא ברי' קטנה ומ\"מ נמשך לה חיות אמר צדקתך שהוא צדקה שנמשך חיות לכל ברי', וכד הוה חזי שלך אמר משפטיך תהום רבה שגם בתהום יש דין ומשפט, וכ' רש\"י שם לשון מורי, שלחת את השלך להמית אותן המזומנים למיתה, ומכאן השיב רבינו ז\"ל תשובה לאותן שמודים שיש השגחה במין המדבר אבל במין הבע\"ח אינו משפיל כ\"כ להשגיח עליהם, וממה שאומר כאן להמית אותן המזומנים למיתה נראה בעליל שיש השגחה גם בבע\"ח. ומה שארז\"ל ע\"פ תעשה אדם כדגי הים מה דגים שבים הגדול בולע את הקטן כו', זהו ג\"כ דוקא המזומנים למיתה אבל אותן שאינם מזומנים אינו יכול לבלוע, והראי' שהרי אח\"כ א' כך אדם הגדול כו' ובמין המדבר מודים שיש השגחה כמו\"כ בבע\"ח הוא ג\"כ ע\"פ השגחה, וזהו חייב אדם להתפלל בשלומה של מלכות שאלמלא מוראה איש את רעהו חיים בלעו, הגם שהוא ע\"פ השגחה מ\"מ צ\"ל בסדר השתל' ולא כו'. וזהו שארז\"ל אפי' ציפורא בלעדי שמיא לא מיצדי, דרשב\"י כשיצא ממערה ראה צייד צד עופות כשאמר דימוס ניצול וכשאמר ספקולא ניצוד, ויש פי' בהיפך, דאפי' ציפורא בלעדי שמיא לא מיצדי, אבל או\"ה דקרו לי' אלקא דאלקייא זהו\"ע ע\"ז, ושיתוף הוא שמשתף שם שמים בד\"א.\n<b>והענין</b> דהנה ארז\"ל ג' שותפין באדם אב ואם והקב\"ה נותן בו נשמה, והנה כשנדייק הדק היטיב נראה שאין השותפות שוין, לבד מה שחלק או\"א הוא רק הגוף דאב מזריע לובן כו' ואם מזריע אודם כו', והעיקר הוא חלק הקב\"ה שהוא",[["1128","10","<b>והנה להבין זה צ\"ל ההפרש בין שיתוף לע\"ז</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010015\" data-slug=\"or-hatorah-hb\" data-id=\"8159010015\">אוה\"ת בראשית (כרך ז) תתשסד, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560383\" data-slug=\"or-hatorah-hb\" data-id=\"8316560383\">אוה\"ת נח (כרך ג) תרנח, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470282\" data-slug=\"or-hatorah-hb\" data-id=\"8316470282\">יתרו ע' תשנה</a>. ואתחנן ע' שעג. ד\"ה באתי לגני תשי\"ג. ובכ\"מ."]]],[2002180353,"הנשמה, והראי' כשנסתלק הנפש מהגוף נשאר הגוף כאבן דומם ומותר אדם על הבהמה ין, ואפי' חושים המעולים כמו שכל וכדומה מסתלקים ממנו<sup data-n=\"1129\">11</sup>, וזהו כשנא' דהגוף הוא מחלק או\"א אבל באמת הנה ארז\"ל ע\"פ אין צור כאלקינו אין צייר כאלקינו צר צורה בתוך צורה דהאב אינו יודע איך נעשה מזה ציור הולד כמו<sup data-n=\"1130\">12</sup>*, הרי שאין השותפות שוין, אלא הוא ע\"ד שארז\"ל כל האומר ויכולו כאילו נעשה שותף להקב\"ה במע\"ב וכי מפני שמשבח את הקב\"ה שברה\"ע נעשה לו שותף, הרי אין השותפות שוין, אלא ששם אומר כאילו כו' אבל כאן נא' ג' שותפין כו', אלא שלכך נק' שותף מפני שהוא בעל בחירה שאם לא ירצה ליקח אשה ממילא לא יוליד בנים, מובן מזה שמי שאינו בעל בחירה אינו נק' שותף, וכמו הארץ שאינו שייך לומר שהוא בעל בחירה שאם ירצה יצמח כו' דכשזורעין בתוכו צומח וכשזורעין גרעין זה צומח פרי זו כו', וכן השמש דכתי' ממגד תבואות וממגד גרש ירחים אינו שייך לומר שהוא בעל בחירה שאם ירצה יזרח על הארץ ומ\"מ לא יצמח, אלא כשהוא זורח על הארץ בע\"כ צומח ממנו שהוא רק כלי שדרך בו נשפע ההשפעה, והרי הוא כמו הגרזן ביד החוצב בו שאינו שייך לומר שהגרזן הוא החוצב הגם שצריך להגרזן ובלתו לא יוכל לחטוב ומ\"מ חטיבה אינו מיוחסת להגרזן כ\"א להאדם החוטב בו, שהגרזן הוא רק כלי שאינו בעל בחירה כלל. וא\"כ אותן העובדים לשמש ולירח משתפים שם שמים בד\"א. וזהו ענין אחד להוציא ע\"ז ושיתוף וכמ\"ש וידעת היום והשבת אל לבבך כי הוי' הוא אלקים אין עוד אפי' בחללו של עולם, וזהו ראו עתה כי אני אני הוא ואין אלקים עמדי.\n<b>אך</b> צ\"ל דהנה אי' בזהר דפסוק זה קאי על לע\"ל<sup data-n=\"1131\">13</sup> וא\"כ מה נא' ראו עתה, והענין דהנה כתי' אני ראשון ואני אחרון ומבלעדי אין אלקים, ועכשיו רק פ\"א אני ולע\"ל יהי' ב\"פ אני אך התחברות ב' בחי' אני, ועכשיו בעבודה הוא בבחי' ראי', וזהו ראו עתה כי אני אני הוא שהוא בבחי' ראי'. והנה צ\"ל תחילה ההפרש בין ג\"ע לתחיית המתים, דהנה בג\"ע יש ב' מדרי' געה\"ע וגעה\"ת, ולא כל אדם זוכה לגעה\"ע וע\"פ רוב זוכים לגעה\"ת, הגם שיש כמה מדרי' בג\"ע וכמ\"ש צדיקים אין להם מנוחה לא בעוה\"ז ולא בעוה\"ב שנא' ילכו מחיל לחיל אך בכלל יש ב' מדרי' געה\"ע וגעה\"ת, ובתחה\"מ לא יש רק מדריגה א' וכולן שוין, הגם שארז\"ל כאו\"א נכוה מחופתו של חבירו מ\"מ הוא במדרי' א', ועוד זאת דבתחה\"מ יתלבשו נשמות בגופים אפי' נשמות האבות ומשה שהם יותר מג' אלפים שנה בג\"ע יתלבשו בגופים לקבל העונג שיהי' לע\"ל, וצ\"ל זה.",[["1129","11","<b>ואפי' חושים המעולים כמו שכל וכדומה מסתלקים ממנו</b>: ראה בהמ\"מ לעיל במאמר פיסקא: שכל אברי הגוף."],["1130","12","<b>דהאב אינו יודע איך נעשה מזה ציור הולד כמו</b>: אולי חסר כאן תיבה. (ואוצ\"ל: כמוהו. או שצ\"ל: ציור כמו הולד)."],["1131","13","<b>אך צ\"ל דהנה אי' בזהר דפסוק זה קאי על לע\"ל</b>: בכל הבא להלן — ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380499\" data-slug=\"likkutei-torah\" data-id=\"4001380499\">לקו\"ת שלח מו, ד</a> ואילך. אוה\"ת האזינו ע' א'תש-א. ובכ\"מ. וראה גם בהמ\"מ לעיל בהמאמר ע' תקיד."]]],[2002180354,"<b>והענין</b> דהנה בג\"ע נהנין מזיו השכינה זיו תורתן ועבודתן, דשם לומדים ג\"כ תורה אלא שהוא ברוחניות, דכאן הוא הלכה גשמיות כמו המחליף פרה בחמור וכדומה ושם הוא ברוחניות, והוא עונג ופלא ולכן ארז\"ל מוטב דלידייני' וליתי לעלמא דאתי, כדאי כל יסורי גיהנום בשביל השגה התחתונה שבגעה\"ת, דכל חיי<sup data-n=\"1132\">14</sup>* איוב ע' שנה אינו כדאי נגד שעה אחת גיהנם מ\"מ מוטב דלידייני' וליתי לעלמא דאתי להשיג השגה התחתונה שבגעה\"ת. אך הנה מעט למטה<sup data-n=\"1133\">15</sup>* וזהו שארז\"ל ר\"א ור\"ע ראו כרך גדול של רומי ר\"א בכה ור\"ע שחק, ר\"א בכה שכ\"כ עונג העליון נפל למטה כרך מלא תענוגים גשמיי', ור\"ע שחק אם לעוברי רצונו כך נמשך עונג העליון בדרך נפילה ושבירה לעושי רצונו שמבררים את זאת עאכו\"כ שיומשך עונג העליון למעלה. דהנה כתי' וכל קרבי<sup data-n=\"1134\">16</sup> שם קדשו, שיש מלאכים שנק' קרביים, כמו קרבי אדם מבררים את האוכל והמובחר עולה למוח ולב והפסולת נדחה לחוץ כמו\"כ מלאכים הם מבררים, דכמו שיש מלאכים שהם שלוחי השפע כמו\"כ יש מלאכים שע\"י עולין וכמ\"ש ומלאכי אלקים עולין ויורדים בו [סולם הוא תורה ותפלה], ועונג זה יומשך לתחה\"מ. וזהו ההפרש בין ג\"ע לתחה\"מ, דג\"ע הוא בחי' ממכ\"ע שיש בו התחלקות מעלה ומטה ולכן בג\"ע יש ב' מדרי' כמו באדם יש ראש וגוף שאין ערוך לגוף לגבי הראש וכן ראש ורגל שיותר אין ערוך כמו\"כ בג\"ע יש עליון ותחתון, ובתחה\"מ יאיר בחי' סוכ\"ע לכן יהי' רק מדרי' א'. הגם שארז\"ל כאו\"א נכוה בחופתו של חבירו, הכל בבחי' מקיף, דמי שיכול לקבל מקיף זה אינו יכול לקבל מקיף היותר עליון, דמקיף הוא מה שאינו יכול להאיר בפנימיות ומכ\"ש מקיף למעלה מזה שאינו יכול לקבל [אבל הכל בבחי' מקיף] ולכן צריכים נשמות להתלבש בגופים שיאיר בחי' סוכ\"ע.\n<b>וביאור</b> הענין דהנה כתי' והאופנים וחיות הקודש ברעש גדול<sup data-n=\"1135\">17</sup>, וצ\"ל והלא שרפים הם למעלה מאופנים מפני מה שרפים אינם ברעש ואופנים ברעש. והענין דהנה שרפים משיגים איך שא\"ס הוא קדוש ומובדל וכמ\"ש שרפים עומדים ממעל לו ויש ב' פי' א' ממעל לש' אד' שכ' תחילה ואראה את אד' שהוא בחי' אנת אשתמודע אדון על כולא ושרפים הם למעלה מהם, דאימא עילאה מקננא בכורסייא שהוא השגה לכן אינו ברעש, והוא כמו בן כרך שראה את המלך, והאופנים וחיות הקדש שהם ביצי' והאופנים בבריאה<sup data-n=\"1136\">18</sup>* אינם משיגים איך שהוא קדוש אלא שיודעין שהוא קדוש וזהו הרעש והוא מצד העדר השגה, ואם מזה הרעש גדול כ\"כ שהוא רק העלם יצי' על בריאה מכ\"ש העונג העליון",[["1132","14","<b>חיי איוב</b>: כ\"ה בגוכי\"ק. ובד\"כ הל' בדרושים הוא: יסורי איוב."],["1133","15","<b>אך הנה מעט למטה</b>: אוצ\"ל: מעט נפל למטה. ראה הל' לעיל במאמר (ע' תקיד): ואמנם יש מבחי' התענוג מה שנפל בשבה\"כ, והוא בלעו\"ז."],["1134","16","<b>דהנה כתי' וכל קרבי את שם קדשו</b>: ראה בהנסמן בכ\"ז בהמ\"מ לעיל בהמאמר (ע' תקיד)."],["1135","17","<b>וביאור הענין דהנה כתי' והאופנים וחיות הקודש ברעש גדול</b>: ראה ע\"ז לעיל בהמאמר ע' תקטו. וש\"נ."],["1136","18","<b>והאופנים בבריאה</b>: נראה דצ\"ל: בעשי'."]]],[2002180355,"שנתרחק כ\"כ, ומזה גופא מובן מאחר שנפל למטה יותר מובן שהוא בשרשו גבוה יותר, וכמו נפילת החומה האבן שבראש החומה נופל למרחוק יותר, וכשיתבונן איך<sup data-n=\"1137\">19</sup>.\n(ע\"כ נרשם בגוכי\"ק, וחסר סיום)",[["1137","19","<b>וכשיתבונן איך</b>: ראה המשך הענין לעיל במאמר ע' תקטז ואילך."]]],[2002180356,"<h3>את ה' האמרת (ש\"פ נצבים)</h3>\n<b>ש\"פ נצבים טל לפ\"ק</b>\n<b>את</b> ה' האמרת<sup data-n=\"1138\">1</sup> היום כו' וה' האמירך היום. וצ\"ל אומרו היום שהוא מיותר, הנה אי' בספרים כ\"מ שנא' היום סתם קאי על ר\"ה<sup data-n=\"1139\">2</sup> כמ\"ש ויהי היום ויבואו בני אלקים, וכן כאן שנא' היום קאי על ר\"ה, וצ\"ל דכל הפי' שיש בהאמרת יש בר\"ה ג\"כ. והנה נת\"ל דבוהאמרת יש ג' פי', אחד ל' רוממות ושבח וכמארז\"ל אתם עשוני חטיבה א' בעולם אף אני אעשה לכם חטיבה א' בעולם ומפ' הת\"י האמרת כמו חטיבה, אתם עשוני כו' ה' אחד אף אני כו' גוי אחד וזהו שבח דהאמרת והאמירך, ב' ל' לבוש וכמ\"ש בצע אמרתו ופי' בתרגום בזע פורפירא דילי'<sup data-n=\"1140\">3</sup>, ג' ל' אמירה ודיבור. וצ\"ל מה שייך אחד לר\"ה דוקא והלא כל ק\"ש דמיחדים שמו בכ\"י ערב ובקר ומהו ר\"ה דוקא.\n<b>אך</b> הנה צ\"ל תחילה מה דאי' במדרש אחד אין כיוצא בו, וצ\"ל מהו השבח דאין כיוצא בו ואיך עולה על הדעת על מוח ולב האדם דיש כו' דצ\"ל אין כו', דאם הי' דבר דאפ\"ל כן ואומרי' שאינו כן זהו שבח אבל שא\"א כלל מהו השבח. והענין",[["1138","1","<b>את ה' האמרת</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה ”ומעתה צ\"ל פי' הא' שאחד הוא אין כיוצא בו\" הנדפס לעיל ע' תקיח. והוא המשך ד\"ה את ה' האמרת שלפני\"ז. וראה עוד בהמ\"מ לעיל ע' תקיח."],["1139","2","<b>הנה אי' בספרים כ\"מ שנא' היום סתם קאי על ר\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380885\" data-slug=\"likkutei-torah\" data-id=\"4001380885\">מב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380893\" data-slug=\"likkutei-torah\" data-id=\"4001380893\">מד, א</a>. סה\"מ תרל\"ב ח\"ב ע' תקצט. וש\"נ."],["1140","3","<b>וכמ\"ש בצע אמרתו ופי' בתרגום בזע פורפירא דילי'</b>: לשון זה הוא באיכ\"ר עה\"פ, וזח\"א סא, ב (ולא בתרגום איכה שלפנינו). וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450600\" data-slug=\"or-hatorah-hb\" data-id=\"8316450600\">אוה\"ת תבוא ע' תתרס</a>: במד\"ר תשא ר\"פ מ\"ה בפי' ויתנצלו בנ\"י את עדיים, פורפיראות (בגדי מל' חשובים) וכה\"א את ה' האמרת (האמרת ל' בגד כמו שפי' חז\"ל בצע אמרתו ביזע פורפירא דילי', ע\"פ מדותיו תרגום על אמרא דלבושא). ע\"כ ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450610\" data-slug=\"or-hatorah-hb\" data-id=\"8316450610\">אוה\"ת</a>. וכ\"ה באוה\"ת תבוא שם ע' תתרסט. ובאוה\"ת תבוא כרך ו' ע' ב'שפז. ועד\"ז בסה\"מ תר\"ל ע' רצ: הוא לשון לבוש וכמ\"ש בת\"י ע\"פ כשמן הטוב כו' שיורד ע\"פ מדותו דנחית על אמרא דלבושא וכן איתא במדרש איכה ע\"פ בצע אמרתו בזע פורפירא דילי' ע\"כ. אולם ע\"ד הלשון במאמר כאן בשם התרגום כ\"ה ג\"כ באוה\"ת תבוא שם ע' תתרפ. סה\"מ תרל\"ב ח\"ב ע' תעג. לעיל בהמאמר ע' תקי. ועוד."]]],[2002180357,"דהנה כתי' ואתה הוא ושנותיך לא יתמו וצ\"ל והלא שנה הוא זמן מוגבל ממש וא\"ס הוא בלתי בעל גבול ואיך שייך לומר שנותיך לנוכח. ופי' הרשב\"א<sup data-n=\"1141\">4</sup> דהנה האדם הוא בעל גבול וא\"א שישיג אוא\"ס הבבע\"ג דכל עיקר האדם הוא שכל שהוא מוגבל ואיך שייך שישיג בשכלו איך שא\"ס הוא בבע\"ג, ולכן אומרים תחילה ושנותיך שהוא גבול ואח\"כ לא יתמו כ\"כ גבול עד שיהי' בבע\"ג.\n<b>ואפ\"ל</b> באו\"א ויובן מ\"ש ושנותיך ומ\"מ לא יתמו שהוא בבע\"ג, דהנה זמן הוא מחודש ושרש הזמן הוא מבחי' מל' שהוא מלך מלך ימלוך, והוא עבר הוה עתיד, מה שכבר הלך לו ומה שיהי' וזמן הוה, אבל למעלה ממל' לא יש זמן כלל, וזהו מ\"ש כי אלף שנה בעיניך כיום אתמול, דהנה יחידות עשיריות מאות הוא בבי\"ע<sup data-n=\"1142\">5</sup> א\"כ מאות בבריאה ואלף במל' דאצי' אבל למעלה ממל' דאצי' אינו שייך זמן כלל, הגם דאי' סדר זמנים קודם לכן<sup data-n=\"1143\">6</sup>, הוא רק סדר זמנים אבל לא זמן ממש. אך מ\"מ צ\"ל דזמן יש לו שרש בא\"ס שלמעלה מזמן, דהנה אי' בעה\"ק<sup data-n=\"1144\">7</sup> דאם תאמר דיש לו כח בבלתי בעל גבול ואין לו כח בגבול אתה מחסר שלימותא וא\"ס הוא שלימותא דכולא אלא כמו שיש לו כח בלתי בע\"ג כמו\"כ יש לו כח בגבול וכח הגבול הנמצא ממנו תחילה הם כלים דע\"ס דאצי', ובד\"כ הם ל' כלים דז\"א שהם נר\"ן בבי\"ע, ועל ל' שמות הוא שם שדי שא' לעולמו די עד פה תבוא, דשם הוי' הוא למעלה מזמן דהי' הוה ויהי' כאחד, ואם הי' התהוות העולמות משם הוי' הי' הכל עולמות הא\"ס ובלי מספר כלל אבל שם שדי הוא הגבלה, אך הנה כתי' הוי' מלך הוי' מלך הוי' ימלוך הוא התחברות א\"ס הבבע\"ג עם גבול, דהנה יש מחלוקת בין חוקרים הראשונים אם נמנעו הנמנעות<sup data-n=\"1145\">8</sup> או לא נמנעו הנמנעות, והוא כהדיעה דנמנעו הנמנעות, דיש דעה דרוכב בלתי רוכב כאחד א\"א בחיק הבורא ג\"כ ולפי משנ\"ת כאן שאפ\"ל בבע\"ג וגבול כמו\"כ אפ\"ל רוכב ובלתי רוכב. וזהו אתה הוא ושנותיך לא יתמו הגם דשנותיך הוא הגבלה מ\"מ לא יתמו, וזהו אחד אין כיוצא בו דהי' אומר שא\"ס הוא בבע\"ג אבל לא גבול זהו אומרו אין כיוצא בו שהוא התחברות ב' הבחי', וזהו השבח איך אפ\"ל שניהם כאחת בבע\"ג וגבול, זהו השבח הגדול שהם שניהם כא'. וזהו\"ע שיר של ר\"ה שבו נברא אדה\"ר א' השיר ה' מלך<sup data-n=\"1146\">9</sup> גאות לבש שהו\"ע התחברות א\"ס הבבע\"ג עם בחי' גבול.",[["1141","4","<b>ופי' הרשב\"א</b>: שו\"ת ח\"א סתי\"ח."],["1142","5","<b>דהנה יחידות עשיריות מאות הוא בבי\"ע</b>: ראה בהמ\"מ לעיל ע' תקיח."],["1143","6","<b>הגם דאי' סדר זמנים קודם לכן</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, ג</a>. דרמ\"צ נז, ב. נט, א. קנא, א. סה\"מ תרכ\"ז ע' פה. ובכ\"מ."],["1144","7","<b>דהנה אי' בעה\"ק</b>: עבודת הקודש (להר\"מ בן גבאי) ח\"א פ\"ח. וראה בהמ\"מ לעיל ס\"ע תקיח."],["1145","8","<b>דהנה יש מחלוקת בין חוקרים הראשונים אם נמנעו הנמנעות</b>: ראה שו\"ת הרשב\"א המובא לעיל. ספר החקירה להצ\"צ ע' 68. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011187\" data-slug=\"likkutei-sichot\" data-id=\"1300011187\">לקו\"ש ח\"א ע' 173</a>. חל\"ו ע' 145. וש\"נ."],["1146","9","<b>וזהו\"ע שיר של ר\"ה שבו נברא אדה\"ר א' השיר ה' מלך</b>: ראה גם רשימות תהלים להצ\"צ (יהל אור) ס\"ע שלח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291332\" data-slug=\"likkutei-sichot\" data-id=\"1300291332\">לקו\"ש חכ\"ט ע' 317</a>. וש\"נ."]]],[2002180358,"<b>ועתה</b> צ\"ל מ\"ש וה' האמירך היום לשמור מצותיו וצ\"ל מה שייך זה לוה' האמירך, זה שייך למ\"ש ה' האמרת שהוא שבח ישראל משבחין אותו מה שמקבלין עומ\"ש אבל מה שייך זה לשבח ישראל. והענין דהנה ארז\"ל הקב\"ה מניח תפילין<sup data-n=\"1147\">10</sup>, הקב\"ה הוא ז\"א ומניח תפילין אין פי' תפילין גשמיים אלא הו\"ע המשכת מוחין לז\"א, ד' בתים ד' מוחין, קדש והי' כי יביאך חו\"ב שמע והא\"ש דעת שנחלק לחו\"ג, והנה אי' במדרש ע\"פ מגיד דבריו ליעקב חוקיו ומשפטיו לישראל מה שהוא עושה אומר לישראל לעשות, והפי' כך מה שהוא עושה מי הוא הגורם שהוא עושה מפני שאומר לישראל לעשות, דע\"י שישראל מניחין תפילין ממשיכים מוחין לז\"א, וע\"י ציצית ממשיכים בחי' ל\"ב חוטין ל\"ב נת\"ח, ולמעלה יותר הו\"ע ויקחני בציצית ראשי, וטלית הוא פריסא דמלכא, וזהו השבח לישראל שע\"י המצות שעושין למטה ממשיכין מלמעלה שיומשך מוחין לז\"א כו'.\n<b>אך</b> צ\"ל דהנה ארז\"ל<sup data-n=\"1148\">11</sup> אף אני אעשה כו' גוי אחד אין כיוצא בו, וצ\"ל מהו\"ע אין כיוצא בו בישראל. הענין דהנה כתי' חטא חטאה ירושלים ואי' במדרש וכי העובדים לחמה וללבנה אינם חוטאים, דמ\"ש ירושלים הוא מיותר דמדבר תחילה מענין ירושלים, אלא דאוה\"ע אף שחוטאים אינו כלום דהעבודה שלהם אינו תופס מקום כמו\"כ החטא אינו חטא, אבל ישראל שע\"י עבודתם ממשיכים המשכת אלקות לכן כשחוטאים הוא חטא, דהנה ישראל ע\"י העובדות שלהם ממשיכים המשכת אלקות, ל\"מ ע\"י מצוה, אפי' ענינים כמו ברכת נשואין ע\"י יחוד חו\"כ למטה ממשיכים מלמעלה יחוד הקב\"ה וכנס\"י שהוא כלליות חו\"כ הקב\"ה חתן וכנס\"י כלה, ולכן מברכים ע\"ז ברוך אתה הוי', ברוך הוא המשכה הוי' שיומשך שם הוי' בפרט זה ובפרט זה, ואפי' ע\"י דברים שאינם מצות כלל כמו נעילת הסנדל ממשיכים ג\"כ המשכת אלקות וראי' שמברכים ע\"ז ובזמן שאסור נעילת הסנדל אינו מברכים ג\"כ וכשמברכין הוא ברכה לבטלה, הגם דמה נפ\"מ אם נועל הסנדל א\"ל מ\"מ ממשיכים עי\"ז המשכת אלקות, ולמעלה סנדל הוא משארז\"ל סנדל קושר כתרים לקונו מתפילותיהן של ישראל והו\"ע כתר דעשי', וזהו ההמשכה שממשיכים משם הוי' עד כתר דעשי', וזהו אין כיוצא בו על ישראל, הנמצא כזה שע\"י כל מה שעושין אפי' אינו מצוה ממשיכים המשכת אלקות.\n<b>ועתה</b> צ\"ל הפי' הב' בוהאמרת<sup data-n=\"1149\">12</sup> ל' לבוש, דהנה אין מלך בלא עם הם עוממות נבראים נפרדים בע\"ג, דמלוכה אינו שייך כ\"א על נפרדים אבל על בנים אינו שייך מלוכה, וכדי שיהי' מאוא\"ס דאני הוי' לא שניתי שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה אתה הוא קודם שנברה\"ע ואתה הוא לאחר שנברה\"ע",[["1147","10","<b>ועתה צ\"ל מ\"ש וה' האמירך . . דהנה ארז\"ל הקב\"ה מניח תפילין</b>: ראה בהמ\"מ לעיל בהמאמר ע' תקיט."],["1148","11","<b>אך צ\"ל דהנה ארז\"ל אף אני אעשה . . דהנה כתיב חטא חטאה ירושלים</b>: ראה גם אוה\"ת תבוא שם ע' ב'ע. סה\"מ תרל\"ב שם ס\"ע תעה."],["1149","12","<b>ועתה צ\"ל הפי' הב' בוהאמרת</b>: ראה גם סה\"מ תר\"ל ע' רצט ואילך. סה\"מ תרל\"ב ע' תעד."]]],[2002180359,"הוא ע\"י מדת המל' שהוא אינו כמו שאר הספי', דכל הספי' הם בקירוב כמו מדת החסד אבל מדת המל' הוא בבחי' רוממות והתנשאות ולכן אפ\"ל בחי' עם ומ\"מ יהי' להם ביטול היש. והנה בחי' מל' הוא בחי' לבוש, ובלבוש יש ב' מדרגות א' לבוש הוד והדר וכמ\"ש וכבוד הדר מל', ב' כמ\"ש אלביש שמים קדרות אין פי' שמים גשמיים אלא כמ\"ש ואתה תשמע השמים שמכנים הבורא בשם שמים כמו\"כ כאן.\n<b>והענין</b> דהנה במלוכה יש ב' מדריגות, א' מה שנק' מלוכה ב' מה שנק' ממשלה<sup data-n=\"1150\">13</sup>, מלוכה הוא כשמקבלין ברצון וכמ\"ש ומל' ברצון קבלו עליהם, ב' ממשלה הוא אף שאינם רוצין מ\"מ הוא מושל ושולט עליהם, ולמעלה מלוכה הוא כשמאיר גילוי אלקות וכמו בקרי\"ס נא' ה' ימלוך דקודם קרי\"ס הי' מצד שם אלקים בגימ' הטבע אך בקרי\"ס הפך ים ליבשה [זהו יוצא מדרכי הטבע] נא' ה' ימלוך, וזהו מלכותך ראו בניך בוקע הים לפני משה, בעת בקיעת הים אז ראו מלכותך זה אלי ענו ואמרו ה' ימלוך לעולם ועד, וממשלה הוא שאע\"פ שאינם רוצין לקבל עליהם מ\"מ הוא מושל ושולט עליהם און קיין זאך טוט זיך ניט אליין. וזהו שאנו מבקשים בר\"ה גלה עלינו כבוד מלכותך, שיאיר בחי' מלוכה, והופע עלינו בהדר גאון עוזך והנשא על הארץ ביקרך כמו ר\"י קרא למאני' מכבדותא כמו\"כ כאן הוא לבוש יקר, וזהו ותמלוך אתה הוא הוי' לבדך שבחי' אתה והוא והוי' יאיר בבחי' מל'. וזהו שיר של ר\"ה ה' מלך גאות לבש, שנתלבש בלבוש גאות הוא לבוש הוד והדר.\n<b>וה'</b> האמירך היום הוא שמלביש נש\"י ג\"כ בלבוש, דהנה ארז\"ל מ\"ט עיזי מסגא ברישא<sup data-n=\"1151\">14</sup> והדר אמרא כברייתו של עולם ברישא חשוכא והדר נהורא, אימרי הוא עבודת הצדיקים שמקיימים תומ\"צ, דמצות הם לבושים ואי' ברש\"י כל בגד ובגדים שבתורה הוא מצמר ופשתן דמצינו בפסוק בגד צמר ובגד פשתן, והנה כמו בגד שעושין מצמר הכבשים דבגז כבשים יתחמם, כמו כן מצות הם לבושא כתלג חוורא ולבוש דשער רישא כעמר נקי, ובר\"ה אז זמן סליחת עוונות נמשך לבוש נושא עון ועובר על פשע וכמ\"ש אם יהיו חטאיכם כשנים כשלג<sup data-n=\"1152\">15</sup>* ילבינו אם יאדימו כתולע כצמר יהיו, וזהו אורי הוא ר\"ה דאו' לדוד ה' אורי וישעי אורי בר\"ה וישעי ביוהכ\"פ.\n<b>ועתה</b> צ\"ל הפי' הג' בוהאמרת<sup data-n=\"1153\">16</sup> ל' אמירה ודיבור, ואיזהו דיבור הוא שנק' אמירה הוא ע\"מ שנא' ויאמר אלקים, והנה בתחילת הבריאה<sup data-n=\"1154\">17</sup> הי' מצד כי חפץ חסד,",[["1150","13","<b><a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380940\" data-slug=\"likkutei-torah\" data-id=\"4001380940\">א' מה שנק' מלוכה ב</a>' מה שנק' ממשלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380944\" data-slug=\"likkutei-torah\" data-id=\"4001380944\">לקו\"ת ר\"ה נה, ב</a>. נו, ב ואילך. סה\"מ תרכ\"ז ע' תלו. ובכ\"מ."],["1151","14","<b>וה' האמירך . . דהנה ארז\"ל מ\"ט עיזי מסגא ברישא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450614\" data-slug=\"or-hatorah-hb\" data-id=\"8316450614\">אוה\"ת תבוא ע' תתרפד</a>. סה\"מ תרכ\"ז ע' שסב. תרכ\"ט ע' נח. תרל\"ג ח\"א ע' ריא. רכט."],["1152","15","<b>כשלג ילבינו</b>: אי\"ז ברור בגוכי\"ק כאן."],["1153","16","<b>ועתה צ\"ל הפי' הג' בוהאמרת</b>: בהבא לקמן — ראה גם סה\"מ תר\"ל ע' ש ואילך. סה\"מ תרל\"ב ח\"ב ע' תעד. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381178\" data-slug=\"likkutei-torah\" data-id=\"4001381178\">לקו\"ת שה\"ש יב, ב</a>. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' לג ואילך."],["1154","17","<b>והנה בתחילת הבריאה הי' מצד כי חפץ חסד .ֿ. כי אמרתי עולם חסד יבנה</b>: ראה גם סה\"מ תרכ\"ז ע' קמ. קמב. תרכ\"ט ע' ט. עג. תו. ועוד."]]],[2002180360,"מצד טבע הטוב להיטיב, ועכשיו באתעדל\"ת תליא מילתא וכמ\"ש כי אמרתי עולם חסד יבנה כשצריך להיות התהוות העולמות צריכים לבנות תחילה מדת החסד. וזהו זה היום תחילת מעשיך זכרון ליום ראשון, ומהו\"ע זכרון ליום ראשון, אלא כמו שביום ראשון הי' מצד כי חפץ חסד כמו\"כ עכשיו יומשך בבחי' כי אמרתי עולם חסד יבנה. וזהו את ה' האמרת שממשיכים בחי' עשרה מאמרות. ומ\"ש את הוי' האמרת שממשיכים שם הוי' בבחי' אמירה, דהנה ארז\"ל גדולים מעשה צדיקים ממעשה שמים וארץ, דמעשה שו\"א הוא מש' אלקים ואפי' בראשית נמי מאמר והוא בחי' מאמר א' הרי כ' בראשית ברא אלקים, ולכן הוא יש מאין שאינו מושג, אין הארה, אבל צדיקים ממשיכים משם הוי' לשם אלקים שהוא קיום העולם יסוד כמ\"ש צדיק יסוד עולם והוא בחי' סוד הוי' שהוא יסוד העולם, וזהו יסוד י' סוד, י' הוא כלליות שם הוי' הוא היסוד, אך למעלה אינו כמו למטה דלמטה היסוד למטה והבנין למעלה, למעלה הבנין למטה והיסוד למעלה.\n<b>אך</b> ע\"י מה ממשיכים שם הוי' בוהאמרת, זהו מ\"ש האמרת שהוא ל' אמר דכתי' יום ליום יביע אמ\"ר ר\"ת אש מים רוח<sup data-n=\"1155\">18</sup>, שהקול כלול מאמ\"ר ואח\"כ נפרט בכמה פרטי אותיות הדיבור, ובעבודה הו\"ע על ג' דברי' העולם עומד על התורה ועל עבודה ועל גמ\"ח, עבודה הוא קרבנות שהי' מקריבין בהמה ע\"ג המזבח שהיתה נכללת באש שלמעלה דארי' דאכיל קורבנין, כמו\"כ צ\"ל הקרבת נה\"ב וכמ\"ש ואהבת את ה' אלקיך בכל לבבך בשני יצריך, שגם היצה\"ר יהי' לו אהבה לאלקות, היינו כח המתאווה שבאדם יהי' לו אהבה לאלקות, וכמו בקרבן עיקר ההקרבה הוא חלב ודם כמו\"כ כתי' כמו חלב ודשן תשבע נפשי היינו שיהפוך התענוג לאלקות וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ שלא ירצה לא געה\"ע ולא געה\"ת כ\"א א\"ס עצומ\"ה, וגמ\"ח הו\"ע מים יורדי' מגבוה לנמוך המשכת החסדים מלמעלמ\"ט, ותורה הוא רוח שהו\"ע הבל הפה ועי\"ז יהי' בחי' התדבקות רוחא ברוחא.\n<b>וכמו\"כ</b> בר\"ה הנה ארז\"ל ג' ספרים נפתחין בר\"ה והוא בחי' ג' ספרים שבהן ברא כו' בספר וסופר וסיפור, סיפור הוא בחי' מל' אמירה ודיבור שיומשך בו בחי' ספר וסופר וכמ\"ש איה סופר איה שוקל<sup data-n=\"1156\">19</sup> כו', שאיה בעצמו הוא שוקל ומודד, והו\"ע בוצינא דקרדוניתא שמודד כל המדידות דאבי\"ע ומשגיח על כל פרט ופרט, והוא ע\"י קול שופר שכלול מאש מים רוח, וסדר תקיעות הם תר\"ת והו\"ע ג' דברים כו' ג' ספרים. וזהו בשאר ימות השנה ממשיכים משם הוי' בוהאמרת ע\"י תומ\"צ ובר\"ה ע\"י קול שופר שהו\"ע צעקה פנימיות מעומקא דליבא.",[["1155","18","<b>דכתי' יום ליום יביע אמ\"ר ר\"ת אש מים רוח</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370025\" data-slug=\"torah-or\" data-id=\"3901370025\">תו\"א בראשית ו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381178\" data-slug=\"likkutei-torah\" data-id=\"4001381178\">לקו\"ת שה\"ש יב, ב</a>. סידור עם דא\"ח נב, ד. קפא, ב. רסד, ד. מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' לד. וש\"נ."],["1156","19","<b>וכמ\"ש איה סופר איה שוקל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370238\" data-slug=\"torah-or\" data-id=\"3901370238\">תו\"א שמות נג, ב</a> ואילך. ס' מאמרי אדה\"ז תקס\"ה ח\"א ע' רה. ועל נביאים ע' קכג."]]],[2002180361,"<b>וה'</b> האמירך היום הוא משארז\"ל כל הקורא בתורה<sup data-n=\"1157\">20</sup> הקב\"ה קורא ושונה כנגדו, והיינו שגורם דיבור למעלה, וזהו כל הקורא בתורה כאילו קורא בשמותיו של הקב\"ה כמו כשקוראין לא' בשמו נפנה עצמותו אליו כמו\"כ למעלה נמשך עצמיות אוא\"ס, באיזה כח הוא זהו והוי' האמירך שהוא בכח שם הוי'. ואח\"כ כתי' להיות לו לעם סגולה, דהנה רפואה הוא ע\"פ טו\"ד וסגולה הוא למעלה מטו\"ד פי' שאין בזה טעם הגלוי אבל טעם סתום יש, וזהו מה שהוי' האמירך הוא בבחי' סגולה. ולתתך עליון על כל הגוים לתהלה לשם ולתפארת<sup data-n=\"1158\">21</sup>, הרי ג' בחי' חב\"ד, ג' דברים, לתהלה הוא כמ\"ש בהלו נרו על ראשי שהוא בחי' אש, ולשם הוא כמ\"ש ויעש דוד שם וצ\"ל הרי קודם הי' ג\"כ שם אלא שעשה הגדלה בהשם שהמשיך מקדמות השכל וכמ\"ש אשר הלך אלקים לפדות לו לעם ולשום לו שם, מצינו שהלך הקב\"ה ת\"ק שנה לעשות לו שם, והיינו שנמשך ה\"ח המגדילים בחי' מל', ולתפארת הוא תורה שהוא רוח. וזהו ה' האמרת שממשיכים והאמרת מבחי' שם הוי', אך ע\"י מה ממשיכים זה זהו וה' האמירך שע\"י וה' האמירך ממשיכים בחי' וה' האמרת.",[["1157","20","<b>וה' האמירך היום הוא משארז\"ל כל הקורא בתורה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450600\" data-slug=\"or-hatorah-hb\" data-id=\"8316450600\">אוה\"ת תבוא ע' תתרסט</a>. תתרפח."],["1158","21","<b>ולתתך עליון . . לתהלה לשם ולתפארת</b>: ראה גם לקו\"ת תבוא מה, ג. ובכ\"מ."]]],[2002180362,"<h3>תפלה לעני (ליל ב' דר\"ה תר\"מ)</h3>\n<b></b><b>בס\"ד ליל ב' ר\"ה ט\"ל [תר\"מ] לפ\"ק. ליובאוויטש</b>\n<b>תפלה</b> לעני<sup data-n=\"1159\">1</sup> כי יעטוף ולפני ה' ישפוך שיחו. וצ\"ל מהו כי יעטוף שהוא מיותר. וגם צ\"ל אומרו ולפני ה' ישפוך שיחו, שיחו הוא תרעומות<sup data-n=\"1160\">2</sup> (ובפ\"א כמ\"ש כי מרוב<sup data-n=\"1161\">3</sup> שיחי וכעסי). הנה יש תרעומות שהוא מתרעם לפני ה'. והענין דהנה כתי' תקעו בחדש שופר בכסה ליום חגינו, הנה נא' בחדש, בשאר חדשי השנה נא' איזה חדש וכאן א' חדש סתם. והנה ארז\"ל איזה חג שהחדש מתכסה בו הוי אומר זה ר\"ה, דכל המועדים הם באמצע החדש ור\"ה הוא בר\"ח, וצ\"ל והלא בתורה נא' בחודש השביעי באחד כמו\"כ הול\"ל כאן תקעו בחדש השביעי כו' ולמה נא' סתם ואח\"כ בכסה ליום חגינו ללמוד שהוא ר\"ה, וצריכים לומר שענין תקיעת שופר הוא מפני שבכסא ליום חגינו, ולכאורה נראה שענין תק\"ש הוא מצוה כמו כל המצות. והענין דהנה כתי' ארץ אשר ה' אלקיך דורש אותה תמיד<sup data-n=\"1162\">4</sup> עיני ה' אלקיך בה מראשית השנה ועד אחרית שנה,",[["1159","1","<b>תפלה לעני</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה תקעו בחודש הנדפס לעיל ע' תקלד. וע\"ש בהמ\"מ בתחילת המאמר."],["1160","2","<b>שיחו הוא תרעומות</b>: ראה גם לעיל בהמאמר ע' תקלח."],["1161","3","<b>ובפ\"א כמ\"ש כי מרוב</b>: ר\"ל שבפעם א' בעת חזרת המאמר ע\"י כ\"ק אדמו\"ר מהר\"ש, הוסיף כאן: כמ\"ש כי מרוב כו'."],["1162","4","<b>דהנה כתי' ארץ אשר ה' אלקיך דורש אותה תמיד</b>: ראה בארוכה בכ\"ז ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450601\" data-slug=\"or-hatorah-hb\" data-id=\"8316450601\">אוה\"ת עקב ע' תרא</a> ואילך. וע' תרה ואילך."]]],[2002180363,"מרשית הוא חסר א' וארז\"ל כל שנה שהיא רשה בתחילתה מתעשרת בסופה, סוף שיש לו אחרית וכמ\"ש ואחריתך ישגה מאד, וכמו ויש תקוה לאחריתך, דאחרי\"ת ע\"ה גימ' כתר<sup data-n=\"1163\">5</sup>, ופירוש כל שנה שהיא רשה הוא שישראל עושין עצמן רשין ודלים ומדברים תחנונים לפני המקום כמ\"ש תחנונים ידבר רש, וצ\"ל מה שייך רש לר\"ה.\n<b>והענין</b> דהנה כתי' תפלה לדוד הטה ה' אזנך ענני כי עני ואביון אני, וצ\"ל והאיך קורא א\"ע עני והרי הי' חסיד וכמ\"ש שמרה נפשי כי חסיד אני, וחסיד ועני הם כמו ב' הפכים, דעני אין פי' בגשמיות שהרי הי' מלך ישראל אלא כמשארז\"ל אין עני אלא בדעת, וחסיד הוא כמ\"ש איזה חסיד המתחסד עם קונו עם קן דילי'<sup data-n=\"1164\">6</sup> והוא למעלה מצדיק, ואם הי' עני איך הי' במדריגת חסיד ואם הי' חסיד איך הי' במדרי' עני. וגם צ\"ל מ\"ש ענני כי עני כו' מהו המעלה דעני, ובאמת הנה אי' בגמ' יאה עניותא לישראל, ובמד' אי' ג\"כ יאה עניותא לברתא דיעקב כערקא סומקא ברישא דסוסווא חיוורא, הרי יאה וכאן משמע שהוא בא בטענה מצד זה, וצ\"ל מהו המעלה.\n<b>והענין</b> דהנה בתפלה יש תפלה למשה איש אלקים ותפלה לעני ואי' בזהר שהם חדא דרגא, וצ\"ל והיאך הם שוין דא\"כ מהו מעלה דאיש אלקים. והנה בזה יובן מ\"ש זה עני קרא וה' שמע וצ\"ל תי' זה הוא מיותר, ומאחר דעני הוא מעלה הו\"ל עני קרא, הנה זה הוא משה וכמארז\"ל כל הנביאים נתנבאו בכה הוסיף עליהם משה שנתנבא בזה וכמ\"ש כי זה משה האיש, שהוא איש מבחי' זה, וארז\"ל יבוא זה ויקבל זאת מזה לעם זו, יבוא זה זה משה, וזהו זה שהוא משה ועני קרא שניהם שוים. ועוי\"ל זה עני קרא, זה שהוא עני<sup data-n=\"1165\">7</sup>. והענין דהנה כתי' אל זה אביט אל עני ונכה רוח ולכאו' משמע דעני ונכה רוח הם ב' מדריגות, ובאמת הפי' כך עני שהוא נכה רוח דתחילה קאמר אל ז\"ה אביט שהוא בחי' עשיר מ\"מ הוא עני שהוא נכה רוח שמשפיל א\"ע, דאינו שייך לומר שהוא עני בעצם דאין עני אלא בדעת והרי יש לו דעת וענין הדעת הוא התקשרות וכמ\"ש דע את אלקי אביך ועבדהו בלב שלם וכמ\"ש וידעת היום והשבות אל לבבך כי ה' הוא אלקים מ\"מ הוא כמו עני שהוא שפל בעיני עצמו, כמו\"כ הוא משפיל א\"ע שכל הדעת שלו אינו תופס מקום כלל ואינו בערך כלל וכמ\"ש והייתי שפל בעיני ועם האמהות אשר אמרת עמם אכבדה, שהי' שפל בעצם. דהענין הוא דתכלית הידיעה שלא נדע, דבא\"ס אינו שייך ידיעה שהוא למעלה מהשגה דהחקר אלוקה תמצא, אך לא שיתחיל בלא נודע א\"כ לא יהי' עבודה כלל, אלא כל מה שיוכל להשיג בהשגה ישיג ואח\"כ יבוא לבחי' לא נדע. וזהו הגם שהוא עשיר מ\"מ הוא משפיל א\"ע כעני, ובאמת לגבי בחי' שלא נדע ה\"ה עני",[["1163","5","<b>דאחרית ע\"ה ( עם הכולל] גימ' כתר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380128\" data-slug=\"likkutei-torah\" data-id=\"4001380128\">לקו\"ת צו יג, א</a>. אוה\"ת ויחי שנח, ב (בשם המאו\"א). דרושים לר\"ה ע' א'שצג. סה\"מ תרכ\"ז ע' תכח. תרל\"ב ח\"א ע' לה."],["1164","6","<b>איזה חסיד המתחסד עם קונו עם קן דילי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא ספ\"י (טו, ב</a>)."],["1165","7","<b>ועוי\"ל זה עני קרא זה שהוא עני</b>: ראה הלשון לעיל בהמאמר (ס\"ע תקלה): ועוי\"ל זה עני שהגם שהוא בבחי' זה בחי' עשיר, זה תפארת בחי' עשיר אספקלריא המאירה כו'."]]],[2002180364,"דמאחר שאינו שייך השגה כלל, והוא כמ\"ש אדם ובהמה תושיע ה' וארז\"ל ערומים בדעת כאדם ומשימים עצמן כבהמה ופירש\"י כאדם כאדה\"ר שהוא בחי' ח\"ס שעז\"נ אני חכ' שכנתי ערמה<sup data-n=\"1166\">8</sup> דחכ' הוא רק שכן לערמה דערמה הוא למעלה בחכ'<sup data-n=\"1167\">9</sup>* וכמו למטה חכם הוא שמדבר בשכל וערמה הוא שמסבב הענין וכמו שמרחק א\"ע מזה ובזה הוא פועל דהמנגד אינו עומד לכנגד כ\"כ, וכמו\"כ ביראה צ\"ל ערום ביראה, וכמו\"כ למעלה יש ג\"כ ערמה דכמו שיש ערמה בלעו\"ז והנחש הי' ערום כמו\"כ יש ערום בקדושה בא אחיך במרמה ועז\"נ אני חכ' שכנתי ערמה דחכ' הוא רק שכן לערמה דזה חכ' סתם וזה חכ' סתימאה, ומשימים עצמן כבהמה פירש\"י דכי הרוח, דבהמה אין לה דעת וזהו ומשימין עצמן כבהמה שהוא משפיל א\"ע והוא ביטול דלמעלה מטו\"ד.\n<b>ועוי\"ל</b> דזה עני קרא שהוא תפלה לעני ותפלה למשה, דאי' בזהר דתפלה לעני הוא קדם לתפלה למשה, וצ\"ל איך הוא קדום, דאפי' כמו שנת\"ל דהם שוין ג\"כ אינו מובן דכל אפי שוין, אבל לומר שהוא קדום זה ודאי אינו שייך לומר כלל. והנה ראי' לזה הוא מתפילין של יד ותש\"ר, דתש\"י הוא בחי' עני ותש\"ר הוא בחי' עשיר, ולכן תש\"י מניחים על יד שמאל שהוא יד כהה ולכן בתש\"ר ד' פרשיות בד' בתים שכל דבר הוא בריבוי ותש\"י הוא בבית א' ועי\"ז בו כל מה שיש בתש\"ר רק שהוא בקטנות וצמצום, ומ\"מ מקדימים תש\"י לתש\"ר.\n<b>והנה</b> להבין זה צ\"ל תחילה למה ברא הקב\"ה את העניים<sup data-n=\"1168\">10</sup>, והלא ברא הקב\"ה את האדם צריך לברוא לו כל ההצטרכות שלו, היד ה' תקצר, וכמ\"ש איש תחת גפנו ואיש תחת תאנתו, ומ\"מ כתי' שם לא יחדל אביון מקרב הארץ וצ\"ל למה. והנה בגמ' מתרץ דכתי' מלוה ה' חונן דל, כדי שיהי' מלוה ה' הוא ע\"י חונן דל, דכשברא הקב\"ה את האדם צריך ליתן לו כל ההצטרכות, ותמורת שצריך הקב\"ה ליתן לו נותן לו האדם ה\"ה מלוה ה' ע\"י שחונן דל ואח\"כ יתן לו הקב\"ה בריבוי כפלי כפליים וע\"ד מ\"ש עשר בשביל שתתעשר שהוא נותן רק חלק עשירי ועי\"ז תתעשר בריבוי ואפשר שיהי' לו יותר מכפי שהי' תחילה בסוד שרש, אך מ\"מ אינו מובן למה צ\"ל עני שיהי' מלוה ה', יתן לו הקב\"ה ההצטרכות משלו ולא יהי' מלוה ה'. ובמד' יש תירוץ אחר כדי שבנ\"א יזכו זא\"ז, דהעשיר מזכה העני בההשפעה גשמיות והעני משפיע לעשיר השפעה רוחניות דמזכה אותו במצות צדקה שהוא מצוה גבוה דכלליות כל המצות הם צדקה דמה איכפת לו להקב\"ה אם שוחט מן העורף או שוחט מן הצואר אלא לא ניתנו המצות אלא לצרף את הבריות וזהו צדקה וכמ\"ש כי כל מצותיך צדק, וזהו דכתי' גבי רות אשר עשיתי עמו הגם שהיא קיבלה מ\"מ נק' עשיתי עמו שזיכתה אותו",[["1166","8","<b>שעז\"נ אני חכ' שכנתי ערמה</b>: לעיל בהמאמר מציין ע\"ז כ\"ק אדמו\"ר מהר\"ש לד\"ה ומקנה רב (נדפס באוה\"ת מטות ע' א'שמג). וראה גם סה\"מ תרל\"ג ח\"א ס\"ע מד-ה. וש\"נ."],["1167","9","<b>למעלה בחכ'</b>: כ\"ה בגוכי\"ק. ואוצ\"ל: למעלה מחכ'."],["1168","10","<b>והנה להבין זה צ\"ל תחילה למה ברא הקב\"ה את העניים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450551\" data-slug=\"or-hatorah-hb\" data-id=\"8316450551\">אוה\"ת עקב ע' תקנא</a>."]]],[2002180365,"במצוה גבוה. והנה תירוץ זה הוא מתקבל יותר מתי' הגמ', דלפי תירוץ הגמ' משמע שהריווח הוא רק להעשיר ולפי תירוץ המדרש דיש ריווח לשניהם להעני ולהעשיר.\n<b>וביאור</b> הענין דהנה בכלליות סדר השתל' הוא בחי' משפיע ומקבל השמים הוא משפיע בארץ וכמ\"ש כאשר ירד הגשם והשלג מן השמים כו' כ\"א הרוה כו' וכתי' אני אענה את השמים והם יענו את הארץ, ולמעלה שמים הוא אש ומים ז\"א וארץ הוא מל' והו\"ע מדות ודיבור המדות משפיעים בדיבור דהאדם מדבר המדה שבלב, ולמעלה יותר הוא חו\"ב חכ' אב ובינה אם, ולמעלה עוד יותר הנה אי' בע\"ח דכל עצמות דעתיק<sup data-n=\"1169\">11</sup> הוא שני בחי' שבו מ\"ה וב\"ן, מ\"ה שבו הוא דכורא דעתיק וב\"ן שבו הוא עתיק דנוק', הרי שאפי' בעתיקא קדישא ג\"כ יש משפיע ומקבל, אפי' בכלליות העולמות הנה הקו שנמשך בכלליות אבי\"ע הוא נשפע מא\"ס שלפני הצמצום דהנה כשהי' הצמצום סבל בתוכו כל העולמות וא\"כ כל העולמות ואפי' עולמות הא\"ס כל שנק' עולם ל' העלם שנגע בו הצמצום הוא בחי' מקבל וא\"ס שלפני הצמצום הוא בחי' משפיע, ועל ל' השמות הם שם הוי' ושם אלקי', הוי' הוא משפיע ושם אלקי' ושם אד' הוא מקבל, וזהו וה' בהיכל קדשו, היכ\"ל בגימ' אד' כוס בגימ' אלקים כמו שהכוס מקבל יין והיכל מקבל אדם כמו\"כ אלקים ואד' מקבלים שם הוי', ועל ל' הזהר הו\"ע יחוד שמשא וסיהרא, סיהרא הוא בחי' עני דסיהרא לית לה מגרמא כלום ושמשא הוא בחי' עשיר, והנה ע\"י שהעשיר משפיע לעני גורם יחוד עשיר ועני פי' יחוד שמשא וסיהרא, ועי\"ז ניתוסף בשמשא ג\"כ, וכמו למטה לכאו' רק המשפיע משפיע להמקבל ובאמת שהמשפיע מקבל מהמקבל ג\"כ והוא הקבלת עונג שהוא מצד המקבל, כמו\"כ למעלה ניתוסף בבחי' משפיע ג\"כ. וכמ\"ש צדיק אבד<sup data-n=\"1170\">12</sup>, אבד מלקבל ברכאן מלעילא, וכמארז\"ל אין נותנין לאדם פרנסה אלא בשביל אשתו ובניו, ומפרשים כך אין נותנין לאדם העליון כו', כמו למטה כשהוא מפרנס אשתו ובניו נותנין לו יותר וכשאינו מפרנס כו' נותנין לו הכל לפי ערך, פרנסה הוא הריווח לבד מה שנקצב לו להכרח, ה\"ה בשביל אשתו ובניו, כמו\"כ אין נותנין לאדם העליון פרנסה אלא בשביל אשתו ובניו<sup data-n=\"1171\">13</sup>, אשתו הוא כנס\"י ובניו הוא נש\"י בני בכורי ישראל, דכשיש משפיע ומקבל נמשך בהמשפיע יותר וכמ\"ש זכר ונקבה בראם ויברך אותם אלקים אימתי ויברך<sup data-n=\"1172\">14</sup>.\n(ע\"כ נרשם בגוכי\"ק, וחסר סיום)",[["1169","11","<b>הנה אי' בע\"ח דכל עצמות דעתיק</b>: ראה גם אוה\"ת ויקרא (כרך ב) ע' תק. סה\"מ תרכ\"ו ע' עז."],["1170","12","<b>וכמ\"ש צדיק אבד</b>: התוכן מכאן עד סיום הפיסקא, ליתא לעיל בהמאמר (ע\"ש ס\"ע תקלז)."],["1171","13","<b>וכמארז\"ל אין נותנין פרנסה לאדם אלא בשביל אשתו ובניו</b>: ראה גם סה\"מ תרל\"ג ח\"א ע' ריט. רמד. רנא. וש\"נ. [ועי' ב\"מ נט, ב. ובמ\"מ ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381130\" data-slug=\"likkutei-torah\" data-id=\"4001381130\">לקו\"ת ברכה ק, ב</a>. ובס' מאמרי אדהאמ\"צ נ\"ך ע' קכה. וכאן מוסיף ”ובניו\"]."],["1172","14","<b>ויברך אותם אלקים אימתי ויברך</b>: ראה המשך הענינים לעיל בהמאמר ר\"ע תקלח ואילך."]]],[2002180366,"<h3>מזמור לתודה</h3>\n<b></b><b>בס\"ד. פ' אמור שנת תרל\"ט, ליובאוויץ.</b>\n<b>מזמור</b> לתודה<sup data-n=\"1173\">1</sup> הריעו להוי' כל הארץ, הנה הריעו להוי' כל הארץ ר\"ת הלכה, וצ\"ל מה שייך תודה להלכה. אך הנה אי' בגמ' כל הקרבנות בטלין<sup data-n=\"1174\">2</sup> לע\"ל חוץ מקרבן תודה, והלכות נמי אינן בטלין לע\"ל לכן שייך תודה להלכה. אך ע\"ז שאי' כל הקרבנות בטלין מקשין והלא אנו אומרים בנוסח המוסף ושם נעשה לפניך את קרבנות חובותינו משמע שלא יבטלו, ומתרצין זה שאנו אומרים ושם נעשה כו' קאי על קרבנות ציבור שהם אינם בטילין אבל קרבנות יחיד בטלין, ותודה אף שהיא קרבן יחיד מ\"מ לא יבטל לע\"ל, וצ\"ל מהו\"ע תודה. הנה תודה הו\"ע הודאה ואי' בגמ' ארבעה צריכין להודות וקחשיב יורדי הים והולכי מדבריות ופירש\"י מפני שיצאו מסכנה צריכין להודות ע\"ש הנס, ומהו\"ע של הד' זהו נגד ד' אותיות הוי' וד' גאולות וד' לשונות של גאולה והוצאתי והצלתי וגאלתי ולקחתי. ובסי' האריז\"ל פי' מזמור לתודה הוא יחוד חו\"ב דיצי', וצ\"ל מהו\"ע הודאה אצל חו\"ב.\n<b>והענין</b> הוא דהנה כתי' כי אל דעות הוי' שיש ב' מיני דיעות ד\"ע וד\"ת, וע\"פ הקבלה ד\"ע הוא יסוד אבא וד\"ת הוא יסוד ז\"א, וע\"ד החסידות ד\"ע הוא שלמעלה היש אמיתי ומה שלמטה הוא אין וקמי' כולא כלא חשיב, וד\"ת הוא שלמטה היש ולמעלה הוא אין ונתהוה בריאה יש מאין. ולהבין ענין בריאה יש מאין הענין הוא כי יש בחי' השתל' עו\"ע שאין זה דבר חדש שהעלול הי' כלול תחילה בעילה, והמשל לזה הוא מחשבה ודיבור, שכל ומדות, שהדיבור הי' כלול תחילה במח' והמדות בשכל, והגם שעיקר המדות הם בלב, אך תחילה נמשכים מבינה כדאי' בגמ' חמשים שערי בינה נבראו בעולם, ומהו\"ע השערי בינה הנה כתי' אם הבנים שמחה שבינה נקרא אם והבנים הם המדות שהבינה מוליד את המדות, ומהו\"ע חמשים כי יש ז' מדות מן לך הוי' הגדולה עד לך הוי' הממלכה יש ז' מדות וכל מדה כלול מז' שבתיקון יש התכללות חסד שבגבורה גבורה שבחסד, שכל פרט יש לה הטי' בשכל כשמבין שהדבר טוב לו הוא עושה המדה, ואם לא הי' מבין שטוב לפניו הדבר לא הי' עושה המדה, ושער הנו\"ן הוא עצם הבינה, ומהו לשון שער פי' שער הוא שמשמש כניסה ויציאה, שעל ידו הוא יציאה מבינה למדות, וזהו בחי' השתל' עילה ועלול, שהמדות הי' כלולים תחילה בשכל שנק' מדות שבשכל ואח\"כ נמשכים מהעלם אל הגילוי שנק' אז מדות שבלב. וכך יש להבין ממשל מחשבה ודיבור, שהדיבור הי' כלול תחילה במח', שכשאדם מדבר צריך תחילה לחשוב האיך לדבר",[["1173","1","<b>מזמור לתודה</b>: הנחת א' מהשומעים מהמאמר הנדפס לעיל ע' שסז ואילך. — הנחה זו נמצאת בכת\"י 1185. וראה לעיל ע' תקסג הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר.\nהמ\"מ למאמר זה כבר נסמנו לעיל בהמאמר, ולא נכפלו כאן עוה\"פ."],["1174","2","<b>אי' בגמ' כל הקרבנות בטלין</b>: לעיל בהמאמר מביא זה ממד\"ר פ' צו פ\"ט."]]],[2002180367,"וכן בעת הדיבור צריך לחשוב כי אם לא יחשוב בעת שמדבר אין להדיבור שום חיות, הרי מזה ג\"כ נוכל להביא משל להשתל' עו\"ע שהעלול הי' כלול תחילה בעילה.\n<b>אבל</b> בריאה יש מאין שנברא יש הגשמי, הרי זה א\"א לומר שיש הגשמי הי' כך בהעלם תחילה בהאין, זה א\"א להיות, וכן המחקרים אומרים שבריאת העולם הי' דבר מלא דבר, שמלא דבר נתהוה דבר, וזה א\"א להיות שהדבר הי' תחילה בהעלם בלא דבר שמאחר שהוא לא דבר א\"א להיות בו דבר. וכן מלשון יש מאין ג\"כ יש להבין שהפי' אין הוא בלתי מושג ויש הוא דבר שמושג, וזה א\"א להיות שהיש המושג הי' תחילה בהעלם באין שבלתי מושג, מאחר שקוראים אותו בלתי מושג האיך יהי' בו יש המושג, ואם הי' בו היש המושג מפני מה קוראים אותו אין שאינו מושג, אלא שהבריאה הי' יש מאין בחפץ ורצון הקב\"ה שיהי' בריאה יש מאין חדש שלא הי' תחילה בהאין. ודבר שהוא חידוש אין אנו מוצאים בתורה בלה\"ק תיבה אחרת אלא לשון בריאה כמ\"ש ואם בריאה יברא הוי' ופרש\"י אם בריאה מוטב ואם לאו יברא, והגם שפריך בגמ' הרי אין כל חדש תחת השמש ותירצו לאקריבו פיתחא, מ\"מ ה\"ז חידוש ונק' בש' בריאה, זהו\"ע ד\"ת.\n<b>ואף</b> שעיקר אמת הוא ד\"ע מ\"מ הרי כתי' כי אל דיעות הוי' הרי ב' דיעות הן אמת שד\"ת הוא ג\"כ אמת, שב' דיעות הם יחו\"ע ויחו\"ת, ד\"ע הוא יחו\"ע וד\"ת הוא יחו\"ת, ויחו\"ת הוא ג\"כ ענין אמת. והשורש של הב' דיעות הם משני שמות הוי' ואלקים, ד\"ע מש' הוי' וד\"ת הוא מש' אלקים, שאלקים הוא בגימט' הטבע ששניהם הם כח אלקי אלא שאלקים הוא מצמצם ומעלים ומסתיר שיהי' דבר יש ונפרד בכדי שיהי' בטל לאין. וראי' לזה שגם ש' אלקים הו\"ע אמת, אף שאין צריכין ראי' לזה שהרי ש' אלקים הוא ש' מז' שמות שאינן נמחקין, מ\"מ יש ראי' לזה בתורה שבריאת העולמות הי' רק בש' אלקים של\"ב פעמים אלקים נאמר במע\"ב ואח\"כ כתי' אשר ברא אלקים לעשות ס\"ת אמת, להורות שגם ש' אלקים הוא אמת. וצ\"ל היאך שניהם הם אמת, אלא שיש כמה מדריגות אמת, שפת אמת, ואמת, ואמת לאמיתו. וזהו\"ע מ\"ש תתן אמת ליעקב, ויעקב הוא ת\"ת שהוא אמת, ומקשים וכי ת\"ת דוקא אמת<sup data-n=\"1175\">3</sup> וחו\"ג אינם אמת, אלא שגם הם אמת רק שיש להם מנגדים, כי מחמת מדת החסד יוכל להשפיע חסד עד אין שיעור, כי טבע הטוב להיטיב, ויש מנגד לזה מדת הגבורה, וכן מחמת גבורה כתי' הן שמים לא זכו בעיניו ויוכל להיות גבורה עד אין שיעור, יש מנגד לזה מדת החסד, ומאחר שיש לכאו\"א מנגד ויכול לפסוק אין זה אמת גמור, כ\"א ת\"ת שהיא מדת הרחמים שנותן מקום לשניהם אפי' למדת הדין, שלו יהא שע\"פ דין אינו מגיע לו כלל מ\"מ ראוי לרחם עליו, שלזה מדה\"ד אינו מנגד, שמדה\"ד אינו מנגד רק שאין מגיע לו אבל שראוי לרחם עליו הגם שאינו",[["1175","3","<b>ומקשים וכי ת\"ת דוקא אמת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">לקו\"ת מטות פג, סע\"ג</a>-ד. וראה גם דרמ\"צ קפ, סע\"א ואילך."]]],[2002180368,"מגיע לו זה מדה\"ד אינו מנגד, ולכן נק' אמת גמור. ופעם מקשים על תתן אמת ליעקב<sup data-n=\"1176\">4</sup> הלא כתיב ונתתם לי אות אמת דא אות וא\"ו שהיא מדת הת\"ת ומהו תתן אמת ליעקב, הלא יעקב הוא מדת הת\"ת שהוא אמת. אלא שיש כמה בחי' אמת, ויעקב שהוא אמת, ע\"ז אומרים תתן אמת ליעקב שיהי' אמת לאמיתו. כן ש' הוי' ואלקים ג\"כ שניהם אמת, ושרש ש' אלקים הוא מאלקים חיים ומלך עולם שהוא אלקים דבינה ה\"ה ג\"כ אמת, ושרש ומקור של כל אמת הוא מתיקון ואמת שפנוי משערות, וחלילה לומר ששערות (דיגת\"ד) אינם אמת אלא שיש כמה מדריגות אמת, ובכלל שורש אמת הוא מע\"ק, וש' הוי' הוא אמת לאמיתו. וזהו\"ע מ\"ש וארא אל אברהם ושמי הוי' לא נודעתי להם ופירש\"י לא ניכרתי במדת אמיתי' שלי, וחלילה לומר שש' אל שהוא מדה\"ר וש' אלקים שהוא מדה\"ד אינם אמת, אלא שיש כמה מדריגות אמת וש' הוי' הוא אמת לאמיתו וש' אלקים שגימט' הטבע הוא ג\"כ אמת.\n<b>ולהבין</b> מהו הלשון של טבע, הנה יש מחלוקת המחקרים בתיבת טבע, בתשו' ח\"צ אי' שתיבת טבע הוא מחודש שזה קרוב לשלש מאות שנה שנתחדש תי' טבע, שעל מה שייך לומר טבע, על הנהגת העולם לא שייך לומר טבע דכתי' המכסה שמים בעבים המכין לארץ מטר שאפי' צמיחה שצריך להיות תחילה גשם ולגשם צריך להיות תחילה קישור עבים מ\"מ הרי זה כח אלקי כמ\"ש המכסה שמים בעבים שהוא ית' המכסה, אלא ענין טבע הו\"ע נסים תכופין. ושארי המחקרים אומרים שאמת בריאת העולמות הי' יש מאין אך הנהגת העולם הוא טבע, ושרש תיבת טבע הוא מלשון המשנה כמארז\"ל להודיע גדולתו של הקב\"ה אדם טובע כמה מטבעות בחותם אחד וכולן דומין זה לזה, אבל הקב\"ה טבע כל אדם בחותם של אדם הראשון ואין אחד דומה לחבירו, ונמצא שטבע הוא הנהגת העולם.\n<b>ובזה</b> נוכל להבין המד\"ר שהקשו כתי' ויכל אלקים ביום השביעי והא כתי' ששת ימים עשה והי' צריך לומר ויכל אלקים ביום הששי, וכן מצינו בתלמי המלך כאשר העתיקו את הספר תורה לפניו העתיקו ויכל אלקים ביום הששי, כדי שלא יפרוך, ואמר במד\"ר משל ע\"ז משל למלך שעשה לו טבעת מה הי' חסר חסר חותם בא שבת בא חותם, נמצא ששת ימי המעשה נק' בש' טבעת ושבת בש' חותם. ובסי' אי' בש' הזהר<sup data-n=\"1177\">5</sup> השמים מספרים כבוד אל, פי' השמים דא שמים עילאין מספרין מנהרין ומנצצין בחי' כבוד אל דנהיר לכל עיזקא ועיזקא, פי' עיזקא היא טבעת, ומהו\"ע טבעת, הנה טבעת הו\"ע עגולים כי יש עגולים ויושר עיגולים הוא העלם עד\"מ השפעת הרב לתלמידו כשמשפיע לו דבר שכל והתלמיד אינו מבין אותו אז שכל הרב מקיף את שכל התלמיד ואז השכל אצלו בבחי' העלם, ואח\"כ כשמבין אותו אזי הוא מקיף את שכל הרב ואז הוא בבחי' יושר, עד\"מ בששת ימי המעשה נבראו",[["1176","4","<b>ופעם מקשים על תתן אמת ליעקב</b>: ראה אגה\"ק סי' ו (קט, ב ואילך). וראה גם סה\"מ תרל\"ד ע' רסא. וע' שס."],["1177","5","<b>ובסי' אי' בש' הזהר</b>: סידור עם דא\"ח קעח, סע\"ב ואילך. ובאריכות בפירוש המלות לאדהאמ\"צ ה, סע\"ב ואילך."]]],[2002180369,"עולמות והיכלות שמעלימים ומסתירים על חיות אלקי וגם עולם הוא לשון העלם לכן נק' בש' טבעת ובשבת מאיר הגילוי. ובזה ניחא מ\"ש ויכל אלקים ביום השביעי שבשבת נתגלה ש' הוי', מ\"מ מלאכה אינו נק' שהי' מתחילה בששת ימי בראשית, אלא שהי' בהעלם ובשבת יצא לידי גילוי, מ\"מ הי' חסר בששת ימי בראשית ובשבת נתגלה, כמו השפעת הרב לתלמיד שמתחילה ג\"כ הי' השכל אצל התלמיד רק שהי' בהעלם ואח\"כ נתגלה מ\"מ קודם שהבין הי' חסר.\n<b>ולהבין</b> ענין זה בתוס' ביאור הנה כתי' יהללו את ש' הוי' כי הוא צוה ונבראו, נמצא שהבריאה הי' ע\"י ש' הוי', וכן כתי' בדבר הוי' שמים נעשו, כל אשר חפץ הוי' עשה, וכמו כן יש כמה פסוקים, וגם פי' הוי' הוא מהוה, ובאמת כתי' בראשית ברא אלקים, ל\"ב פעמים אלקים כתי' במע\"ב משמע שבריאת העולמות הי' ע\"י ש' אלקים. אך הענין הוא דשם כתי' ברא שמתלבש כח הפועל בנפעל שהוא בחי' ממכ\"ע שע\"ז נא' מה הנשמה ממלא את הגוף כך הקב\"ה ממלא את העולם, דזה שהנשמה מחי' את כל הגוף מ\"מ החיות הוא בהתחלקות בראש יותר מידים ובידים יותר מברגלים כך החיות אלקי הוא מחי' בהתחלקות, בראתיו יצרתיו אף עשיתיו, בברי' יותר מיצי' ביצי' יותר מבעשי'. וכ\"ז הוא ש' אלקים, אבל בש' הוי' כתי' ונבראו מאליו וממילא בלא התלבשות שזהו בחי' סוכ\"ע, שע\"ז אי' לא כמו שהנשמה ממלא<sup data-n=\"1178\">6</sup> את הגוף הקב\"ה ממלא את העולם, שהנשמה מתלבשת בגוף ומתפעלת ממקרי הגוף אבל אצל הקב\"ה כתי' אני הוי' לא שניתי שאצלו לא שייך שום שינוי, ואף שעיקר החיות הוא מסוכ\"ע מ\"מ אפי' הארה זו שמאיר בעולם הוא ג\"כ בלא התלבשות, ופי' סוכ\"ע אין פי' שסובב את העולם בלבד כי כתי' את השמים ואת הארץ אני מלא לית אתר פנוי מיני', מ\"מ נק' סוכ\"ע מפני שהוא בהעלם, שזהו בחי' מי שאמר והי' העולם, מי שאמר לשמן וידליק הוא יאמר לחומץ וידליק, וזהו ש' הוי' ששם יוכל להיות שינוי הטבע. ומעתה יובן שבששת ימי בראשית הי' ש' הוי' בהעלם בחי' סוכ\"ע אבל בשבת כתי' שבת להוי' גילוי ש' הוי', וכן בכל שי\"ב לא נזכר ש' הוי' רק ש' אלקים, אבל אחר שבת כתי' ביום עשות הוי' אלקים ארץ ושמים, וזהו שאמר ויכל אלקים ביום השביעי שבשבת נתגלה ש' הוי' שהו\"ע חותם שחותמו של הקב\"ה הוא אמת, וזהו דנהיר לכל עיזקא ועיזקא שהחותם שהוא ש' הוי' מאיר בטבעת שהוא ש' אלקים בגימט' הטבע.\n<b>וענין</b> הנס הו\"ע התנשאות כמו ושים אותו על נס שיהי' הגילוי למעלה מן הטבע שהוא ש' הוי', כי בכלל נסים שרשם למעלה מן הטבע, ואפי' נסים שבדרכי הטבע שרשם למעלה מן הטבע שהוא ש' הוי' רק שמלובשים בטבע, ולכן ד' צריכים להודות שהד' הם כנגד ד' אותיות של ש' הוי', ובנס שהוא מש' הוי' לכן צריכין להודות.",[["1178","6","<b>בחי' סוכ\"ע שע\"ז אי' לא כמו שהנשמה ממלא</b>: ראה עד\"ז לקמן סד\"ה צאינה וראינה."]]],[2002180370,"<b>ועפ\"ז</b> יובן מ\"ש בסי' האריז\"ל שמזמור לתודה הוא חו\"ב דיצי', דהנה חו\"ב הו\"ע אין ויש, בינה הוא יש כמ\"ש להנחיל אוהבי יש וחכ' הוא אין כמ\"ש והחכ' מאין תמצא. ולכאו' צ\"ל מהיכא אנו יודעים שחכ' הוא אין מפסוק והחכמה מאין תמצא, דלמא הוא נמצא מאין אבל היא בעצמה היא יש. אך מתיבת תמצא אנו לומדים זאת, שאם הי' כתיב נברא היינו אומרים באמת שהוא יש אבל כיון שנא' תמצא משמע שהוא ע\"ד מציאה כמו ראובן שמצא אבידה של שמעון שמוכרח לומר שהדבר שמצא ראובן הוא עצם הדבר שאבד שמעון שאל\"כ הרי אין חייב להחזיר לו ובאמת הרי אינו שלו כמו\"כ מ\"ש והחכ' מאין תמצא החכ' היא עצמה אין שאל\"כ הרי אין לומר תמצא. ונמצא שחו\"ב הם אין ויש, וזהו כמו בד\"ת, כמו שבד\"ת היש אינו משיג את השפעת האין, כך היש דבינה אף שבינה הוא השגה מ\"מ אינו משיג השפע שנמשך מאין דחכ', וכמו היש דד\"ת תמיד בטל להשפעת האין כך היש דבינה תמיד בטל להאין דחכ', והאין דחכ' משפיע תמיד בהיש דבינה, וזהו\"ע זיווג חיצוני' דחו\"ב שזיווגייהו תדירא תרין ריעין דלא מתפרשין לעלמא לצורך קיום וחיות העולמות, וזהו ד\"ת. ויש בחכ' ד\"ע שהוא עצם אור אבא שהאין דשם הוא כמו אין דכתר שהוא בעצם יש אמיתי אלא מרוב העלמו הוא נק' אין ומה שנמשך לבינה הוא רק הארה מעצם חכ', שבאין יש שני פי' א' שאינו מושג והב' הוא הארה, וכשאומרים אין שאינו מושג קאי על ד\"ת שהיש אינו משיג האין דחכ', וכשאומרים שהוא הארה קאי על ד\"ע שהאין שמשפיע בבינה אינו רק הארה מעצם אור אבא ושם כולא קמי' כלא חשיבי כיון שהאין המשפיע בבינה אינו רק הארה מכש\"כ העולמות שנמשכו ממנו בודאי כלא חשיבי. וזיווג פנימי' זה זיווגייהו לפרקים.\n<b>והנה</b> נס הו\"ע התנשאות לנשא טבע למעלה מן הטבע, דהיינו שתוכלל בינה בחכ', ע\"ד הבן בחכ' שהבינה תוכלל בחכ', וע\"ד שילוב אד' בהוי', והיינו שטבע נכללת בלמעלה מן הטבע שהוא ש' הוי' ומשם נמשך הנס שהוא למעלה מן הטבע, כמ\"ש ואמת הוי' לעולם, ובעולם יש שני פי' אחד לשון העלם והב' הוא ע\"ד אלקים חיים ומלך עולם, ואמת קאי על חכ' ואפ\"ל שקאי על ת\"ת שת\"ת נק' ג\"כ אמת. וע\"ז אמר ד' צריכין להודות שלבחי' זו דנס שהוא ד\"ע לא יוכל להשיג בשכל אלא צריך להודות, ע\"ד מודים חכמים לר\"מ, שאעפ\"י שהם אינם משיגים מ\"מ הם מודים. כן ענין ד\"ת יכול כל אדם להשיג, אבל ד\"ע שאינו יכול להשיג רק ע\"י הודאה יכולים להמשיך מבחי' שכולא קמי' כלא חשיב."],[2002180371,"<h3>עבדו את ה' בשמחה</h3>\n<b>בס\"ד. ל\"ג בעומר.</b>\n<b>עבדו</b> את הוי' בשמחה<sup data-n=\"1179\">1</sup> בואו לפניו ברננה דעו כי הוי' הוא אלקים, ואי' במגלה עמוקות שעבדו את הוי' כו' הו\"ע כהנים בעבודתם וכנגד זה תיקנו בתפילה פרשת קרבנות עד ב\"ש, ובואו לפניו ברננה הו\"ע לוים בדוכנם שהי' עבודתם בשירה וזמרה וכנגד זה בתפילה תיקנו פסוד\"ז, ודעו כי הוי' כו' קאי על ק\"ש שז\"ע פ' ראשון הוי' אחד.\n<b>ולהבין</b> זה צ\"ל תחילה פי' דפסוק ראשון דק\"ש, דהנה אנו אומרים שמע ישראל וכו', וצ\"ל למי אומר כאו\"א מישראל שישמע זאת, ומהו מדריגת ישראל. אך הענין הוא דהנה אנו אומרים נשמה שנתת בי טהורה היא אתה בראת אתה יצרת וכו' וצ\"ל הלא בתחילה הי' צ\"ל בראת יצרת ואח\"כ טהורה. והענין הוא דהנה ידוע שלא כל הנשמה ירדה להתלבש בגוף ונה\"ב כי הנשמה גדלה ממעלת ומדריגת המלאך, והנה מה מלאך ארז\"ל שבשליש עולם הוא עומד כש\"כ וקו\"ח הנשמה בודאי הגוף קטן מהכיל כולה, ע\"כ מוכרח לומר שמה שירדה הנשמה להתלבש בגוף ונה\"ב הוא רק הארה ומקצת מהנשמה אבל עצם הנשמה נשארה למעלה בבחי' מקיף. וזהו משארז\"ל אע\"ג דאיהו לא חזי מזלייהו חזי, פי' מזל הוא שרש ומקור הנשמה ושם היא בבחי' חזי שרואה ושומעת הכל. ואף שארז\"ל אין מזל לישראל, היינו מזלות דרקיע אינם שייכים לישראל, כי אם שמזל ישראל הוא מדריגה היותר הנעלה שנק' בש' אין ומשם הוא שרש הנשמה.\n<b>ובזה</b> יהי' ניחא מארז\"ל שנראה כסותרים זה את זה, דהנה כתי' תורה צוה לנו משה מורשה, וארז\"ל אל תקרא מורשה אלא מאורסה שהתורה נקראת בש' כלה והיא מאורסת לישראל שנקראים בש' חתן, משמע שישראל הם במדריגה הגבוה מאורייתא, ופעם ארז\"ל תלת קשרין מתקשרין דא בדא ישראל באורייתא ואורייתא בקוב\"ה, משמע שאורייתא גבוה מישראל שנקראים בש' כלה שהם מקבלים מהתורה שנק' בש' חתן. אך הענין דהנה מצד שרש הנשמה הם גבוהים הרבה מאורייתא, כי הנשמה שרשה גבוה מאד כמארז\"ל נשמתן של ישראל קדמה לכל דבר, ובתד\"א אי' שני דברים קדמו לעולם תורה וישראל ואיני יודע איזה מהם קדם אומר אני מחשבתן של ישראל קדם, ולכן נק' נש\"י בש' חתן שהם משפיעים וממשיכים המשכת אוא\"ס בתורה, והגם כי אורייתא מחכמה נפקת, אך הרי נש\"י נק' בשם בנים שכמו הבן נמשך מעצם מוח האב כמו\"כ נש\"י נמשכים מעצם חכ' עילאה, דהנה כתי' והחכמה מאין תמצא, ונת\"ל<sup data-n=\"1180\">2</sup> דכמו שהכתר נק' אין כמו\"כ יש בחכ' מדריגה הנק' אין, ונש\"י נמשכים מפנימי' החכמה שהוא האין דחכ' ולכן יש בכוחם",[["1179","1","<b>עבדו את ה' בשמחה</b>: הנחת א' מהשומעים מהמאמר הנדפס לעיל ע' שפג ואילך. נמצא בכת\"י 1185. וראה לעיל ע' תקסח הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר, ובהנסמן בהמ\"מ לשם."],["1180","2","<b>כתי' והחכמה מאין תמצא ונת\"ל</b>: לעיל בד\"ה מזמור לתודה הא'."]]],[2002180372,"דוקא להמשיך אוא\"ס בתורה. וזהו הפי' שמע ישראל שיתבונן בשרש ומקור הנשמה שהיא טהורה שהוא מדריגה גבוה מאד. ומחמת זה ההתבוננות יבוא לביטול דיחו\"ע, שזהו\"ע הוי' אחד.\n<b>אך</b> הנשמה נעשה נברא ובע\"ג, וכמאמר אתה בראת אתה יצרת וכו', ומחמת זה הם מקבלים מאורייתא שנש\"י נק' בש' כלה והתורה בש' חתן, ולכן אי אפשר לבוא להתבוננות וביטול דאחד. ועוד כי הנה אנו אומרים ואהבת כו' בכל לבבך בשני יצריך ולכאורה איך יבוא היצה\"ר לאהבת הוי'. אך הנה פי' יצר הוא מדות, שיצ\"ט הוא מדות דנה\"א ויצה\"ר הוא מדות דנה\"ב, והנה ידוע דלכל מדה יש שכל המוליד את המדה ולזה יש נו\"ן שערי בינה אשר ע\"י יכול להיות הולדת המדות מהמוחין, וכמו שיש שכל בנה\"א המוליד המדה כמו\"כ יש שכל בנה\"ב, וע\"י השכל יכול להבין גם הנה\"ב שצריך להיות אהבה לה', אך ההתבוננות דאחד לא יכול לקבל הנה\"ב. ולזאת מחמת הב' טעמים הנ\"ל נתקן לומר בשכמל\"ו שהו\"ע התבוננות דד\"ת, כי פי' מל' הוא רק הארה בעלמא כי מלך שמו נק' שהוא רק ש' והארה בעלמא וזהו מקור כל העולמות, אך ממל' כמו שהוא עוד לא הי' אפשר להיות בריאה, כי אם מבחי' כבוד מל' שהוא הארה דהארה, וגם מזה הבחי' ג\"כ לא הי' יכול להיות התהות כ\"א מבחי' שם כבוד מלכותו ומזה נמשך כללות העולמות לעולם ועד, ודרך כלל הג' בחי' דשם כבוד מל' הוא כנגד ג' עולמות בי\"ע, וזהו\"ע ד\"ת שהיא בריאה יש מאין, והגם שנת\"ל שהאין דד\"ת פירושו<sup data-n=\"1181\">3</sup> אין ע\"ש שאינו מושג, אך גם זה יובן שמכ\"ש הוא שהוא הארה בעלמא וידוע דזיו והארה הוא בטל לגבי עצם, ולכן כאשר יעמיק דעתו בזה איך שמקור המהוה כללות העולמות הוא אין, ואיך אפשר להיות הנברא אשר נתהוה ממנו מציאות היש הנראה לעינינו, עי\"ז יבוא הנה\"ב נפש השכלית שבו ג\"כ לביטול היש ויהיה לו אהבה לאלקות ולכה\"פ שלא יהי' מונע ומעכב ויסכים לביטול דנה\"א. ופי' בכל נפשך אפי' נוטל את נפשך והו\"ע מס\"נ דנפש האלקית, אבל<sup data-n=\"1182\">4</sup>* בכל נפשך היינו בכל כוחות הנפש אפי' כוחות דנה\"ב.\n<b>אך</b> הנה הנה\"א נתלבש בגוף ונה\"ב אשר הם מעלימים ומסתירים לגמרי, ובכדי שיבוא לאהבה ע\"ז ארז\"ל כל המאריך באחד שהו\"ע אריכות ההתבוננות דברכת ק\"ש ופסוד\"ז, ועי\"ז יכול לבוא לק\"ש. ואף שהתנאים ואמוראים לא היו מאריכים בתפילה וכש\"כ בפסוד\"ז מ\"מ היו באים לביטול דאחד, הענין הוא מפני ששרש נשמתם הי' מבחי' מוחין דגדלות והיו תמיד קשורים ודבוקים בא\"ס ב\"ה וכמאמר רשב\"י בחד קטירא אתקטרנא בי' אחידא בי' להיטא, ור' יהודה הנשיא הי' מעביר ידיו על גבי עיניו ודיו, ורב יהודה הי' מצלי מתלתין יומין לתלתין יומין שהי' תמיד בשוב דתורה, ובכדי לעורר את הרצוא הי' די לו פעם א' לשלשים יום, אבל אנו שנתגשמו ונתרחקנו מאלקות ובפרט נשמות דעקבתא דמשיחא לכן בכדי לבוא לידי",[["1181","3","<b>שנת\"ל שהאין דד\"ת פירושו</b>: לעיל בד\"ה מזמור לתודה הא' שם."],["1182","4","<b>אבל בכל נפשך</b>: כ\"ה בכת\"י המעתיק."]]],[2002180373,"איזה ביטול צ\"ל אריכות ההתבוננות. והמשל לזה כאשר לומדים הלכה עם תינוק ששכלו עדיין מועט ואינו יודע עניני העולם וע\"פ רוב כל הלכות ענינם בטיב העולם, ולזה צריך שיסביר לו גדול בריבוי הסבר עד שיבין, אבל גדול כאשר לומד ההלכה לא צריך לריבוי הסבר. ועד\"ז יובן בתנאים ואמוראים שהיו תמיד קשורים ודבוקים בו ית' הי' די להם מעט התבוננות וכשהיו מתבוננים מעט היו באים תיכף להתקשרות עצומה, אבל אנו צריכין לריבוי התבוננות. ולכן תיקנו פסוד\"ז שהו\"ע הסיפור איך שהמלאכים משבחים ומזמרים, וברכת ק\"ש הוא בכדי לעורר נה\"ב ששרשו משמרי האופנים וע\"י שמספרים לו איך ששרשו עומד תמיד בביטול גדול לאלקות עי\"ז יתעורר הוא ג\"כ לבוא לאהבה את ה'.\n<b>והנה</b> פסוד\"ז הוא כנגד עבודת הלוים שהי' בשירה וזמרה, כי הנה כתי' ועבד הלוי הוא ואי' בזהר שהוא קאי על עלדאת\"כ, ועבודתם הי' להעלות עלדאת\"ג לעלדאת\"כ דהיינו שיהי' ביטול לאלקות בעלדאת\"ג כמו בעלדאת\"כ, והוא ע\"י שירה וזמרה שלהם, כי הנה אנו רואים דכאשר יתעורר אדם באיזה התפעלות בלבבו מ\"מ אינו נראה ונגלה עדיין ההתפעלות, וכאשר ישורר איזה ניגון עי\"ז יהי' נראה ונגלה ההתפעלות. והענין דהנה ארז\"ל כל בעלי השיר יוצאין בשיר, ופי' בעלי השיר היינו מלאכים ונשמות, כי גם מלאכים יש להם גופים רק שגוף האדם הוא מד' יסודות אבל גוף המלאך הוא מב' יסודות, ומאיזה מהם מהדקות שבהם כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט, ובכדי לצאת מגדר הגבלה דכלי הגוף הוא ע\"י שירה וזמרה. וכן נשמות יושבין בג\"ע ומשיגין השגות והשגה הו\"ע הגבלה, ובכדי לצאת מהשגה הזו למדריגה היותר נעלה הוא ע\"י שירה וזמרה. ובדרך כלל הוא העמוד שבין ג\"ע התחתון לג\"ע העליון, ובד\"פ יש הרבה מדריגות בגעה\"ת והרבה מדריגות בגעה\"ע. ועפי\"ז יובן עבודת הלוים שהי' בכדי שיבואו להתפעלות, לא התפעלות שיהי' הולדת המדות כ\"א התפעלות שיבואו לרעו\"ד והוא ע\"י שירה וזמרה. אך הגם שעיקר עבודת הלוים הי' ברצוא ותשוקה ליכלל בעלדאת\"כ מ\"מ הי' להם גם מדריגת שוב, כי הנה כתי' והחיות רצוא ושוב כמראה הבזק ופרש\"י כמו שלהבת היוצא מהכבשן וחוזר כמו\"כ החיות מוציאין ראשיהן ממעל לרקיע ונרתעים לאחוריהם מפחד השכינה, כמו\"כ יובן גם בלוים שהי' גם להם בחי' שוב אלא שעיקר עבודתם הי' ברצוא, כי כללות העבודה א\"א להיות בלתי שוב כמ\"ש בס\"י אם רץ לבך שוב לאחד. וענין השוב של הלוים הוא קבלת עול יראה. וכמו\"כ בכללות ישראל צ\"ל העבודה ברצוא ושוב, רצוא ותשוקה ליכלל וליבטל אליו ית', ושוב בתומ\"צ.\n<b>והנה</b> בעבודת הלוים הי' עוד עבודה שהיו נושאים את המשכן שנק' משכן העדות והארון עם לוחות העדות, והוא בכללות החיבור דש' הוי' כי המשכן הוא יחוד ו\"ה והלוחות הם עשרת הדברות והוא היו\"ד של ש' הוי' והארון הוא אור נו\"ן והוא ה' ראשונה של ש' הוי' ולכן הלוחות והארון הוא יחוד י\"ה. וכמו\"כ בתפלה שתיקנו כנגד עבודת הלוים יש בו ג\"כ יחוד דש' הוי', כי הוי' אלקינו הוא יחוד חו\"ב שהוא יחוד י\"ה, ואח\"כ כתי' ואהבת את הוי' אלקיך הוא יחוד ו\"ה. אך בכדי שיבוא"],[2002180374,"לזה הוא ע\"י הקרבנות והקדמת פסוד\"ז תחילה, כי יש עוד פי' בפסוד\"ז שהוא מלשון לזמר עריצים כמו עד\"מ בכרם מזמרים הקוצים והחוחים המונעים ומעכבים מלהיות גדילת דשאים הטובים, כמו\"כ בעבודה הוא להסיר כל המונעים והמעכבים מלבוא לאהבת ה', והוא ע\"י שבחים דלמטה וכמ\"ש רוממות אל בגרונם ועי\"ז נעשה חרב פיפיות בידם כו', ודרך כלל הוא לצאת מחיצוני' הלב לפנימי' הלב שהוא ע\"י פסוקי דזמרה, ועי\"ז מתרומם הנפש שיוכל לבוא לפנימי' הלב.\n<b>וזהו</b> בואו לפניו ברננה שע\"י הרננה דפסוד\"ז עי\"ז יבוא אח\"כ בק\"ש בביטול אמיתי לפניו ית' שהו\"ע פנימי' הלב כמ\"ש נר הוי' נשמת אדם דכמו שטבע הנר לעלות למעלה כמו\"כ יהי' תמיד בתשוקה וצמאון ליכלל בו ית', ועי\"ז יאיר מלמעלה ג\"כ פנימי' כמ\"ש יאר הוי' פניו אליך. אך בכדי לבוא לפסוד\"ז ע\"ז תיקנו פ' הקרבנות שהוא כנגד עבודת הכהנים, כי כמו שהקרבת הקרבנות הוא ע\"י כהנים כמו\"כ העלאת הנרות דנשמות ישראל שנקראים בשם נר כמ\"ש נר הוי' נשמת אדם הוא ע\"י אהרן כה\"ר<sup data-n=\"1183\">5</sup> כמ\"ש בהעלותך את הנרות. ובעבודה הוא דכמו שבהקרבנות הי' אש יורד מלמעלה כמו\"כ בעבודה הוא אתעדל\"ע המעורר אתעדל\"ת בכדי שיוכל לבוא לפסוקי דזמרה.\n<b>וזהו</b> פי' הפסוק עבדו את הוי' בשמחה הוא התעוררות מלמעלה שהיא עבודת הכהנים וזהו\"ע פ' הקרבנות, ואח\"כ איזהו מקומן זהו פ' הקרבנות כמו שנכתב בתושבע\"פ, ואח\"כ הודו הוא ג\"כ כנגד הקרבנות כי המזמור הזה היו אומרים קצת פסוקים בתמיד של שחר מתחילת הודו עד ובנביאי אל תרעו כו' ובתמיד של בין הערביים אומרים המותר עד רוממו, וזהו בכלל עבדו את הוי' וכו'. ואח\"כ בואו לפניו ברננה זהו פסוד\"ז שהיא הכנה שיבוא לפנימי' הלב, ועי\"ז יבוא אח\"כ למדריגת דעו כי הוי' הוא אלקים. והענין כי הוי' אלקינו הוא בינה ומשה דוקא זכה לבינה, אבל אלקים הוא מל' ד\"ת ונת\"ל שגם ד\"ת הוא אמת<sup data-n=\"1184\">6</sup>. ובעבודה הוא לחבר ד\"ע בד\"ת שיהי' מושג בד\"ת כמו בד\"ע. וזהו דעו כי הוי' הוא אלקים דהיינו לחבר ב' השמות הוי' ואלקי' שהם שרש ומקור דב' דיעות ד\"ע וד\"ת שיהי' הביטול בד\"ת כמו בד\"ע שכולא קמי' כלא חשיב.",[["1183","5","<b>כה\"ר</b>: כהנא רבא."],["1184","6","<b>ונת\"ל שגם ד\"ת הוא אמת</b>: לעיל ד\"ה מזמור לתודה הא' שם."]]],[2002180375,"<h3>מזמור לתודה</h3>\n<b></b><b>בס\"ד. פ' בהר תרל\"ט, ליובאוויץ.</b>\n<b>מזמור</b> לתודה<sup data-n=\"1185\">1</sup> הריעו להוי' כל הארץ. הנה הריעו להוי' כל הארץ ר\"ת הלכה וצ\"ל מה שייך תודה להלכה. אך הנה אי' במד\"ר לא ניתנו דברי תורה למשה חתוכים חתוכים אלא מ\"ט פנים טמא ומ\"ט פנים טהור כמ\"ש מזוקק שבעתים ז' פעמים ז' הרי מ\"ט, ועל מה חל לומר מ\"ט פנים טמא על דבר שיש מחלוקת, כי על דבר שהוא מבורר בתורה שאסור כמו חזיר שאסור ע\"ז לא שייך לומר מ\"ט פנים, אלא דבר שהוא מק\"נ שע\"ז יש מחלוקת אם יכולים לברר אותו אם לאו, דעת האוסרין סוברים שאין יכולים לברר, ודעת המתירין סוברין שיכולים לברר, ע\"ז אומר מ\"ט פנים טמא. והלכה כדעת המכריע שהמכריע נותן מקום לשניהם אפי' למדה\"ד רק שההילוך בעולם צ\"ל כך, שזהו\"ע מדת הת\"ת מדתו של יעקב שהוא אמת. וזהו מ\"ש והנורא אל עליון שהגדול הגבור כתי' בלא וא\"ו והנורא כתי' בוא\"ו שזה מורה על שם שנמשך מאל עליון שלמעלה מסדר השתל'. ומהו\"ע של וא\"ו הוא יו\"ד בראשו וביו\"ד גופא יש עצם היו\"ד וקוצו של יו\"ד, עצם היו\"ד הוא חכ' וקוצו של יו\"ד מורה על כתר, וביארנו פי' והחכ' מאין תמצא<sup data-n=\"1186\">2</sup> שאין דחכ' נמשך מאין דכתר בדרך מציאה, וזה נמשך בוא\"ו שהוא מדת הת\"ת ועי\"ז ת\"ת מחבר חו\"ג. ועוד י\"ל ע\"ד מ\"ש המשל ופחד עמו עושה שלום במרומיו מיכאל שר של מים גבריאל שר של אש ואין מכבין זה את זה, והיינו שמאיר שם גילוי שלמעלה משניהם נעשים שניהם בטלים לגמרי, כך במדת ת\"ת ששורה אוא\"ס שלמעלה מחו\"ג נעשים שניהם בטלים. וזהו מ\"ש בדוד והוי' עמו ואי' בגמ' הלכה כמותו בכל מקום, פי' והוי' עמו קאי על הארת הקו שמאיר בכתר וחכ' ואח\"כ נמשך במל', ודוד שהי' מרכבה למדת המל' השיג הארת הקו שמאיר בכתר וחכ' לכן הלכה כמותו בכל מקום. וע\"י מה בא דוד לזה ע\"י שהי' תמיד בביטול ושפלות כמ\"ש כי עני ואביון אני, והייתי שפל בעיני, וע\"י שהי' בביטול ושפלות עי\"ז השיג הארת הקו שמאיר בכתר וחכ'. וזהו מ\"ש מרום וקדוש אשכון את דכא ושפל רוח, מרום וקדוש קאי על הארת הקו שמאיר בכתר וחכ', וע\"י חכ' נמשך באצי', שהארת הקו אינו נמשך אלא בכתר וחכ' ומה שנמשך באצי' זהו ע\"י חכ', והיכן אשכון את דכא ושפל רוח דוקא במקום ביטול ושפלות, ודוד שהי' בביטול ושפלות השיג מדריגת והוי' עמו שיהי' הלכה כמותו בכל מקום.\n<b>ובזה</b> יובן מה שאי' בגמרא אלו ואלו דברי אלקים חיים והלכה כדברי ב\"ה, ופריך בגמרא כיון דאלו ואלו דא\"ח הי' צריך להיות הלכה כדברי ב\"ש שמחדדי",[["1185","1","<b>מזמור לתודה</b>: הנחת א' מהשומעים מהמאמר ד\"ה ומעתה יובן ענין הריעו לה' הנדפס לעיל ע' שעד ואילך. והוא המשך לד\"ה מזמור לתודה הא' הנדפס לעיל. — הנחה זו נמצא בכת\"י 1185. וראה לעיל ע' תקעב הנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר, ובהנסמן בהמ\"מ לשם."],["1186","2","<b>וביארנו פי' והחכ' מאין תמצא</b>: לעיל בד\"ה מזמור לתודה הא'."]]],[2002180376,"טפי, ומתרצין מפני שנוחין ועלובין זה לזה. ולכאורה מה שייך הטעם שנוחין ועלובין להלכה, הרי הלכה תלוי בחידודי טפי, אלא מהו הפי' של עלובים הנה עלובים הו\"ע סבלנים שהו\"ע ביטול ושפלות, וע\"י שהיו בביטול ושפלות השיגו אמת של ההלכה לכן הלכה כדברי ב\"ה. אך צ\"ל מה שאומר בגמ' אלו ואלו דברי אלקים חיים משמע אפי' הדיעה שאינו כהלכה ג\"כ אמת, וכשאומר הלכה כב\"ה משמע זהו דוקא אמת אבל דעת החולק אינו אמת, ובאמת נאמר אלו ואלו דברי אלקים חיים משמע שאפי' דעת החולק נמי אמת, וכיצד הם השני דברים. אך הענין הוא ששרש ההלכה היא מהארת פנים שע\"ז כתי' חכ' אדם תאיר פניו, שאנו רואים שכשאדם מסביר השכלה מתמלא עונג, והיכן מאיר העונג בגילוי בפנים דוקא ע\"ד שארז\"ל צהבו פניו של ר' אבוה כי מצא תוספתא חדתא, כך למעלה שרש הלכה הוא מתיקון ואמת שפנוי משערות היינו שמאיר הגילוי בלא צמצומים. וזהו שרש הלכה שהלכה כמותו, והלכה שאי' בגמ' אלו ואלו דברי אלקים חיים זה קאי על אלקי' דבינה שיש מ\"ט שערי בינה, וביארנו שלידת והתגלות המדות הוא ממ\"ט שע\"ב<sup data-n=\"1187\">3</sup>, כך המ\"ט פנים טמא שרשם הוא ממ\"ט שע\"ב, כי כל דעה אפי' זו שאינה כהלכה יש לה שער ומבוא במ\"ט שערי בינה. והנה יש מדריגה גבוה יותר והוא י\"ג מדות שהתורה נדרשת בהם שהם כנגד י\"ג תיקוני דיקנא שהם ג\"כ אמת רק שהוא ע\"י צמצומים דשערות ושם יש לכל הלכה שרש. אמנם הלכה האמיתית שרשה מתיקון ואמת שפנוי משערות שמאיר בלא צמצומים ומשם יוכל לימשך שיהי' הליכות עולם לו ואמת הוי' לעולם.\n<b>ועתה</b> ניחא המזמור לתודה כו' שתודה והלכה הם שייכים זה לזה, שתודה הו\"ע חכ', שבהודאה יכולים להשיג עצם החכ' ששם מושג ד\"ע שכולא קמי' כלא חשיבי, והלכה ג\"כ הו\"ע חכ' שנמשכין ממוחין סתימאן ואפי' ההלכות שאין הלכה כמותן.\n<b>ועתה</b> יובן מה שאי' שתודה אינה בטילה לע\"ל והלכות ג\"כ אינן בטלין לע\"ל, כי הנה על לע\"ל כתי' ואמר ביום ההוא הנה אלקינו זה, הוא הוא סתום עלמין סתימין דלא אתגליין, וזה הו\"ע גילוי שעלמין סתימין דלא אתגליין יתגלו לע\"ל, אבל הלכות שלקוחין מסתימין דכל סתימין לע\"ל יהי' שייך כמו עכשיו, לא כמו נבואה שאי' עתידה נבואה להתבטל, ואין הפי' שתיבטל לגמרי אלא שיהי' ג\"כ לע\"ל, שנבואה הוא מנו\"ה שבזה\"ז הוא גילוי, אבל לע\"ל שיתגלה גילוי גבוה אחר לא יהי' נחשב זה כלום ע\"ד שרגא בטיהרא מאי אהני, שישנה רק שהיא אינה נחשבת, אבל הלכות שלקוחין מסתימין דכל סתימין אינם בטלין היינו שלע\"ל יהי' שייך כמו בזה\"ז. ותודה ג\"כ ע\"י הודאה משיג אוא\"ס עצומ\"ה ג\"כ אינן בטלין לע\"ל, דלע\"ל יהי' שייך כמו בזה\"ז.",[["1187","3","<b>וביארנו שלידת והתגלות המדות הוא ממ\"ט שע\"ב</b>: לעיל בד\"ה מזמור לתודה הא' שם."]]],[2002180377,"<b>ועוד</b> יש לעשות הפרש בין תודה והלכות לשארי דברים, דהנה אי' בגמ' כל המנחות באות מצה חוץ מתודה ושתי הלחם שבאות חמץ, וסתם מנחה היא מנחת מחבת ומרחשת, ובכלל כל הקרבנות נק' בש' מנחה ע\"ד מ\"ש וישע הוי' אל הבל ואל מנחתו, ומה הביא כתי' והבל הביא גם הוא מבכורות צאנו ומחלביהן משמע שכל הקרבנות נק' בש' מנחה, כי מהו\"ע קרבן הנה קרבן הוא העלאת מ\"ן ומנחה הוא אותיות מ\"נ ח' ה', מ\"ן מורה על העלאת מ\"ן, ח' שעולה עד מזל השמיני ונוצר, ה' שמשם נמשך בה' בהבראם בה' בראם שהוא מל'. וכן יובן ממה שכתי' אצל יעקב מנחה היא שלוחה לעשיו אחי, ומה הביא עזים מאתים ותישים עשרים שהו\"ע קרבנות דתהו, הואיל שידע יעקב ענין דתהו ורצה לירש אורות דתהו לכן הביא קרבנות דעולם התוהו, ובאמת לפי חלקו בירר לפי שעה כי בזה\"ז לא יוכל להתברר כלל עולם התהו, רק עיקר בירור דתהו יהי' לע\"ל, שע\"י קרבנות דתיקון שבזה\"ז יהי' הבירור לע\"ל, כמ\"ש מזמור לתודה הריעו להוי' כל הארץ כדי שיהי' הבירור של כל הארץ יהי' דוקא לע\"ל כמ\"ש אז אהפוך אל עמים שפה ברורה לקרוא כולם בש' הוי' שעיקר הבירור יהי' לע\"ל, רק לפי שעה בירר יעקב חלקו כמ\"ש וישקהו נקוד על וישקהו מלמד שנשקו בכל לבו שבירר אותו לפי שעה, וקרבנות שלנו שאי' בתורה הם דתיקון מפני שעכשיו א\"א לברר עוד עולם דתהו. ונמצא שכל הקרבנות נק' בכלל בש' מנחה, ובפרט מנחה קאי על מחבת ומרחשת.\n<b>וזהו\"ע</b> כל המנחות באות מצה חוץ מתודה ושתי הלחם שבאות חמץ, שבתודה הי' עשר חלות חמץ ושתי הלחם הי' כולו חמץ, ומהו\"ע חמץ ומצה, הנה חמץ ומצה הם אותיות שוות רק ההפרש ביניהם בין ח' וה', ומהו ענין של ה', בה' יש פתח קטן בין גג העליונה לרגל השמאל שזה מורה על פיה פתחה בחכמה שהו\"ע ביטול וזהו\"ע מצה, אבל חמץ הו\"ע הגבהה והתנשאות שמשם נלקח היצה\"ר כמ\"ש מכף מעול וחומץ, ושרשו של יצה\"ר הוא מקו השמאל שבחי\"ת מנה\"י ובנה\"י ג\"כ מקו השמאל דנצח<sup data-n=\"1188\">4</sup>, והגם שכתי' ויגע בכף ירך יעקב מ\"מ תיקן אותו שמואל הנביא כמ\"ש וגם נצח ישראל לא ישקר ולא ינחם אלא שרשו מהוד, ולכן יש בחי\"ת פתח רחב למטה שהוא מורה על לפתח חטאת רובץ כדאמר רבי קרא מסייעו, ולפיכך לא נמצא בשבטים אותיות ח\"ט. וע\"ז קאמר שכל הקרבנות באות מצה, אבל לא חמץ שאין יכולים לברר את החמץ כמ\"ש כי כל שאור וכל דבש לא תקטירו ממנו אשה להוי', אבל תודה ושתי הלחם באות חמץ שהם יכולים לברר אפי' היש דחמץ, משום דתודה הו\"ע חכמה ושתי הלחם הוא ענין תורה שבכתב ותושבע\"פ ואורייתא מחכמה נפקת ובחכמה אתברירו שיכולים לברר אפי' חמץ. וכל זה הוא דוקא באכילת כהנים, אבל אכילת המזבח אינו יכול לברר חמץ.",[["1188","4","<b>ובנה\"י ג\"כ מקו השמאל דנצח</b>: ר\"ל מקו השמאל דנצח שהוא הוד. (או אוצ\"ל: מקו השמאל הוד)."]]],[2002180378,"<b>ולהבין</b> ענין מעלת אכילת כהנים, י\"ל ענין נדרים תחילה, הנה בזמן הזה לא שייך נדרים כי בזה\"ז צ\"ל בלי נדר, אבל כשהי' נדרים צ\"ל מהו ענינו. כי ענין נדרים הוא כשאדם רואה שאינו יכול לעשות הדבר, ואדרבא מתירא שלא יוריד ויגשם אותו יותר, מה הוא עושה מדחה את הדבר ההוא ממנו, אבל חכם מתיר את הנדר כי בחכמה אתברירו ויכול לברר את הדבר שדחה ממנו. ובכלל הו\"ע אתכפי' ואתהפכא, נדר הו\"ע אתכפי', והחכם שמתיר הנדר הוא ענין אתהפכא חשוכא לנהורא. ועוד יש להבין זאת ממה שאי' בגמ' ע\"ה אסור לאכול בשר, והיינו ע\"ה שלפנים שהיו בורים הם אסורים לאכול בשר, והיינו מפני כי עצם הבשר ותאות הבשר יכול עוד יותר להורידו ולגשמו, אבל אצל תלמידי חכמים כתי' עד דלא אכילנא בישרא דתורא לא צלילנא דעתאי והרי הוא מוסיף עוד צלילות הדעת, והיינו מפני כי שרש בעלי חיים הוא משרש גבוה שלמעלה ממדריגת מדבר רק שנפלו בשבירת הכלים, וע\"י שאוכל לשם שמים ע\"ד אוכל לשובע נפשו הוא עוד מעלה אותו וגם הוא מוסיף עוד צלילות הדעת.\n<b>ועוד</b> יש להבין זה ממה שאי' בגמ' הקנאה והתאוה והכבוד<sup data-n=\"1189\">5</sup> מוציאין את האדם מן העולם, וחשיב כבוד מדברים שמוציאין את האדם מן העולם, ומצינו שכתי' ועשית בגדי קודש לאהרן אחיך לכבוד ולתפארת, והכא חשיב כבוד מדברים שמוציאין את האדם מן העולם. אך הענין הוא מפני שאהרן הוא אותיות נראה שהוא ראי' החכמה, וגם אהרן הוא ענין מ\"ה כמ\"ש ונחנו מה שאמר משה זה על שניהם על אהרן ג\"כ, וגם מצינו באהרן גופא שכתי' אצלו ואהרן מה הוא כי כו', ומפני שאהרן הו\"ע מ\"ה ומ\"ה הו\"ע חכ' ובחכמה אתברירו לכן יכול לברר יש דכבוד כמ\"ש כבוד חכמים ינחלו. וע\"ד זה נוכל להבין מעלת אכילת הכהנים מפני שכהן הוא מקו הימין וחח\"ן הוא מימין, כ\"ג מחכמה וסגן מחסד וכהן הדיוט מנצח, וכיון ששרשם מחכמה ובחכמה אתברירו לכן יוכלו לברר אפי' חמץ שהו\"ע יצה\"ר. ועוד יש להבין זאת ממה שאי' בגמרא ואם האכל יאכל וארז\"ל בשתי אכילות הכתוב מדבר אחת אכילת אדם ואחת אכילת מזבח, ומהו\"ע אכילה, אכילה הוא ענין שמ\"ה מברר ב\"ן, ואכילת מזבח נק' בזהר ארי' דאכיל קורבנין שזה ענין מ\"ה מברר ב\"ן, אבל כל זה דוקא אשה ריח ניחוח ג' עולמות בי\"ע, אבל אכילת כהנים שכהנים אוכלים ובעלים מתכפרים נקראים בש' אכילת אדם משום שעל ידי אכילתם יוכלו לבוא למדריגת אדם דכליל כולא, לכן יוכלו לברר אפי' חמץ. אבל על המזבח כתי' כל שאור וכל דבש לא תקטירו ממנו אשה להוי' לפי שאינו יכול לברר חמץ. וע\"ד זה הוא ענין חנוכה שנר חנוכה משמאל שפי' אפי' גבורה שהוא מקו השמאל יתעלה, והיינו מפני שמצאו פך של שמן חתום בחותמו של כהן גדול ומפני מעלת כהן גדול יוכלו להעלות אפי' גבורה שהוא מקו השמאל. ונמצא מבואר שמזמור לתודה הריעו להוי' כל הארץ שתודה והלכה שייכים זה לזה ששניהם הם ענין חכמה.",[["1189","5","<b>שאי' בגמ' הקנאה והתאוה והכבוד</b>: לעיל בהמאמר ע' שעח הובא זה מאבות פ\"ד משנה כ\"א."]]],[2002180379,"<b>עבדו</b> את הוי' בשמחה הו\"ע בינה, כמ\"ש אם הבנים שמחה, וכמו שאנו רואים כשאדם משיג שכל כשהוא אצלו באורך ורוחב אזי יש לו שמחה, אבל בחכמה עדיין לא בא לידי שמחה. ובכלל זהו ההפרש בין מוחין דאבא למוחין דאימא, שבת נקרא מוחין דאבא שכתי' וקראת לשבת עונג, ועונג עדיין לא בא לידי שמחה, אבל יום טוב שנקרא מוחין דאימא כתי' מועדים לשמחה. וכמו כן בעבודה צ\"ל בשמחה כמ\"ש תחת אשר לא עבדת את הוי' אלקיך בשמחה, כי עבודה בלא שמחה לא נקרא עבודה, ומהו ענין של השמחה הוא שיהי' כל אדם שש ושמח מעבודתו ולא יבטל את עבודתו אלא שיהי' שש ושמח מזה גופא שעובד את הוי' נמצא ששמחה הוא ענין בינה.\n<b>בואו</b> לפניו ברננה הוא ג\"כ שמחה, רק שמחה שלאחר מרירות, או ניגון שכלול משמחה ומרירות, ובכלל הוא ההפרש בין תמיד של שחר ובין תמיד של בין הערבים, תמיד של שחר הו\"ע שמחה בצפרא ותמיד של בין הערבים הוא רננא ברמשא, והיינו מפני שענין הקרבת קרבן תמיד של בין הערביים הוא העלאת מ\"ן לברר הבירורים, ומקודם שנתברר הי' בריחוק שהוא מרירות, ואחר שנתעלה הוא שמחה שאחר המרירות לכן נקרא בש' רננה.\n<b>דעו</b> כי הוי' הוא אלקים הוא ענין דעת, כי מזמור לתודה הריעו הוא ענין חכמה, ועבדו את הוי' בשמחה הוא ענין בינה, ומהו ענין חו\"ב הוא כשאדם לומד מסכת או שומע דבר הלכה מרבו ומקבלה נקרא חכם, אף שזה מסכתא ערוכה או דבר הלכה ערוכה מ\"מ נקרא חכם, ובינה הו\"ע להבין דבר מתוך דבר, ונמצא שבבינה יש יתרון מבחכמה. וכמו שארז\"ל ואילו נבונים אפי' בדרא דמשה לא אשתכח שאמר הבו לכם אנשים חכמים ונבונים וידועים והדר קאמר ואקח מכם אנשים חכמים וידועים ואלו נבונים לא אשתכח. והנה בדעת יש ג' פירושים, רש\"י פי' דעת שנותן טעם לדבריו ע\"ד טעמו ונמוקו עמו, שע\"י שמשיג עומק החכמה ע\"י זה יכול ליתן טעם לדבריו. ורבינו יונה פי' דעת ע\"ד שאי' ולא במרכבה ביחיד אלא א\"כ הי' חכם ומבין מדעתו שפירושו די לחכימא ברמיזא שמפני שזה סוד נפלא לכן צריכין דוקא ברמיזא. ובמד\"ר פי' דעת הנהגת המדות שאי' שם כל תלמיד חכם שאין בו דעת נבילה טובה ממנו, לכן אי' במד\"ר על פסוק כלי יקר שפתי דעת זה משה שנאמר ויקרא הוי' אל משה הגם שהי' מקורב לא הלך מעצמו אלא א\"כ קרא אותו והיינו מפני שהי' לו דעת, וזהו הג' פירושים. ובכלל הג' פירושים הם ענין אחד, שבדיעה יש ב' בחי' כמ\"ש אל דיעות הוי' והו\"ע ד\"ע ודעת תחתון, ד\"ע הוא ענין התחברות חו\"ב והיינו מפני שד\"ע גבוה מחו\"ב לכן הוא מחברם, וזהו פירוש רש\"י ורבינו יונה רק רש\"י חושב חכמה כדאי' נמוקו עמו שמשיג עומק החכמה, ורבינו יונה חושב בינה שמבין דבר מתוך דבר ע\"ד די לחכימא ברמיזא. ודעת תחתון נק' דעת שבין כתפין שמחבר מוחין עם מדות, וזהו עיקר עבודה שיומשך מוחין למדות, וזהו פי' המד\"ר דאמר כל תלמיד חכם שאין בו דעת נבילה טובה ממנו, והיינו מאחר שאינו ממשיך מוחין למדות מה הפעולה מהמוחין, דעת קנית מה"],[2002180380,"חסרת דעת חסרת מה קנית, וזהו\"ע דעת עליון ודעת תחתון. ודעו כי הוי' הוא האלקים הוא התחברות ד\"ע ודעת תחתון. וע\"י מה יבוא לזה הוא ע\"י מזמור לתודה שהו\"ע חכמה ועבדו את הוי' בשמחה שהו\"ע בינה, ועי\"ז יבוא לדעו כי הוי' שהוא מחבר ד\"ע ודעת תחתון."],[2002180381,"<h3>מי זאת הנשקפה</h3>\n<b>בס\"ד.</b>\n<b>מי</b> זאת הנשקפה<sup data-n=\"1190\">1</sup> כמו שחר יפה כלבנה ברה כחמה איומה כנדגלות, הנה איומה כנדגלות הו\"ע הדגלים וכמו בדגלים הי' קודם לכן ההקדמה שאו את ראש בנ\"י לגולגלותם ואח\"כ הי' עשיית הדגלים כך כדי שיהי' איומה כנדגלות צ\"ל תחילה נשקפה כמו שחר יפה כלבנה ברה כחמה ואח\"כ יוכל להיות איומה כנדגלות. ולהבין כ\"ז צ\"ל מה שאי' במד\"ר ע\"פ כי תבואו אל הארץ אשר אני נותן לכם וקצרתם את קצירה והבאתם את עומר ראשית כו', אמר ר' ברכי' כשנתתי לכם את המן נתתי עומר לכל או\"א הדא הוא דכתיב עומר לגלגולת ועכשיו שאני מבקש מכם איני מבקש אלא עומר אחד מכולכם, ולא עוד אלא של שעורים, וצ\"ל מהו עומר לכאו\"א ומהו\"ע עומר אחד מכולכם, ומהו ולא עוד אלא של שעורים.\n<b>אך</b> להבין זה צ\"ל תחילה ענין המן דהנה כתי' אצל המן, אכלוהו היום כי שבת היום להוי' היום לא תמצאוהו בשדה, וצ\"ל מפני מה לא ירד המן בשבת הלא כל ההשפעות אינן נעצרים בשבת, וכל ההשפעות הרי הם מלמעלה שהרי אפי' צמיחה אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל, ומ\"מ אינו נעצר בשבת, והמן הוא מדריגה גבוה כ\"ש שלא הי' צריך ליעצר, וגם מהו אכלוהו היום הלא כל הימים אכלו אותו. אך להבין זה צ\"ל כללות ענין המן דהנה כתי' הנני ממטיר לכם לחם מן השמים ויצא העם ולקטו דבר יום ביומו למען אנסנו הילך בתורתי אם לא, משמע שהמן הי' הקדמה לתורה וצ\"ל מה שייך מן לתורה, וגם מהו הנסיון, ועוד מהו הלשון של הילך בתורתי הל\"ל אם יקיימו תורתי.\n<b>אך</b> הענין הוא דהנה ידוע דעיקר קיום העולם הוא ע\"י תורה כמ\"ש אם לא בריתי יומם ולילה חוקות ארץ ושמים לא שמתי, וכן אי' במד\"ר תנאי התנה הקב\"ה עם",[["1190","1","<b>מי זאת הנשקפה</b>: הנחת א' מהשומעים מהמאמר הנדפס לעיל ע' שפט ואילך. הנחה זו נמצאת בכת\"י 1185. וראה לעיל ע' תקעז הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה, וכאן הוא באריכות יותר וכו'.\nהמ\"מ למאמר זה כבר נסמנו לעיל בהמאמר, ולא נכפלו כאן עוה\"פ."]]],[2002180382,"מע\"ב אם יקיימו ישראל תורתי מוטב ואם לאו אחזיר את העולם לתוהו, וכן אי' בזהר באורייתא אתקיים עלמא, וכן הוא בכמה מדרשים וזהר כמו שאי' עשרה עשרה הכף בשקל הקודש שעשרת הדברות מכוון כנגד עשרה מאמרות שקיום עשרה מאמרות הם עשרת הדברות, וכן אי' אלה תולדות השמים והארץ בהבראם אלה בזכות מי הם עומדים ובזכות מי הם נבראו בזכות ואלה שמות בנ\"י, ואלה בזכות מי הם נבראו ובזכות מי הם עומדים בזכות אלה העדות והחוקים, נמצא שבזכות התורה העולם קיים. וכן אי' אנכי עשיתי ארץ ואדם עליה בראתי, בראתי בגימט' תרי\"ג, וזה שעשיתי ארץ ואדם עליה הוא בשביל תרי\"ג מצות, וצ\"ל מה שייך תורה לקיום העולם הלא העולם נברא קודם מ\"ת.\n<b>אך</b> הענין הוא הנה כתי' אתה הוא הוי' לבדך אתה עשית את השמים, אתה הוא הוי' לבדך כתי' אתה מלא ה' כמו שצריך להיות אתה, ואתה עשית את השמים כתי' את חסר ה', והיינו כי אתה הוי' לבדך זהו ע\"ד מ\"ש עד שלא נברא העולם הי' הוא ושמו בלבד, שמו קאי על אצי' כמ\"ש כל הנקרא בשמי ולכבודי בראתיו יצרתיו אף עשיתיו, בראתיו יצרתיו עשיתיו קאי על בי\"ע שזהו לכבודי כמארז\"ל כל מה שברא הקב\"ה בעולמו לא ברא אלא לכבודו, ושמי קאי על אצי' ששם הוא ושמו בלבד, שבאצי' יש גילוי אלקות איהו וחיוהי חד ואיהו וגרמוהי חד, וזהו אתה הוי' לבדך אתה מלא ה' והיינו שבאצי' מאיר הה' פרצופים בשלימות כתר חו\"ב ז\"א ומל' שהם כנגד ד' אותיות דש' הוי' וקוצו של יו\"ד, אך את עשית השמים את חסר ה' שזה קאי על בי\"ע ששם אינו מאיר הה' פרצופים בשלימות, כי מה שלמטה יותר נתמעט כמו שאי' בתיקוני זהר אימא עילאה מקננא בכורסייא, פי' כורסיי' זהו בריאה ושם מאיר רק בינה ולא כתר וחכ', ושית ספירין מקננא ביצי' זהו מדות, ובינה אינו מאיר שם וכ\"ש כתר וחכ', ואימא תתאה מקננא בעשי' לכך חסר ה'. וזהו\"ע מ\"ש אלה תולדות השמים והארץ בהבראם כתי' ה' זעירא, כי יש ג' בחי' אותיות, אתוון רברבין ואתוון בינונין ואתוון זעירין, תורה בכלל הם אתוון בינונין, וענין אתוון זעירין היינו בחי' קטנות וצמצום שנקטן ונתצמצם כדי שיוכל להיות בריאת העולמות, והכא שחסר ה' הוא ע\"ד שאמרו ישראל למשה ואת תדבר אלינו ונשמעה אמר להם התשתם את כחי כנקיבה, והנה כאן שכתי' ג\"כ את חסר ה' הוא ג\"כ לשון התשת כח כנקיבה, וצ\"ל מהו\"ע התשת כח. אך בזהר ע\"פ לסוסתי ברכבי פרעה שיש ב' מיני סוסין סוסין דוכרין וסוסין נוקבין, סוסין הו\"ע אותיות כמ\"ש כי תרכב על סוסיך מרכבותיך ישועה, כמו שע\"י סוס יכול אדם לבוא למקום שבעצמו אינו יכול לבוא כך ע\"י אותיות ממשיכים וזאת התורה אדם, ויש אותיות דוכרין ואותיות נוקבין, ובכלל הם אותיות דש' מ\"ה ואותיות דש' ב\"ן, אותיות דוכרין שהם אותית התורה הם מש' מ\"ה ואותיות נוקבין שהם התהוות בי\"ע הם מש' ב\"ן שבגימט' בהמה, וזהו את חסר ה'.\n<b>אך</b> זה הי' בתחילת בריאת העולמות. וע\"י התורה ממשיכים מאתה הוי' לבדך לאת עשית את השמים, שבאתה עשית את השמים ואת הארץ יאיר ג\"כ הה\"ה כי תורה הוא חמשה חומשי תורה, וזהו\"ע ה' עילאה שהוא בינה והתגלות אוא\"ס הוא"],[2002180383,"בבינה. ובלקוטי תורה מהאריז\"ל איתא שחמשה חומשי תורה הוא כנגד ה' פרצופים דאצי' לכך יוכל להמשיך מאתה הוי' לבדך לאתה עשית את השמים ואת הארץ. וזהו מ\"ש תורת הוי' תמימה משיבת נפש, שיש שם ג' פסוקים פיסקא פיסקא, ובכל אחד מהם יש חמשה תיבות, שהה\"א תיבות הוא כנגד חמשה חומשי תורה שהו\"ע ה' עילאה, וא\"ו פיסקא הוא כנגד שיתא סדרי משנה והו\"ע וא\"ו שממשיכים ה' לוא\"ו, שזהו מאתה הוי' לבדך לאתה עשית את השמים ואת הארץ. וזהו נגילה ונשמחה בך, בך הוא כ\"ב אותיות התורה ובך הוא א\"ס עצמותו ומהותו, שע\"י אותיות התורה ממשיכים מא\"ס עצמותו ומהותו. וזהו\"ע שקיום העולם הוא בשביל תורה, שע\"י תורה ממשיכים מאתה הוי' לבדך לאתה עשית את השמים ואת הארץ, שבבי\"ע יאיר ג\"כ הה' פרצופים. וזהו הילך בתורתי, שהילוך שהוא ענין המשכה מלמעלמ\"ט זהו דוקא ע\"י תורה.\n<b>אך</b> כדי שיוכל להיות המשכה מלמעלה למטה צריך להיות תחילה העלאה מלמטלמ\"ע כמ\"ש אם ישים אליו לבו רוחו ונשמתו אליו יאסוף, כדי שיהי' רוחו ונשמתו אליו יאסוף צריך להיות תחילה אם ישים אליו לבו, ומהו העלאה זהו\"ע העלאה דתפלה. ובזה יובן מה שהמלאכים ביקשו את התורה כמ\"ש תנה הודך על השמים והשיבם כלום יצה\"ר יש ביניכם, ולכאורה מה זה תשובה הלא בלתי יצה\"ר יכולים לקיים יותר את התורה. אך הענין הוא דהנה העיקר של התורה הוא שיהי' יתרון האור מן החשך דוקא כד אתכפי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין. וזהו מ\"ש ימצאהו בארץ מדבר יסובבנהו, שהתורה ניתנה דוקא במדבר שנק' מדבר עמים, כי בא\"י יש גילוי אלקות לכך ניתנה התורה במדבר דוקא כדי שיהי' אתכפי' סט\"א. וזה הי' בעת נתינת התורה, ואנו אומרים נותן התורה, נותן הוא לשון הוה שבכל יום יש נתינת התורה, וכדי שיומשך המשכת התורה צ\"ל תחילה אתכפי'. ומהו האתכפי' זהו תפלה כי תפלה נק' בש' אכילה וכמ\"ש באתי לגני אכלתי יערי עם דבשי, יערי זו ברכת יוצר אור, ודבשי זו מתיקות דק\"ש, והיינו כמו אכילה הוא בירור שהמאכל מתעכל בקיבה ובאיצטומכא ונעשה דם שהמובחר עולה ללב ולמוח והפסולת נדחה לחוץ, וכך תפלה הו\"ע בירור טוב ורע וכמ\"ש רוממות אל בגרונם וחרב פיפיות בידם לעשות נקמה בגוים שע\"י רוממות אל בגרונם שזהו פסוד\"ז וחרב פיפיות בידם שזהו רמ\"ח שהו\"ע רמ\"ח תיבין דק\"ש עי\"ז יוכל להיות לעשות נקמה בגוים לדחות הרע שבנפשו.\n<b>וזהו</b> ע\"ד מ\"ש מצרף לכסף כור לזהב ואיש לפי מהללו, כמו שהצורף שצריך לעשות כלי אינו יכול לעשות הכלי עד שיהי' תחילה הגו סיגים מכסף ויצא לצורף כלי, כך ע\"י רוממות אל בגרונם וחרב פיפיות בידם עי\"ז יוכל להיות לעשות נקמה בגוים שיהי' דחיות הרע, והיכן הוא דחי' הרע בסלח לנו ובאשמנו ובכל הוידוים שאחר שמו\"ע. ובזה יובן מה שאנו אומרים סלח לנו בשמו\"ע, ולכאורה מה יש עוד פחיתות מחטאנו והי' צריך לומר קודם התפלה, והיכן אומרים זה אחר התבוננות דק\"ש ובשמו\"ע. והיינו מפני שקודם התפלה דרך איש ישר בעיניו כשאינו"],[2002180384,"עושה עבירות בפועל וכש\"כ כשעושה קצת מצוה נדמה לו שקרוב לאלקות, רק ע\"י תפלה שמתבונן באלקות עי\"ז מרגיש הרע שבנפשו ואפי' דקות הרע ג\"כ מרגיש, והוא ע\"ד מצרף לכסף כור לזהב שקודם הצירוף אינו ניכר הפסולת רק אחר הצירוף אז ניכר הפסולת, כך קודם התפלה אינו מרגיש הרע רק ע\"י התבוננות בתפלה יוכל להרגיש הרע שבנפשו, ולזה נק' התפלה בשם אכילה שהו\"ע בירור, ולכן לא ניתנה התורה למלאכים לפי שאין להם הבירור תחילה. וזהו מ\"ש הילך בתורתי, שיש שני מיני הילוך, הילוך דתורה מלמעלה למטה והילוך דתפלה מלמטלמ\"ע, ושיהי' ההילוך דתורה מלמעלמ\"ט צריך להיות הילוך דתפלה מלמטה למעלה. וזהו מה שאמר אבא בנימין כל ימי הייתי מצטער על תפלתי שתהא סמוכה למטתי כדי שיהי' התפלה קודם לימוד התורה, שתורה שלאחר התפלה הוא יותר נעלה.\n<b>והנה</b> כמו שיש ב' מיני הילוך בתורה ותפלה בכל ימי השבוע כמו\"כ בשבת יש ג\"כ ב' בחי' הילוך, העלאה והמשכה כמארז\"ל אלמלא שמרו ישראל שתי שבתות כהלכתן מיד היו נגאלין, והשתי שבתות אין המכוון על שתי שבתות ממש אלא שבכל שבת גופא יש ב' בחי' שבת, שבתא דמעלי שבתא ושבתא דיומא, ששבתא דמעלי שבתא הו\"ע העלאה כמ\"ש כי ששת ימים עשה הוי' את השמים ואת הארץ וביום השביעי שבת וינפש, והוא עד\"מ כמו באדם שעושה מלאכה משפיל המוחין ומחשבה בהמלאכה ואח\"כ כשגומר המלאכה אזי יש החזרת המוחין ומחשבה למקורן ושרשן, כך למעלה הגם שאין זה משל כלל כי לא בעמל ולא ביגיעה ברא הקב\"ה עולמו אלא במאמר וברוח פיו מ\"מ בעשרה מאמרות ברא את העולם שנקראים מילין דהדיוטא, ולאו אורחא דמלכא לאשתעי במילי דהדיוטא, הרי זה השפלה, וההשפלה היא במוחין ומחשבה כמו שאי' בעשרה דברים ברא הקב\"ה עולמו בחכ' ובתבונה ובדעת הרי זה השפלה במוחין, ובשבת שהו\"ע שביתה חוזרין המוחין למקורן ושרשן וזהו שבתא דמעלי שבתא שהוא העלאת המוחין למקורן, ושבתא דיומא הוא המשכת עונג מלמעלה למטה כמ\"ש וקראת לשבת עונג, אז תתענג על הוי'. וזהו הב' מיני הילוך העלאה והמשכה שבשבת.\n<b>וההפרש</b> שבין תורה ותפלה דחול לתורה ותפילה שבשבת, שתורה ותפלה שבחול הו\"ע חיצוני' ותורה ותפלה שבשבת היא פנימי', וזהו ע\"ד שמצינו ההפרש בין אכילת שבת לאכילת חול, עד\"ז נוכל להבין ההפרש בין תורה ותפלה של שבת לתורה ותפלה של חול, כי תורה ותפלה נק' בש' אכילה, תפלה כמו שנתבאר לעיל, ותורה כמ\"ש לכו לחמו בלחמי, לכך נוכל להבין זאת משני אכילות דחול ושבת. כי יש שני מיני אכילות כמ\"ש צדיק אוכל לשובע נפשו ובטן רשעים תחסר, בטן רשעים תחסר קאי על אכילת חול שמברר רפ\"ח ניצוצים שעצם המאכל הוא ממקום גבוה רק שנפל בשה\"כ בק\"נ, וע\"י שאוכל ומברך בתחילה וסוף עי\"ז מברר הניצוץ מרפ\"ח ניצוצים ומעלה אותו למקורו וזהו ובטן רשעים תחסר, שנחסר ניצוץ מרפ\"ח ניצוצים, וזהו אמלאה החרבה לא נתמלאה ירושלים אלא מחורבנה של צור, שע\"י חיל בלע ויקיאנו ומבטנו יורשנו אל, עי\"ז נתמלא ירושלים דקדושה וזהו"],[2002180385,"אכילת חול. אך בשבת בורר אסור וגם אכילת שבת אינו מגשם רק האכילה היא ע\"ד צדיק אוכל לשובע נפשו, נפשו הוא נפש דצדיק, וצדיק זה צדיק חי עלמין שהוא יסוד שממשיך מיסוד למל', ושובע נפשו הוא ע\"ד ואכלתם לחמכם לשובע, שובע שמחות את פניך, משביע לכל חי רצון, שממשיך רצון עליון דרך יסוד למל'. וכמו\"כ ההפרש בין תורה ותפלה של חול לתורה ותפלה של שבת, שתפילת חול הו\"ע בירור, אבל תפילת שבת ליכא ענין בירור ולכן אין אומרים סלח לנו בשבת.\n<b>וזהו\"ע</b> העלאה והמשכה של שבת, וביארנו שתורה ותפלה של שבת יותר גבוה מתורה ותפלה של חול, מ\"מ בכדי שיוכל לבוא לידי הילוך דשבת צריך להיות תחילה הבירור דחול, מי שטרח בע\"ש יאכל בשבת. ויש להביא ראי' לזה מהלכה פסוקה שבגמ' כמארז\"ל הי' מהלך בדרך במדבר ואינו יודע מתי שבת מונה ששה ימים ומשמר יום אחד, ולכאורה מאחר שאינו יודע מתי שבת הי' צריך לשמור מיד יום הראשון, והיינו מפני שא\"א לבחי' הילוך דשבת אלא דוקא ע\"י בירור תחילה דחול.\n<b>אך</b> הנה ב' בחי' הילוך אלו העלאה דחול והמשכה דשבת ובהם גופא יש העלאה והמשכה, תורה היא המשכה ותפלה היא העלאה, הם רק באתעדל\"ת אתעדל\"ע שהאתעדל\"ע היא לפי ערך אתעדל\"ת, אבל המן הוא אתעדל\"ע שגבוה מאתעדל\"ת, כי במן כתי' ותעל שכבת הטל והנה על פני המדבר דק מחספס דק ככפור על הארץ, אשר מן הו\"ע טל וטל הוא גבוה מגשם, שגשם תלוי באתעדל\"ת כמ\"ש ואד יעלה מן הארץ אבל בלא אתעדל\"ת אינו יכול להיות אתעדל\"ע, אבל טל אין לו הפסק לעולם כמארז\"ל כנס\"י שאלו שלא כהוגן והקב\"ה השיבם כהוגן, הם שאלו ויבוא כגשם לנו והקב\"ה אמר אהי' כטל לישראל וטל לא מיעצר, ולכן כשאמר אלי' חי הוי' אם יהי' טל ומטר, על המטר פעל ועל טל לא פעל, כי טל לא מיעצר שהוא אתעדל\"ע שאינו תלוי באתעדל\"ת, כי טל הו\"ע אור כמ\"ש כי טל אורות טליך, וכמו שאי' בגמרא כל המשתמש בטל תורה אור תורה מחייהו, ובילקוט גרסינן כל המשתמש בטל תורה טל תורה מחייהו, וכן אי' בתניא טל תורה<sup data-n=\"1191\">2</sup>, שטל ואור הו\"ע אחד, ואור הוא למעלה מבחי' מים, כי מים הו\"ע גליא של תורה, אבל אור שלמעלה ממים הוא סתום דתורה.\n<b>וזהו</b> מ\"ש במן והוא כזרע גד לבן וארז\"ל כאגדה זו שמושכת את הלב. והנה אגדה היא פנימי' התורה כך המן הוא פנימי' התורה, ואי' תלת קשרין מתקשרין דא בדא ישראל באורייתא ואורייתא בקוב\"ה וכולהו דרגא על דרגא סתים וגלי', שבישראל יש סתים וגלי', ובאורייתא יש סתים וגלי', ובקוב\"ה יש סתים וגלי', גליא",[["1191","2","<b>וכן אי' ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא</a> טל תורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא ספל\"ו (מו, ב</a>). אגה\"ק סי\"ז (קכו, א). וראה גם סה\"מ תרל\"ב ח\"ב ע' תקעד."]]],[2002180386,"דאורייתא מקשר גלי' דישראל וגלי' דקוב\"ה, וסתים דאורייתא מקשר סתים דישראל עם סתים דקוב\"ה, והמן ג\"כ מקשר סתים דישראל וסתים דאורייתא.\n<b>ועוד</b> י\"ל כזרע גד לבן, גד הוא ג' ד' ואי' בגמ' על ג' ד' גמול דלים, דל נק' יצ\"ט כמ\"ש אשרי משכיל אל דל שקאי על יצ\"ט כי נק' ילד חכם ומסכן והיצה\"ר נק' מלך זקן וכסיל, וזהו הפי' גמול דלים שיגביר יצ\"ט על היצה\"ר, והכח ע\"ז זהו המן שנותן כח ביצ\"ט להתגבר על יצה\"ר, שזהו אתעדל\"ע שלמעלה מאתעדל\"ת והוא כזרע גד לבן, לבן הוא לובן העליון שזהו מבחי' לבושי' כתלג חיור ושער רישי' כעמר נקי, ע\"ד מ\"ש וישכם לבן בבוקר ויעקב הלך לדרכו, דכדי שיהי' ויעקב הלך לדרכו ב' מיני הילוך דתורה ותפלה צריך להיות תחילה וישכם לבן בבוקר, בוקר זה חסד דאברהם ולבן זה לובן דקדושה שיומשך מלובן דקדושה לחסד דאברהם שזהו אתעדל\"ע שמעורר אתעדל\"ת, כך המן הו\"ע אתעדל\"ע שמעורר אתעדל\"ת. וזהו מ\"ש במן עומר לגלגולת שזהו מלבנינותא דתיקון עמר נקי שבגלגלתא. וזה הענין ג\"כ מצינו בציצית שנמשך ג\"כ מבחי' לבושי' כתלג חיור ושער רישי' כעמר נקי הזמן הוא משיכיר בין תכלת ללבן. וזהו מ\"ש ויקראו את שמו מן הוא ע\"ש הוי' מנת חלקי וכמארז\"ל ע\"פ ויצא מן בת ציון כל הדרה, מן כתי' יש לנו מנה אחת, הוי' מנת חלקי וכוסי אתה תומיך גורלי, גורל הוא למעלה מסדר השתל' שהו\"ע אתעדל\"ע שלמעלה מאתעדל\"ת.\n<b>וזהו</b> ג\"כ ענין של המן שנק' לחם אבירים כמ\"ש לחם אבירים אכל איש, ומהו לשון אבירים הוא ע\"ד משארז\"ל ע\"פ שמעו אלי אבירי לב הרחוקים מצדקה, כל העולם ניזון בצדקה הגם שאינם ראוים לזה והם נזונים בזרוע, ומהו\"ע אבירי לב שיש ב' מיני לב, יש אהבה דבכל מאודך ויש אהבה דבכל לבבך, בכל לבבך הוא ע\"פ טו\"ד, ואביר לב נק' אהבה בכל מאודך שלמעלה מהגבלת הכלי. וכשם שיש בהילוך דתפלה ענין אביר לב כך בהילוך דתורה יש ג\"כ אביר לב, כמ\"ש מידי אביר יעקב ויעקב הוא ההילוך דתורה ומצות. ובכדי שיוכל לבוא לידי השני אבירים הכח לזה הוא המן, ולכן נק' לחם אבירים ע\"ש אביר דתורה ואביר דתפלה. ועכשיו ניחא מה שהמן הי' הקדמה לתורה, שתורה הו\"ע המשכה מלמעלה למטה ותפלה הו\"ע העלאה מלמטה למעלה, וזהו רק אתעדל\"ע לפי ערך אתעדל\"ת, אבל המן הו\"ע אתעדל\"ע שמעורר אתעדל\"ת."],[2002180387,"<h3>צאינה וראינה</h3>\n<b></b><b>בס\"ד. יום ראשון דחג השבועות, תרל\"ט.</b>\n<b>צאינה</b> וראינה<sup data-n=\"1192\">1</sup> בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו, פי' מלך שלמה מלך שהשלום שלו זה הקב\"ה, אמו היינו כנס\"י כמארז\"ל לא זז מחבבה עד שקראה בתי לא זז מחבבה עד שקראה אחותי לא זז מחבבה עד שקראה אמי, ואמי זו כנס\"י, ביום חתונתו זו מ\"ת שבמ\"ת עיטרו כנס\"י עטרה להקב\"ה. וצ\"ל לכאורה הלא ארז\"ל בשעה שהקדימו ישראל נעשה לנשמע ירדו מלאכי השרת וקשרו שני כתרים לכאו\"א אחד כנגד נעשה ואחד כנגד נשמע, משמע שעטרו לכנס\"י עטרה בעת מ\"ת, ואיך קאמר שעטרה לו אמו זו כנס\"י.\n<b>אך</b> הענין הוא דשניהם אמת דהנה אי' במד\"ר ע\"פ קדושים תהיו והתקדשתם כי קדוש אני כתי' שלש פעמים קדוש<sup data-n=\"1193\">2</sup>, וקאמר משל למלך שעשו לו בני המדינה שלש עטרות, אחד נטל ונתן על ראשו, ושנים נתן על ראש בניו, כך העליונים מכתירים בכל יום ג' פעמים קדוש להקב\"ה כמ\"ש כתר יתנו לך מלאכים המוני מעלה ועמך ישראל כו' אחד נטל ונתן על ראשו זהו כי קדוש אני ושנים נתן על ראש בניו, פי' בניו הוא כנס\"י כמ\"ש בני בכורי ישראל, בנים אתם להוי', וזהו קדושים תהיו והתקדשתם. וזהו\"ע בעטרה שעטרה לו אמו זו עטרה שנטל לעצמו, וזה שאומרים שקשרו שני כתרים לכאו\"א זהו שנים שנתן בראש בניו. אך זה צ\"ל שהתם אומר העליונים מכתירים והכא קאמר בעטרה שעטרה לו אמו, אמו זו כנס\"י, שכנס\"י מעטירי' עטרה להקב\"ה. אך באמת אי' בגמ' שהמלאכים ממתינים מלומר שירה עד שיאמרו ישראל למטה שנא' ברן יחד כל כוכבי בוקר והדר ויריעו בני האלקים, שאין יכול להיות ויריעו בני אלקים כ\"א שיהי' תחילה ברן יחד כוכבי בוקר. וכן כתיב כתר יתנו לך מלאכים המוני מעלה ועמך ישראל קבוצי מטה, כי בכדי שיוכל להיות כתר יתנו לך מלאכים צ\"ל תחילה ועמך ישראל קבוצי מטה. נמצא שזה שהמלאכים מכתירים הוא דבר אחד עם עטרה שעטרה לו אמו שהוא תלוי בישראל דוקא.\n<b>אך</b> צ\"ל מה השירה של ישראל ק\"ש, והא אומרים בכל יום ק\"ש ומה קאמר ביום חתונתו זו מ\"ת דוקא. אך הנה אי' בגמ' מהיכן זכו ישראל לק\"ש ממ\"ת שאמר",[["1192","1","<b>צאינה וראינה</b>: הנחת א' מהשומעים מהמאמר הנדפס לעיל ע' תד ואילך. הנחה זו נמצאת בכת\"י 1185. וראה לעיל ע' תקפ הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה, ובהנסמן בהמ\"מ לשם."],["1193","2","<b>במד\"ר ע\"פ קדושים תהיו והתקדשתם כי קדוש אני כתי' שלש פעמים קדוש</b>: הוא חיבור ב' פסוקים, ראה קדושים יט, ב: קדושים תהיו כי קדוש אני ה'. ושם כ, ז: והתקדשתם והייתם קדושים. ובמד\"ר פ' קדושים (פכ\"ד, ח) המובא כאן מחבר ג\"כ ב' פסוקים אלו ומקשר זה עם הג' קדושות, וז\"ל: כך העליונים מכתירין להקב\"ה ג' קדושות, מה הקב\"ה עושה נותן בראשו אחת ושתים בראשן של ישראל, הה\"ד דבר אל כל עדת בנ\"י קדושים תהיו והתקדשתם והייתם קדושים. — וראה פי' מהרז\"ו למד\"ר שם."]]],[2002180388,"הקב\"ה שמע ישראל אנכי כו' ולא יהי' לך וענו ישראל הוי' אלקינו הוי' אחד, שזהו קבלה על אנכי ולא יהי' לך, הוי' אלקינו קבלה על אנכי והוי' אחד קבלה על לא יהי' לך. ואנכי ולא יהי' לך שניהם מפי הגבורה שמענו שהם כוללים כללות המצות, אנכי כולל כל רמ\"ח מ\"ע ולא יהי' לך כולל שס\"ה מל\"ת, וזה הי' בעת מ\"ת, ויש בחי' מ\"ת בכל יום שאנו מברכין נותן התורה נותן הוא לשון הוה, לכן אנו אומרים ק\"ש בכל יום. ונמצא מובן שעטרה שעטרה לו אמו ביום חתונתו קאי על כל יום ויום שבכל יום יש מ\"ת. ונמצא מובן מזה שמה שאומר בעטרה שעטרה לו אמו זהו עטרה שנתן על ראשו, ושנים שקשרו לכאו\"א זה השני עטרות שנתן על ראש בניו, וזהו שקאמר העליונים מכתירים מפני שתלוי בישראל, וקאמר ביום חתונתו זו מ\"ת קאי על כל יום ויום.\n<b>ולהבין</b> מהו\"ע הג' עטרות והג' פעמים קדוש צ\"ל מ\"ש והי' הנשאר בציון והנותר בירושלים קדוש יאמר לו, וקאמר בגמ' ע\"ז עתידים צדיקים שיאמרו לפניהם קדוש כדרך שאומרים לפני הקב\"ה ופרש\"י שיאמרו מלאכים קדוש לפני הצדיקים כדרך שאומרים עכשיו לפני הקב\"ה, ולכאורה אינו מובן האיך שייך לומר שיאמרו המלאכים שירה לפני הצדיקים כדרך שאומרים לפני הקב\"ה. ובספר כלי פז הביא שהרמ\"ק בספר הפרד\"ס שלו הקשה קושיא הלזו, וכתב שקשה הדבר להולמו איך יתכן שיאמרו מלאכים קדוש לפני הצדיקים כדרך שאומרים לפני הקב\"ה, ותירץ שם הרמ\"ק בס' הפרד\"ס שמה שנקראים צדיקים ע\"ש שמקיימים תורה ומצות שמצות נק' בשם צדקה לכן יתעלו בבחי' צדיק וצדק שהם יסוד ומל' שהם ספי' מע\"ס דאצי', וא\"כ כשהמלאכים דבריאה אומרים שירה לפני אצי' ממילא יאמרו לפני הצדיקים ג\"כ, לכן כתי' יאמר היינו שיאמר בדרך מאיליו וממילא. אך זה תירוץ דוחק. ורבינו תירץ תירוץ אחר, ובכדי להבין זה צ\"ל מה שאי' על שלשה דברים<sup data-n=\"1201\">3</sup> העולם עומד על תורה ועבודה וגמ\"ח, והנה שלשה דברים אלו הם כנגד ג' עטרות וג' פעמים קדוש.\n<b>ולהבין</b> זה הנה כתי' לרוקע הארץ על המים כי לעולם חסדו, פי' הנה מתחילת הבריאה היו המים מקיפי' את הארץ והארץ הי' מוקף במים מכל צד ופינה והיינו לפי שיש ד' יסודות ארמ\"ע, והנה ע\"פ דרכי הטבע יסוד היותר כבד נופל למטה והיסוד הקל הוא צף למעלה, וע\"כ יסוד העפר היותר כבד נפל למטה מטה ומים שקלים מעפר היו מקיפים את העפר, ורוח שיותר רוחני וקל כתי' ורוח אלקים מרחפת על פני המים, ואש היותר רוחני וקל משכנו תחת גלגל הירח, וזה הי' בתחילת הבריאה מצד הטבע, ואח\"כ גזר הקב\"ה גזירה יקוו המים אל מקום אחד ותראה היבשה, שארץ יהי' למעלה מן המים. וזהו מ\"ש יורדי הים באניות, שהולכי הים נקראים בשם יורדי שארץ גבוה מן המים. וזהו פי' כי לעולם חסדו, כי אמרתי עולם חסד יבנה, שזהו חסד כי בלא ארץ לא יוכל העולם להתקיים.",[["1201","3","<b>על שלשה דברים</b>: הנחת א' מהשומעים מהמאמר ד\"ה והנה איתא בס\"י אם רץ לבך הנדפס לעיל ע' תיא ואילך. והוא המשך להמאמר שלפנ\"ז ד\"ה צאינה וראינה. — הנחה זו נמצאת בכת\"י 1185. וראה לעיל ע' תקפו הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה.\nהמ\"מ וציונים למאמר זה כבר נסמנו לעיל בהמאמר."]]],[2002180389,"<b>אך</b> יש להבין מפני מה לא הי' בתחילת הבריאה כך שארץ יהי' למעלה מן המים, אף שהטבע היא כך שהמים צריך להיות למעלה מן הארץ, רק הלא הוא ית' הוא כל יכול ויכול לשנות הטבע שיהי' הארץ גבוה מן המים, כמו שמצינו שאח\"כ אחר הגזירה הי' כך, וכיון שלא הי' כך מסתמא מורה זה על איזה דבר.\n<b>אך</b> בכדי להבין זה צ\"ל תחילה ענין ים ויבשה, הנה ים ויבשה הו\"ע עלדאת\"כ ועלדאת\"ג. והנה אי' כל מה שיש ביבשה יש בים חוץ מן החולדה, וכשם שיש ברואים בעלדאת\"ג שהם נראים ונגלים כך יש ברואים בעלדאת\"כ שאינם נראים ונגלים, ובכלל קאי על מלאכים שמלאכים הם מעלדאת\"כ לכן הכלי שלהם אינו מסתיר ומעלים על חיות אלקי המחייהו, הגם שגם למלאכים יש גופים, רק הגופים שלהם הם רק מב' יסודות, ומאיזה מהם מהדקות שבהם מאש ורוח, כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט, לכן הגוף שלהם אינו מעלים ומסתיר. וזהו מה שמצינו במלאך שאומר בי נשבעתי נאום הוי', ולכאורה צ\"ל האיך יוכל לומר בי נשבעתי וגם נאום הוי' ש' העצם, והיינו מפני שעיקר הוא כח המשלחו המדבר בו והוא בעצמו אינו מעלים ומסתיר לכך יכול לומר בי נשבעתי. וכן מצינו במשה שאמר ונתתי מטר ארצכם, ולכאורה איך יכול לומר ונתתי מטר ארצכם, הלא כתי' הנותן מטר על פני ארץ ושולח מים על פני חוצות, ואי' בגמ' ע\"ז בחו\"ל הוא ע\"י שליח אבל בא\"י הוא דוקא ע\"י הקב\"ה. אך הענין הוא מפני שמשה הי' מעלדאת\"כ כמ\"ש מן המים משיתיהו, ואף לאחר שנשפל בעלדאת\"ג מ\"מ הי' תמיד בביטול כמו בעלדאת\"כ כמ\"ש ויקרא משה משה ולא כתי' פסיק טעמא ביניהו, ולא הי' הכלי שלו מעלים ומסתיר והי' שכינה מדברת מתוך גרונו של משה, לכן הי' יכול לומר ונתתי מטר. וזהו שנקראו מלאכים בשם נוני ימא רבא, והיינו שאנו רואים שברואים שבים הם מכוסים במי הים כי בריאתם הוא ממים וחיותם הוא בים, ולכן הם בקרירות כמו מים וחיותם הוא ממים, כי דגים שבים מיד שהם פורשים הם מתים. משא\"כ ברואים שביבשה אף שנתהוו מן הארץ ומקבלים חיות מן הארץ<sup data-n=\"1194\">4</sup>, התהוות הוא מהארץ דהיינו כדי להצמיח שצריך לרקוב הגרעין ואח\"כ נצמח הזרע, ואף שצריך להיות העלאת מ\"ן לכח הצומח שבארץ, מ\"מ הרי כ\"ז מן הארץ, וגבי מדבר כתי' וייצר הוי' את האדם עפר מן האדמה וכמו שאי' הכל הי' מן העפר אפי' גלגל חמה, וחיותם ג\"כ מן הארץ, ואעפ\"כ יכולים ליזון באויר ושטים על פני המים, ואפי' צמחים אינם צריכים",[["1194","4","<b>ברואים שביבשה אף שנתהוו מן הארץ ומקבלים חיות מן הארץ</b>: בהגהות להמאמר מהרה\"ח הרא\"ח ע\"ה ראזנבוים מביא את הבא לקמן כפי ששמע מכ\"ק אדמו\"ר מהר\"ש, וז\"ל: גם התהוות כל הברואים שביבשה הם מן הארץ. כי כל הדצח\"מ מתהווה מן הארץ, כי דומם הוא בעצמו יסוד העפר, וצומח הגם כי לכאורה התהוותו ע\"י הגרעין הנזרע בארץ, אבל באמת אינו כן, כי הלא הגרעין נרקב ונפסד ואינו אלא כי כח הצומח שבגרעין הנזרע הוא רק העלאת מ\"נ לכח הצומח שבארץ, אבל עיקר התהוותו הוא מכח הצומח שבארץ. גם חי ומדבר כתיב בהו תוצא הארץ נפש חי', וייצר כו' את האדם עפר מן האדמה, והכל הי' מן העפר אפי' גלגל חמה."]]],[2002180390,"לארץ<sup data-n=\"1195\">5</sup> כ\"א בעת קטנותן אבל מאחר שנתגדלו אינם צריכים עוד לארץ כלל. ובכלל זה קאי על מלאכים בגופים ונשמות בגופים, ומלאך הו\"ע שליח ותמיד צריך להיות בביטול להקב\"ה המשלחו ובאם יפרד רגע הרי אזי אינו נקרא מלאך, כמו דגים שבים מיד שהם פורשים מיד הם מתים, לפיכך יכול מלאך לומר בי נשבעתי ולכך אין להם בחירה, וזהו ג\"כ מדריגת משה שנאמר בו כי מן המים משיתיהו, וזהו ע\"ד מ\"ש וידגו לרוב בקרב הארץ שיש נשמות שאפי' שהם כאן בבחי' ארץ מ\"מ הם בטלים בביטול כמו דגים, רק זהו פרטי נשמות אבל בד\"כ כל הנשמות שנתלבשו בגוף שמעלים ומסתיר על חיות אלקי הם מעלדאת\"ג, וכמו ברואים שביבשה, שכמו ברואים שביבשה הם נפרדים מן הארץ כך הנשמות הם נפרדים, ולכן יש להם בחירה שאם ירצה האדם יוכל להיות כמשה רבינו וכמארז\"ל מתי יגיעו מעשי למעשה אבותי שזה קאי על האבות, וכן יכול להיות כמשה רבינו ע\"ה. וכמו\"כ אם רוצה יכול להיות בהיפוך ח\"ו.\n<b>ועתה</b> יובן מה שהי' בתחילת הבריאה המים גבוה מן הארץ, מצד כי עלדאת\"כ הוא במעלה יותר מעלדאת\"ג, וים הוא בחי' עלדאת\"כ לכן הי' בתחילת הבריאה למעלה מן הארץ שהוא בחי' עלדאת\"ג, אבל אח\"כ הי' הגזירה שהארץ יהי' למעלה מן המים כמ\"ש לרוקע הארץ על המים, כי עיקר המכוון של הבריאה היא הארץ שלכן ניתנה התורה למטה על הארץ דוקא, כמארז\"ל הים אמר אין בי, תהום אמר אין עמדי. ולכן מצינו שהמלאכים כשבקשו את התורה כמ\"ש תנה הודך על השמים והשיבם כלום יצה\"ר יש ביניכם. ולכאורה אין זה תירוץ כלל דאם היו מבקשים התורה כמו שהיא בגשמי' שפיר הוי במה שהשיבם כלום יצה\"ר יש ביניכם כי יש כמה מצות שאינם יכולים לקיימם בלא יצה\"ר, אבל המלאכים בקשו את התורה ברוחני' וא\"כ מהו\"ע של התירוץ כלום יצה\"ר יש ביניכם. אלא שלכך לא ניתנה התורה למלאכים להיות כי מפני עוצם הגילוי של תורה אי אפשר שתתגלה כ\"א למטה על הארץ. וזהו כי לעולם חסדו, חסד קאי על תורה, תורת חסד, וזהו דוקא לרוקע הארץ על המים, שהמכוון הוא שהארץ יהי' למעלה מן המים. והוא על דרך אותיות החקוקות על אבן טוב שלעוצם בהירותן אינו ניכר כלל האותיות אף ששם הוא עיקר האותיות מ\"מ אינו ניכר רק שנוטלין אותם בשעוה אז ניכר האותיות שבאבן טוב שזה הפעולה מהם, וכמו\"כ התורה א\"א שתתגלה כ\"א למטה על הארץ",[["1195","5","<b>יכולים ליזון באויר . . ואפי' צמחים אינם צריכים לארץ</b>: בהגהות להמאמר מהרה\"ח הרא\"ח ראזנבוים הנ\"ל מביא זה כפי ששמע מכ\"ק אדמו\"ר מהר\"ש, וז\"ל: יכולים להיות נפרדים, כמו החי ומדבר יכולים לחיות באויר או לשוט על פני המים, וגם הצומח אחר גידולו מן הארץ יכול להתקיים אפי' כשנקצץ ונפרד מן הארץ.\nואח\"כ מעיר ע\"ז הרא\"ח ראזנבוים: צ\"ע, הלא גם דגים שבים אינם חוזרים לאין ואפס כשנפרדים מן הים, רק כשפורשים מן הים מיד מתים והחיות שלהם נעדר. וכמו\"כ גם הצומח כשנפרד מן הארץ נסתלק ממנו החיות שלו היינו כח הצמיחה. ואולי כוונתו כי החילוק בזה שצומח כשנפרד מן הארץ יוכל להתקיים זמן ארוך יותר ולא ירקב בזמן מועט, כמו הברואים שבים כשפורשים, ודוחק. ואולי טבע הצומח שיש בו כמה ימים כח הצומח גם אחר כריתתו מהארץ, משא\"כ דגים שבים כיון שפורשים מיד מתים, דקדק לומר מיד דוקא."]]],[2002180391,"דוקא. וגם הנה כתי' אנכי עשיתי ארץ ואדם עליה בראתי, בראתי בגימט' תרי\"ג אלו תרי\"ג מצות, ואדם הוא ע\"ד שאי' ועל דמות הכסא דמות כמראה אדם ולכאורה איך שייך אדם למעלה<sup data-n=\"1196\">6</sup>, אלא הענין הוא כמו שמצינו למטה אדם הוא רמ\"ח אברים ושס\"ה גידים, כך למעלה אדם הוא רמ\"ח אברים רמ\"ח מ\"ע שס\"ה גידים שס\"ה מל\"ת, ואדם ובראתי הם עליה על הארץ דוקא, ובאמת קדמה ארץ במחשבה אפי' לשמים כמארז\"ל בש\"א שמים קדמו וב\"ה אומרים ארץ קדמה, ונת' שבאמת בסדר השתל' הארץ קדמה<sup data-n=\"1197\">7</sup> כמ\"ש בראשית ברא אלקים את השמים כו', אבל במחשבה ארץ קדמה לשמים וכמ\"ש ביום עשות הוי' אלקים ארץ ושמים, וכמו שאי' סוף מעשה עלה במחשבה תחילה, וכש\"כ שארץ קדמה לים שהשמים מקיפים את הים והארץ קדמה גם לשמים וכש\"כ שקדמה לים, לכן כתי' אח\"כ לרוקע הארץ על המים שהי' הגזירה יקוו המים אל מקום אחד ותראה היבשה.\n<b>ולהבין</b> זה בתוספות ביאור ענין ים ויבשה. הנה מי הים הם מלוחים וכמשארז\"ל שאסור לרחוץ בים בשבת ופי' רש\"י מפני שמחזי כרפואה, והרמב\"ם פי' הטעם<sup data-n=\"1198\">8</sup> מפני שמעמל שאין זה עונג שבת, והיינו כ\"ז הוא מפני שמי הים הם מלוחים, ולכן נקראים מנהיגי הים בשם מלחים כמ\"ש וייראו המלחים, וכמ\"ש כל אניות הים ומלחיהם, ע\"ש שמי הים הם מלוחים. והנה מים אלו כשהם בוקעים את עפר הארץ נעשו מים חיים שהמים של ים גופא נעשים אח\"כ מים חיים, וכמ\"ש כל הנחלים הולכים אל הים והים איננו מלא אל מקום שהם הולכים שם הם שבים ללכת, ומים חיים הוא גבוה במדריגה יותר נעלה מבחי' ים, היינו לענין טהרות טומאה יש דיעה שהים כמקוה שאינו מטהר בזוחלין, והגם שיש דיעה שמטהר בזוחלין מ\"מ טומאות חמורות כמו זב ומצורע אינו מטהר, ואפי' זבה יש דיעה בב\"י בשם רש\"י שאין מטהר אותה אלא מים חיים, רק אנן לא קיי\"ל הכי אלא כתוספת שאינה צריכה מים חיים כמו שמביאין ראי' מברייתא דתורת כהנים חומר בזב מבזבה שהזב צריך מים חיים וזבה אינה צריכה מים חיים, אבל מ\"מ הזב אין הים מטהר אותו אבל מים חיים מטהר כל הטומאות חמורות כי מים חיים הוא במדריגה גבוה יותר מים, וכמו שאי' באבות דר' נתן עשרה דברים נק' חיים הקב\"ה נק' חיים שנא' והוי' אלקים אמת הוא אלקים חיים, תורה נקרא' חיים שנאמר עץ חיים היא למחזיקים בה, מים נק' חיים שנאמר והי' ביום ההוא יצאו מים חיים מירושלים, וא\"כ מים חיים הוא מדריגה גבוה. והנה",[["1196","6","<b>ולכאורה איך שייך אדם למעלה</b>: בהגהות להמאמר מהרא\"ח ע\"ה ראזנבוים שם מביא זה כפי ששמע מכ\"ק אדמו\"ר מהר\"ש, וז\"ל: איך שייך ציור אדם למעלה, והלא אין לו דמות הגוף, אלא הוא ענין התורה, כדכתי' זאת התורה אדם, וכמו שהאדם כלול מרמ\"ח אברין ושס\"ה גידי' כן התורה כלולה מרמ\"ח מ\"ע, רמ\"ח פקודין רמ\"ח אברים דמלכא ושס\"ה ל\"ת."],["1197","7","<b>ונת' שבאמת בסדר השתל' הארץ קדמה</b>: ראה סה\"מ תרכ\"ז ע' רעו ואילך. תרכ\"ט ע' כג ואילך. שצ\"ח ואילך. תרל\"ב ח\"א ע' קט ואילך. וש\"נ."],["1198","8","<b>והרמב\"ם פי' הטעם</b>: בהגהות הרא\"ח ע\"ה ראזנבוים שם מביא זה כפי ששמע מכ\"ק אדמו\"ר מהר\"ש, וז\"ל: ואף לפי פי' הרמב\"ם מפני שמעמל את הגוף ואין זה עונג שבת, אבל מפני מה הוא מעמל את הגוף מפני שהמים שבים הם מלוחים."]]],[2002180392,"כמו\"כ המלאכים נק' בש' נוני ימא רבא מפני שהם מעלדאת\"כ, וכן הנשמות קודם התלבשותם בגוף שרשם הוא מעלדאת\"כ וכמ\"ש חי הוי' אשר עמדתי לפניו והעמידה הו\"ע ביטול ע\"ד מ\"ש במלאכים ויעמידם לעד לעולם, שפי' ויעמידם הו\"ע ביטול, כך כאן אצל נשמות העמידה הו\"ע ביטול, וגם בכתבי האריז\"ל מביא שבשביעי של פסח הוא לידת הנשמות והיינו מפני שאז הוא קי\"ס והנשמות קודם התלבשותם הם בים וכשנעשה קריעה בים נעשה לידת הנשמות, וכאשר הם בוקעים את עפר הגוף הם נקראים מים חיים שהוא במדריגה יותר נעלה, כמו במשל כאשר המי הים בוקעים עפר הארץ נעשו מים חיים כך כאן.\n<b>ולהבין</b> ענין מי הים מלוחים שלכאורה הוא חסרון, אך באמת זהו ג\"כ מעלה ומדריגה גבוה, רק שמים חיים הוא מדריגה היותר נעלה. כי פי' מלח הענין הוא כי הנה כתי' ולא תשבית ברית מלח אלקיך על כל קרבנך תקריב מלח, שמלח הוא ברית הוי' אלקיך, שענין מלח הגם שבעצמו אין לו טעם טוב מ\"מ הוא ממתיק מאכל אחר כמ\"ש היאכל תפל מבלי מלח. וכמו\"כ למעלה ענין מלח שממתיק הדינין דשם אלקים, שמשם אלקים יש ג\"כ יניקה לחיצוני' כמ\"ש ואתה מחי' את כולם כי בשם אלקים יש ק\"כ צירופים כי יש בו ה' אותיות וכל אות יש בו כ\"ד צירופים, כמו שאי' בס\"י שתי אבנים בונים שתי בתים שלש אבנים בונים ששה בתים וכו' ה' אבנים בונים כ\"ד בתים, וממ\"ח צירופים אחרונים שבשם אלקים יש יניקה לחיצונים, ופעולת המלח הוא שממשיך מבחי' טעמים דשם הוי' בשם אלקים להמתיק הדינין דשם אלקים. וגם ענין מלח שמפליט הדם מן הבשר, כן למעלה דם הוא בחי' הגבורות שבו נאחזים הקליפות, והמלח מפליט הדם. וזהו שמי הים הם מלוחים ע\"ש כי אותיות ים הם מצירופים אחרונים דשם אלקים כי יש בשם אלקים אותיות אלה ים, וממ\"ח צירופים אחרונים דשם אלקים משם הוא יניקת הקליפות וכמ\"ש ותשליך במצולות ים כל חטאתם, שמצולות ים הוא בחי' עמקי הקליפות, וזהו שמי הים הם מלוחים שהמלח הוא המשכת הטעם דשם הוי' בשם אלקים וכתי' הוי' בחכ', ושרש הטעמים הם גבוהים מאד שהוא מבחי' טנת\"א, וזהו מלח בגימ' מזל עם הכולל<sup data-n=\"1199\">9</sup> שנמשך ממזל שזהו מדריגה גבוה.\n<b>אמנם</b> מים חיים הם מדריגה היותר גבוה, ובד\"כ ההפרש בין מים חיים למי מלוחים, מי מלוחים הו\"ע צדיקים דכתי' אצל מלח ברית<sup data-n=\"1200\">10</sup> הוי' אלקיך, ומאן דנטיר ברית איקרי צדיק, הגם שבשביל מילה כל ישראל צדיקים כמ\"ש ועמך כולם",[["1199","9","<b>מלח בגימ' מזל עם הכולל</b>: בהגהות הרא\"ח ע\"ה ראזנבוים שם מעיר ע\"ז: צ\"ע מה היתה כוונתו בזה, ולמה לא אמר מלח גימ' מזלא כדאי' ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380090\" data-slug=\"likkutei-torah\" data-id=\"4001380090\">לקו\"ת</a> ד\"ה ולא תשבית מלח [לקו\"ת ויקרא ד, א]."],["1200","10","<b>דכתי' אצל מלח ברית . . ומאן דנטיר ברית אקרי צדיק</b>: בהגהות הרא\"ח ע\"ה ראזנבוים שם מביא זה כפי ששמע מכ\"ק אדמו\"ר מהר\"ש, וז\"ל: כי איתא בזהר מאן דאתגזר אקרי צדיק, ועמך כולם צדיקים. רק קיום מצות מילה בשלימותה הוא דווקא להיות נוטר ברית. ולכן נאמר גם במצות מילה לשון ברית כמו במלח, ואתנה את בריתי ביני ובינך, ואתה את בריתי תשמור, המורה על המשכת שם הוי'. (אבל בחי' בע\"ת הוא ענין לפני הוי' כו', כאשר ית' לקמן שזהו עמוד העבודה רזא דקורבנא עולה עד רזא דא\"ס).\nואח\"כ מעיר ע\"ז הרא\"ח ע\"ה ראזנבוים: אולי הי' כוונת אדמו\"ר מה שהביא ב' הפסוקים ואתנה את בריתי כו', גם ואתה את בריתי תשמור, להורות על מצות מילה ועל נטירת הברית. וצ\"ע למה נצרך להקריב מלח על כל קרבנך, והלא זה הוא עמוד העבודה, בחי' מים חיים כמו בחי' בע\"ת למעלה מבחי' בחכ' אתברירו, ואולי מטעם זה אמר מלח בגימט' מזל, ושרש המזל נמשך ממו\"ס שבו מלובש גבורה דע\"י. גם צ\"ע הלא מצות מילה ג\"כ מבחי' גבוה ר\"ת מילה וס\"ת הוי'."]]],[2002180393,"צדיקים, מ\"מ עיקר צדיק קאי על מאן דנטיר ברית, משא\"כ מים חיים הוא בחי' בעלי תשובה שבוקעים את עפר הארץ ובמקום שבעלי תשובה עומדים צדיקים גמורים אין יכולים לעמוד, וכמו שאי' בזהר זכאין אינון מארי תיובתא דמשכין לי' בחילא יתיר.\n<b>ובדרך</b> כלל ההפרש בין צדיקים לבעלי תשובה זהו ההפרש בין אהבה דבכל נפשך לבין אהבה דבכל מאודך, צדיקים הם בחי' אהבה דבכל נפשך שהיא אהבה שע\"פ טו\"ד וכמ\"ש לאהבה את הוי' כי הוא חייך, עד\"מ אדם כשהוא חולה אזי רוצה באמת שיתפשט הבריאות בכל הגוף, וכן כשיתבונן שהוא המחי' העולמות מכש\"כ שהוא אוהב אותו וזהו ע\"פ טעם ודעת, אבל אהבה דבכל מאודך זה אהבה בלי גבול תשוקה ורצוא להוי' שמגיע לעצמו' אוא\"ס ב\"ה שלמעלה מבחי' חכ'. ולאהבה דבכל נפשך יכולים לבוא גם מלאכים ונשמות קודם התלבשותן בגוף ונה\"ב כי האהבה היא ע\"פ טעם ודעת, אבל אהבה דבכל מאודך אינה באה אלא מההיפך דוקא דהיינו מבחי' ההסתר שמסיר מעליו ההסתר אזי יוכל לבוא לבחי' דבכל מאודך כמו למשל מים כשהם הולכים אינן הולכים בחוזק כ\"כ, אבל אם תעצר את הליכה ואח\"כ תעזוב אותה אזי המים הולכים ביותר כח שזהו ענין תשובה, שפי' תשובה אינו על עונות דוקא כ\"א שמסיר מעצמו ההעלם, כמו מי שהוא בעל עסק ועוסק במו\"מ אזי כל היום אינו יכול להיות דבוק לאלקות, ואח\"כ ששב להדבק לאלקות זהו ענין תשובה, ומזה נעשה אצלו תגבורת יותר וזהו אהבת בכל מאודך. ועד\"ז יובן מה שארז\"ל לעולם הוי זהיר בתפילת המנחה שהרי אליהו לא נענה אלא בתפילת המנחה, וזהו מפני כי בשחר כשאדם קם משנתו שנעשה ברי' חדשה ולא ראה שום היפך אין שום חידוש שמתפלל, אבל מנחה שכל היום הוא טרוד בעסקיו שהוא בחי' הסתר ושב מהעסק ומתפלל, ע\"ד תופל בכלי חרס שמדביק עצמו להוי', ה\"ז בחי' תשובה, לכך גדולה מעלת תפילת מנחה.\n<b>ועוד</b> יש הפרש בין אהבה דבכל נפשך לאהבה דבכל מאודך, שאהבה דבכל נפשך מאחר שהיא עפ\"י טעם ודעת ואין אדם יכול לעמוד בהתבוננות תמיד לכן יכולה לפסוק אחר התפילה, אבל אהבה דבכל מאודך הוא כמ\"ש אליך הוי' נפשי אשא וכמ\"ש בידך אפקיד רוחי ר\"ת באר, כמו באר שנובע תמיד כך אהבה זו דבכל מאודך מפני שהיא למעלה מטעם ודעת לכך יכולה להיות בתמידות. ובדרך כלל ההפרש שבין אהבה דבכל נפשך לבכל מאודך, האהבה דבכל נפשך הוא אהבה בכלי"],[2002180394,"אבל אהבה דבכל מאודך הוא אהבה שלמעלה מבחי' כלי וגבול, ועי\"ז מגיע לעצמו' אוא\"ס ב\"ה.\n<b>ועתה</b> יובן מ\"ש על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח שזהו עמוד העבודה, כי עבודה היא בחי' עבודת הקרבנות שמקריבין בהמה ע\"ג המזבח ואי' בזהר רזא דקורבנא עולה עד רזא דא\"ס, ועכשיו תפלה כנגד תמידין תיקנו, שע\"י בירור נה\"ב שזהו אהבה דבכל מאודך מגיעים לרוממות עצמו' א\"ס ב\"ה. וזהו בחי' קדוש הא', כי לזה האהבה דבכל מאודך צריכין התבוננות איך שהוא קדוש ומובדל, ובי\"ה הוי' צור עולמים, ביו\"ד נברא עוה\"ב ובה' נברא עוה\"ז, שזהו רק משני אותיות שאינם בערך לגבי דיבור וכש\"כ לגבי מחשבה וכש\"כ לגבי א\"ס ב\"ה ולא כמו שהנשמה ממלא את הגוף כך הקב\"ה ממלא את העולם, שהנשמה ממלא את הגוף ומתפעלת ממקרי הגוף אבל אצל הקב\"ה לא שייך שום שינוי, אשר ע\"י ההתבוננות זו תהי' לו רצוא ותשוקה ליכלל וליבטל לעצמות א\"ס שלמעלה מבחי' חכ', וזהו קדוש הא' שנטל לעצמו שממשיכים עי\"ז בחי' עטרה למלך שהשלום שלו, וזהו צאינה וראינה במלך שלמה בעטרה שעטרה לו אמו."],[2002180395,"<h3>על שלשה דברים</h3>\n<b></b><b>בס\"ד. מאמר ב' דצאינה וראינה הנ\"ל, יום ב' דחה\"ש, תרל\"ט.</b>\n<b>על</b> שלשה דברים העולם עומד על התורה ועבודה וגמ\"ח, הנה י\"ל שהשלשה דברים אלו הם כנגד ג' עטרות וג\"פ קדוש, ועמוד עבודה הו\"ע עבודת הקרבנות ורזא דקורבנא עולה עד רזא דא\"ס, ועכשיו תפלה כנגד קרבנות תיקנו שע\"י תפילה נעשה בירור נה\"ב ויכול לבוא לבחי' בכל מאודך לצאת מהגבלת הכלי לעוצם רוממות א\"ס שלמעלה מבחי' חכ' וכללות ע\"ס דאצי', וזהו\"ע בעטרה שעטרה לו אמו הכתר אשר ניתן בראשו, והוא בחי' רצוא פי' כליון וצמאון ותשוקה ליכלל בא\"ס עצומ\"ה.\n<b>אך</b> אי' בס\"י אם רץ לבך שוב לאחד, והו\"ע עמוד גמ\"ח שהו\"ע מעהמ\"צ שע\"י מעשה המצות ממשיכים גילוי אלקות למטה. וזהו שאנו מברכים אשר קדשנו במצותיו, פי' אשר הו\"ע עונג העליון, ואשר הוא לשון פלא שהו\"ע פלא, ועוד זאת"],[2002180396,"שע\"י מצות ממשיכין קדושתו של הקב\"ה למטה. והוא ע\"ד שאי' במד\"ר ע\"פ הנמצא כזה איש אשר רוח אלקים בו הה\"ד קמו בניה ויאשרוה בעלה ויהללה, ולכאורה מהו הסמיכות זל\"ז. אך הפסוק מתמה ע\"ז שאדם בגוף גשמי יש בו כ\"כ אלקות שיכול להשיג כ\"ז, לכן ראוי להללו ולשבחו, וזהו קמו בני' ויאשרוה בעלה וכו'. וכמו\"כ הפי' כאן אשר הוא מלשון אשרוני בנות, וזהו אשר קדשנו במצותיו שפלא הוא שע\"י מעהמ\"צ ממשיכין גילוי אלקות למטה, כי נתאוה הקב\"ה להיות לו ית' דירה בתחתונים וזהו ע\"י מעהמ\"צ. והגם שעכשיו הוא אינו כ\"א להוסיף אורות באצי', עכ\"ז הרי לע\"ל יהי' ע\"י מעהמ\"צ גילוי אלקות גם למטה, וגם עתה שהוא להוסיף אורות באצי' ה\"ה כמונח בקופסא.\n<b>וזהו\"ע</b> עמוד גמ\"ח שהו\"ע קדוש הב' כתר שנתן על ראש בניו. ובסידרא דקדושה מתרגם אלו ב' בחי' קדוש, קדיש בשמי' מרומא עילאה וקדיש על ארעא עובד גבורתי', קדיש בשמי' מרומא עילאה הו\"ע קדוש הא' בעטרה שעטרה לו אמו שנשאר רק למעלה כמו שאי' במד\"ר ע\"פ קדושים תהיו כי קדוש אני קדושתי למעלה מקדושתכם וזהו קדיש בשמי' מרומא עילאה, שנשאר רק למעלה. וקדיש על ארעא עובד גבורתי' הוא קדוש הב' שנתן על ראש בניו שהוא ע\"י מעהמ\"צ. ופי' על ארעא הוא כי מצות ניתנו דוקא למטה, כי מלאכים ביקשו תומ\"צ ולא ניתנו להם והשיבום כלום יצה\"ר יש ביניכם שלא ניתנה התורה אלא על הארץ כמ\"ש אנכי עשיתי ארץ ואדם עלי' בראתי, בראתי גימט' תרי\"ג והוא על הארץ דוקא, כי לעוצם רוממות התומ\"צ לא ניתנה רק על הארץ, וזהו\"ע קדיש על ארעא עובד גבורתי'.\n<b>וקדוש</b> הג' הוא לעלם ולעלמי עלמיא הו\"ע תורה שניתנה לכ\"ו דור, כי לכאורה איך יכול האדם שהוא מוגבל בשפלות נפשו ופחיתות ערכו לבוא ע\"י אהבה דבכל מאודך לבחי' מאוד העליון להיות בעטרה שעטרה לו אמו, או ע\"י מעהמ\"צ להמשיך גילוי אלקות למטה, לזה ניתן כח בתורה כי בתורה יש ב' בחי' דיבור התורה כמ\"ש וידבר הוי' אל משה לאמר דבר אל בנ\"י ואמרת, וכתי' והיו הדברים האלה וארז\"ל בדברי תורה הכתוב מדבר, ושננתם לבנך ודברת בם, וכן אי' בתושבע\"פ ע\"פ ערוכה בכל ושמורה אם ערוכה בכל רמ\"ח אברים אז היא שמורה, והפי' הוא שצריך ללמוד בדיבור ובכל כוחות נפשו, וע\"י בחי' דיבור תורה נתעורר לו כח שע\"י מצות ממשיך גילוי אלקות. ועוד יש בחי' תורה שבו נכלל פילפול, והו\"ע התקשרות מחשבתו במח' התורה בפנימי' ועמקות ומקיף ומוקף, והו\"ע הגיון כמ\"ש ובתורתו יהגה, והגית בו יומם ולילה, והגיון הוא בלב כמ\"ש והגיון לבי, ולבך יהגה, וע\"י בחי' הגיון תורה נתעורר לו כח לבוא לבחי' אהבה דבכל מאודך, ועי\"ז מגיע לבחי' מאוד העליון להיות בעטרה שעטרה לו אמו. ובכלל הוא ההפרש בין תושב\"כ לתושבע\"פ, כי תושב\"כ הו\"ע אותיות כי כל התורה כולה היא שמותיו של הקב\"ה, ואנו רואים עד\"מ שם אברהם או ראובן כשקורין לו בשמו הוא משיב הרי השם הוא אותיות, כן למעלה כל התורה כולה רק אותיות ואין אנו משיגים כל הכוונות מהאותיות, וכל הקורא בתורה הקב\"ה קורא ושונה כנגדו שהו\"ע המשכה,"],[2002180397,"וכן ע\"י כל המצות ממשיכין גילוי אלקות. ותושבע\"פ הו\"ע עיון התורה, והאותיות אינם עיקר, ואף שזה שארז\"ל ערוכה בכל ושמורה הי' על תלמיד אחד שלמד בחשאי שצריך להיות בכל רמ\"ח אברים, עכ\"ז העיקר אינו דוקא האותיות רק השכל הוא העיקר, וכשלומד הלכה קודם שמשיג אותה הרי שכל ההלכה מקיף אותו, ואח\"כ כשמשיג ההלכה ה\"ה מקיף שכל ההלכה והו\"ע מקיף ומוקף יחוד נפלא שאין כמוהו לכן נותן כח שע\"י בחי' בכל מאודך יכול להגיע למעלה לבחי' מאוד העליון להיות קדיש בשמי' מרומא עילאה. וזהו מארז\"ל אם פגע בך מנוול זה משכהו לבהמ\"ד אם אבן הוא נימוח, מנוול זה יצה\"ר ובהמ\"ד הו\"ע דרשות תושבע\"פ, ואם אבן הוא נימוח פי' אפי' לבו כלב האבן, ע\"ד מ\"ש על לע\"ל והסירותי את לב האבן מבשרכם ונתתי לכם לב בשר והוא כמ\"ש יבוא כל בשר להשתחוות לפני והוא ע\"י תושבע\"פ. נמצא שבתורה יש ב' בחי' שע\"י אהבה דבכל מאודך יכול להגיע למעלה לבחי' קדיש בשמי' מרומא עילאה, וע\"י מעהמ\"צ יכול להמשיך גילוי אלקות למטה.\n<b>והנה</b> זה הי' בכלל בעת מ\"ת דכתי' וירד הוי' על ה\"ס, וכל העם רואים את הקולות רואים את הנשמע ושומעים את הנראה, אנכי ולא יהי' לך מפי הגבורה שמענו שהוא כללות התורה כי אנכי הוא כולל רמ\"ח מ\"ע ולא יהי' לך כולל שס\"ה מל\"ת וכל העם ענו ואמרו הוי' אלקינו הוי' אחד שהו\"ע קבלה שקבלו התורה וזהו בעת מ\"ת, ואנו מברכים בכל יום נותן התורה נותן הוא לשון הוה שבכל יום יש ענין מ\"ת להגיע ע\"י בכל מאודך למעלה ג\"כ לבחי' מאוד העליון להיות קדיש בשמי' מרומא עילאה, וע\"י מעהמ\"צ להמשיך גילוי אלקות למטה להיות קדיש על ארעא עובד גבורתי'.\n<b>ובכלל</b> הו\"ע ג' פרשיות דק\"ש, פרשה א' ואהבת עד ובשעריך מ\"ב תיבות שהוא בחי' שם מ\"ב שאי' בזהר שם מ\"ב עולה ואינו יורד, כן בפ' זו הו\"ע אהבה בכל מאודך לצאת מהגבלת הכלי לעוצם רוממות א\"ס ב\"ה כמו ענין קרבנות שרזא דקורבנא עולה עד רזא דא\"ס, כן אהבה דבכל מאודך מגיע לא\"ס ב\"ה והו\"ע בעטרה שעטרה לו אמו רק לו, והוא קדוש הא'. כן הו\"ע שם מ\"ב שעולה ואינו יורד. ופ' שני' הוא כנגד קדוש הב' שע\"י מעהמ\"צ ממשיכין גילוי אלקות, ובפ' זו כתי' והי' אם שמוע תשמעו אל מצותי ויש השפעות רוחני' והשפעות גשמי'. ובפ' ויאמר הו\"ע תורה שכתי' בה אני הוי' אלקיכם אשר הוצאתי אתכם מאמ\"צ, והענין הוא כי אדם יכול להשפיל א\"ע ולומר איך אפשר שאני מוגבל ובהגשמה ואיך אוכל ע\"י בכל מאודך להגיע למעלה לבחי' מאוד להיות בעטרה שעטרה לו אמו, או ע\"י מעהמ\"צ להמשיך גילוי אלקות למטה, ועז\"נ אשר הוצאתי אתכם מאמ\"צ, כי במצרים היו משוקעים במ\"ט שערי היפוך ובמשך חמשים יום הגיעו לשער הנו\"ן דקדושה, ושם הי' מ\"ת, ולא בעת מ\"ת לחוד הי' זה כי בכל דור ודור חייב אדם לראות א\"ע כאלו הוא יצא ממצרים, ובאמת כן הוא בכ\"י ויום, וכמו שיש מצרים בלעומת זה כן יש מצרים דקדושה שע\"י מצרים וגבולים נעשים לו רצונות זרות וע\"י יצ\"מ ממילא נופלים ממנו המח\"ז, וע\"י כח התורה יכול לבוא לבחי' העלאה והמשכה. וזהו דכתי'"],[2002180398,"וידבר אלקים את כל הדברים האלה לאמר שלכאורה תיבת לאמר מיותר, התינח בכל התורה שכתי' וידבר הוי' אל משה לאמר הפי' הוא שהוי' דיבר אל משה שיאמר לכל ישראל, אבל עשה\"ד הלא כל ישראל שמעו וכמארז\"ל אנכי ולא יהי' לך מפי הגבורה שמענו, ומהו לאמר. אך פי' לאמר הוא לדורות, וכל הדברים הו\"ע כל מה שתלמיד ותיק עתיד לחדש הכל ניתנה בתורה. נמצא כמו שבמ\"ת הי' העלאה והמשכה שעכדו\"ד פרחה נשמתן שהו\"ע העלאה והי' קבלת התורה, כן בכל יום ויום יש בחי' מ\"ת העלאה והמשכה, שע\"י אהבה דבכל מאודך מגיע לבחי' מאד העליון שהו\"ע כתר שניתן בראשו קדוש הא' והו\"ע כתר דאריך, ופ' שני' הו\"ע שע\"י המצות ממשיך גילוי אלקות, וכ\"ז ניתנה בכח התורה.\n<b>וזהו\"ע</b> שני כתרים שנותן על ראש בניו כתר ז\"א וכתר מל' שהוא כנגד נעשה ונשמע. וצ\"ל שבמקום אחר נת' שנעשה ונשמע הו\"ע אורות וכלים, נעשה הו\"ע אורות, ונשמע הו\"ע כלים<sup data-n=\"1202\">1</sup>, והכא נתבאר שנעשה ונשמע הו\"ע תומ\"צ. אך באמת שניהם עולים בקנה א', כי הנה כתי' כי נר מצוה ותורה אור שהמצות נמשלו לנר כמו נר הוא הכלי המחזיק שמן ופתילה, ובשמן ובפתילה נאחז האור, הרי הנר הוא הכלי המחזיק שמן ואור ופתילה, כן הו\"ע מצות הם כלים לתורה שנק' אור וכמ\"ש כלים ריקים אל תמעיטי, כשיש כלי יש אור, וכמ\"ש אין עוד כלי ויעמוד השמן, שכ\"ז שיש כלי יש שמן. וזהו שאנו אומרים קדשינו במצותיך ותן חלקינו בתורתך, שמתחילה צ\"ל מצות שהם כלים ואח\"כ תורה שהו\"ע אור.\n<b>ומעתה</b> צ\"ל מארז\"ל בשעה שהקדימו ישראל נעשה לנשמע ירדו מלאכי השרת וקשרו להם שני כתרים, משמע הואיל והקדימו נעשה לנשמע, אבל משום נעשה ונשמע לחוד לא הי' נותנים להם השני כתרים, והדרוש הזה סובב ונתבאר שנעשה ונשמע הו\"ע תומ\"צ משמע בשביל תומ\"צ לבד ניתנו השני כתרים.\n<b>אך</b> הענין הוא כי כאן נת' שהג' פרשיות ק\"ש הו\"ע ג' פעמים קדוש, ופ\"א קדוש הוא בחי' בכל מאודך והו\"ע פי' אחד בשעה שהקדימו שהענין הוא הגם שלא ידעו מה שיצוה עליהם ואף שיצוום דברים שא\"א לקיימם עכ\"ז הקדימו והו\"ע ביטול הרצון לבעהר\"צ, וכן הו\"ע פרשה ראשונה בכל מאודך שנק' עושין רצונו של מקום, ופי' עושין הו\"ע כפי' והכרח, ופ' ראשונה נק' עורש\"מ כמארז\"ל איך אפשר אדם חורש בעת חרישה וזורע כשהוא זורע וקוצר בעת קצירה ותורה מה תהא עלי', ויש שם תירוץ ע\"ז. ועוד שם פעם א' אומר ועמדו זרים ורעו צאנכם ופעם א' אומר ואספת דגנך ותרצו שם כאן בזמן שישראל ערש\"מ וכאן בזמן שאין ישראל ערש\"מ, בזמן שישראל ערש\"מ מלאכתן נעשית ע\"י אחרים ועז\"נ ועמדו זרים ורעו צאנכם",[["1202","1","<b>שבמקום אחר נת' . . נעשה הו\"ע אורות ונשמע הו\"ע כלים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א מג\"א צז, א</a>. [ושם: נעשה פי' הכלים . . ופי' נשמע הוא האור. וכ\"ה גם לעיל בהמאמר ע' תיג]."]]],[2002180399,"ובזמן שאין ישראל ערש\"מ מלאכתן נעשית ע\"י עצמן ואספת דגנך, והקשו שם התוס' הלא באיזה מקום כתי' ואספת דגנך בפ' ב' דק\"ש וכתי' והי' אם שמוע והאיך נק' אין ערש\"מ, ותירצו שם שאין ערש\"מ כ\"כ הואיל שכתי' רק בכל לבבך ובכל נפשך ולא כתי' בכל מאודך, משמע שבפ' א' שכתי' שם בכל מאודך נק' ערש\"מ, נמצא כמו בשעה שהקדימו הו\"ע ביטול הרצון לבעהר\"צ כך ע\"י בחי' בכל מאודך שנק' ערש\"מ מגיע לבחי' א\"ס שלפני הצמצום ושיתהוה צמצום ראשון רצון אותיות צינור, והו\"ע רצונות פרטיים ע\"י תומ\"צ, כי בשביל רצונות הפרטיים בלבד שהו\"ע תומ\"צ לא הי' צריך להקדים נעשה לנשמע אך בכדי שיהי' רצון פשוט הו\"ע הקדימה, וכן הו\"ע אהבה דבכל מאודך והו\"ע קדוש הא' כתר אשר ניתן בראשו. ואח\"כ ע\"י תומ\"צ שהו\"ע פ' השני' דק\"ש והג' ויאמר נעשה שני כתרים בראש בניו.\n<b>והכח</b> לזה ניתנה בתורה, כי לכאורה איך אפשר אדם מגושם ומוגבל ע\"י הנחת תפלין להמשיך ד' מוחין הלא הדיו הוא גשמי' ותפילין הם מקלף גשמי ואדם גשמי וע\"י הנחת תפילין נעשה המשכת מוחין לז\"א שהו\"ע מדות מקור לעולמות וכמ\"ש כי אמרתי עולם חסד יבנה. וכן ע\"י מצות צדקה ממשיך להחיות רוח שפלים אפי' לעולמות עליונים, כי קמי' ית' אפי' עולמות עליונים דלים ושפלים נחשבים, אך הכח לזה ניתנה בתורה, כי האבות קודם מ\"ת קיימו כל המצות כמארז\"ל קיים אאע\"ה כל התורה כולה עד שלא ניתנה, והי' ע\"י מס\"נ, אבל עתה ניתן הכח בתו' אפי' שלא ע\"י מס\"נ כמו מצות תפילין רק בכוונה הפשוטה היינו לשעבד הלב והמוח ועי\"ז נעשה המשכת מוחין לז\"א, או מצות הצדקה רק בכוונה להחיות רוח שפלים למטה, ועי\"ז נעשה ממילא בעולמות עליונים תוס' חיות, או ע\"י שמירת שבת נעשה המשכת מוחין דאבא וביו\"ט מוחין דאימא, כי ע\"י מצות נעשה הגדלת הכלים. והענין הוא כי ז\"א הוא בעל ט\"ס וט' פעמים ט' הרי פ\"א ורת\"ס וה\"ח המגדילים הם מספר רמ\"ח, והוא ע\"י רמ\"ח מ\"ע. ובזה יובן מה כשהאדם מעורר בעצמו בחי' בכל מאודך בל\"ג עי\"ז מגיע למעלה לבחי' מאוד העליון, הלא לכאורה אדם הוא מוגבל ומגושם אפי' כשאצלו הוא בל\"ג הרי לגבי למעלה הכל הוא בחי' גבול ולא נק' אתעדל\"ע כעין אתעדל\"ת. אך הענין הוא כמ\"ש במד\"ר ע\"פ הן אל ישגיב בכחו מי כמוהו מורה כשהוא נותן נותן לפי כוחו וכשהוא מבקש אינו מבקש אלא לפי כוחן כמ\"ש שור או כשב או עז כי יולד ולא איל וצבי ויחמור שאינו בנמצא כ\"כ, וכן כשאדם מעורר אצלו בחי' בכל מאודך שהו\"ע בל\"ג עי\"ז מעורר למעלה בחי' מאוד העליון, והענין הוא כי כך עלה ברצונו הפשוט. וזהו\"ע הג' עטרות שבג\"פ ק\"ש, פ' הא' הו\"ע בכל מאודך שעי\"ז נעשה בחי' כתר שנתן בראשו, וב' פרשיות והי' ויאמר שהו\"ע תומ\"צ עי\"ז נעשה השני כתרים שנתן על ראש בניו.\n<b>אך</b> זה הי' במ\"ת ואח\"כ נטלו מהם כמ\"ש ויתנצלו את עדים מהר חורב, ועתיד הקב\"ה להחזירן כמ\"ש ופדויי ה' ישובון ובאו לציון ברינה ושמחת עולם על ראשם ששון ושמחה ישיגו ונסו יגון ואנחה, וארז\"ל פי' שמחת עולם על ראשם היינו שמחה שמעולם על ראשם, והיינו השני כתרים שנתן להם ע\"י מלאכי השרת עתיד"],[2002180400,"הקב\"ה להחזירן, וזהו מדריגה עוד יותר נעלה, שמתחילה הי' ע\"י מלאכי השרת, ולע\"ל הקב\"ה בעצמו יחזירם. והענין הוא כמארז\"ל לע\"ל צדיקים יושבין ועטרותיהם בראשיהם, ופי' ענין עטרה הו\"ע כתר וכמו שכדי שיומשך מאוא\"ס לע\"ס הוא ע\"י כתר שכתר הוא ממוצע בין המאציל לנאצלים, כן לע\"ל יהי' עטרותיהם בראשיהם היינו בחי' חי' שעתה הוא בבחי' מקיף ולע\"ל יאיר בנר\"נ, וזהו\"ע שמחת עולם על ראשם. וששון ושמחה הוא יסוד ומל' דקדושה, ויגון ואנחה הו\"ע יסוד ומל' דלעומת זה, כי זה לעו\"ז עשה אלקים ולאום מלאום יאמץ כשזה קם זה נופל וכשיאיר ששון ושמחה ממילא יהי' ונסו יגון ואנחה.\n<b>ולכן</b> עתידין צדיקים שיאמר לפניהם קדוש, ובלשון קבלה הענין הוא שיתעלה בדרך אור חוזר מל' בכתר שלמעלה מבחי' צדיק וצדק. והענין הוא כי הנה כתי' והיה ביום ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני, ופי' ענין ים הקדמוני הו\"ע ים החכ' שיהי' מים חיים, הענין הוא שיש ב' בחי' גידים, א' גידים הבוקעים עפר הארץ להיות נהר, ויש גידים המחוברים לתהום והו\"ע ב' בחי' אין, וזהו מלמעלמ\"ט, ולע\"ל יהי' מל' בכתר בדרך אור חוזר מלמטה למעלה, ולכן כל הנשאר בציון והנותר בירושלים קדוש יאמר לו, כי פי' ענין ציון הוא פנימי' ירושלים והו\"ע תורה כמ\"ש כי מציון תצא תורה ודבר הוי' מירושלים, והענין הוא כי בנש\"י יש ב' בחי', בעלי תורה מארי תורה, ובעלי עסקים, בעלי תורה הו\"ע כל הנשאר בציון, ובעלי עסקים שאינו יכול ללמוד תורה בתמידות והם ע\"י מעהמ\"צ בשלימות היראה שהוא יראה שלם עי\"ז מגיע לבחי' כתר, ולכן כל הנשאר בציון והנותר בירושלים קדוש יאמר לו. וזהו\"ע מ\"ש לאמר לציון עמי אתה, פי' עמי אתה כתר אחד לשניהם ולכן קדוש יאמר לו.\n<b>ומעתה</b> יובן פי' צאינה וראינה בנות ציון בעטרה שעטרה לו אמו, פי' שיהי' וראינה צ\"ל צאינה והו\"ע ההילוך כמ\"ש והתהלכתי בתוככם שיש ב' מיני הילוך מלמעלמ\"ט ומלמטלמ\"ע. והענין הוא כי אי' בילקוט עתיד הקב\"ה לטייל עם צדיקים בעלמא דאתא, כי הנה כתי' והי' מידי חודש בחדשו ומידי שבת בשבתו יבוא כל בשר להשתחוות לפני, והפי' הוא כי בכל ימי החול בחו\"ל מאיר ו\"ק דעשי' ולפעמים ו\"ק דיצי', ובא\"י מאיר ו\"ק דיצי' ולפעמים ו\"ק דברי', ובשבת שאז הוא עליות העולמות הרי אז התכללות ו\"ק דעשי' ביצי' וו\"ק דיצי' בבריאה וו\"ק דברי' באצי', ובר\"ח העלי' הוא בדיבור, אבל לע\"ל יהי' חודש בחדשו ושבת בשבתו העלאה באר\"ע<sup data-n=\"1203\">2</sup>, ויבוא כל בשר להשתחוות לפני כמ\"ש השמים החדשים והארץ החדשה אשר כו' עומדים לפני שיהי' העלי' בפנימי'. וזהו ענין מ\"ש בילקוט לטייל בג\"ע כי ג\"ע הוא ענין עליות כמ\"ש מי יעלה בהר הוי'. וזהו פי' צאינה שהו\"ע ההילוך שיהי' לע\"ל, ואז וראינה שעתה הוא בעטרה שעטרה לו אמו שפי' לו דוקא למעלה מהשגה,",[["1203","2","<b>העלאה באר\"ע</b>: כ\"ה בכת\"י. ואולי הכוונה: בעילוי אחר עילוי. או: באין ערוך. או: בארץ עילאה."]]],[2002180401,"אבל לע\"ל וראינה בבחי' השגה ולכן כל הנשאר בציון והנותר בירושלים קדוש יאמר לו.\n<b>ועוד</b> י\"ל מפני מה קדוש יאמר לו כי הנה כתי' ואנשי קדש תהיון לי, שלע\"ל יתעלו בבחי' קדש שלמעלה מקודש<sup data-n=\"1204\">3</sup> שהוא בוא\"ו אלא בבחי' קדש שהוא בלא וא\"ו, שהוא מלה בגרמי', והפי' הוא שעתה אומרים המלאכים קדוש הוי' צבאות, אבל לע\"ל יהי' בחי' קדש ע\"ד מ\"ש שאו ידיכם קדש וברכו את הוי' שיומשך מבחי' קדש להוי', ולכן גם מלאכים עליונים יאמרו לפני נש\"י קדוש. ועוי\"ל שעכשיו הוא בעטרה שעטרה לו אמו והוא כי הכח ניתן באמו לעטר עטרה לו דוקא, אבל לא שהם עצמן הם בחי' עטרה אבל על לע\"ל כתי' אשת חיל עטרת בעלה שאשת חיל תהי' העטרה, ופי' אשת חיל הוא כנס\"י שלע\"ל תהי' בחי' עטרה, ולא כמו שנת\"ל שיתעלה מל' בכתר, רק בעצמן יהיו בחי' העטרה, ולכן קדוש יאמר לו. נמצא מובן עתה שכל הנשאר בציון והנותר בירושלים קדוש יאמר לו מג' טעמים הן, לטעם הא' שמל' יתעלה בכתר, או מטעם הב' שיתעלה במדריגת קדש, והן לטעם הג' שא\"ח יהי' עט\"ב לכן קדוש יאמר לו.\n<b>וזהו</b> פי' על שלשה דברים העולם עומד על התורה ועבודה וגמ\"ח, על התורה הוא כמ\"ש ואשים דברי בפיך, ועל גמ\"ח כמ\"ש בצל ידי כסיתיך, ועל העבודה הוא כמ\"ש לנטוע שמים וליסוד הארץ שקאי על קרבנות כמו שאי' בזהר ע\"פ והנה סולם מוצב ארצה וראשו מגיע השמימה שהו\"ע קרבנות שריחן עולה עד השמים, ופי' ענין עמוד העבודה הו\"ע עבודת הקרבנות ורזא דקורבנא עולה עד רזא דא\"ס. ועכשיו תפילה כנגד תמידין תיקנו, שע\"י התפילה יכול לבוא לבחי' בכל מאודך לצאת מהגבלת הכלי לעוצם רוממות א\"ס ועי\"ז נעשה בעטרה שעטרה לו אמו. ועי\"ז מגיע לע\"ל שכל הנשאר בציון והנותר בירושלים קדוש יאמר לו.",[["1204","3","<b>קדש שלמעלה מקודש</b>: אוצ\"ל: קדש שלמעלה מקדוש. (כדלעיל בהמאמר ע' תטז)."]]],[2002180402,"<h3>הנני ממטיר</h3>\n<b></b><b>בס\"ד פ' נשא תרל\"ט הנחה.</b>\n<b>הנני</b> ממטיר<sup data-n=\"1205\">1</sup> לכם לחם מן השמים ויצא העם ולקטו דבר יום ביומו למען אנסנו הילך בתורתי אם לא. הנה י\"ל שיש ב' מיני הילוך מלמטלמ\"ע ומלמעלמ\"ט והו\"ע תורה ותפילה, שהו\"ע אתעדל\"ת ואתעדל\"ע כעין אתעדל\"ת, והמן הי' הקדמה למ\"ת, וצ\"ל מהו\"ע הנסיון דמן, ועוד משמע שגם בתורה יש נסיון.\n<b>ולהבין</b> זה הנה במן כתי' ולקטו דבר יום ביומו ואיש אל יותר ממנו עד בוקר, והוא ע\"ד מארז\"ל כל מי שיש לו פת בסלו ודואג על מחר ה\"ז מקטני אמנה, שהו\"ע קטנות. וצ\"ל מפני מה המן לא יותר ממנו עד בוקר הלא כל השפעות שנשפעים מלמעלה מותר להכין מיום לחבירו ואין לך עשב למטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל, והמן אסור להותיר מיום לחבירו.\n<b>והענין</b> הוא כי המן הוא ממדריגה גבוה שלמעלה מזמן ועליו ארז\"ל מי שברא יומו ברא פרנסתו. כי הנה בכלל יש ג' מדריגות, זמן, סדר זמנים כמו שאי' במד\"ר ע\"פ ויהי ערב ויהי בוקר מלמד שהי' סדר זמנים קודם לכן, ויש מדריגה שלמעלה מסדר זמנים ג\"כ, והמן הוא ממדריגה שלמעלה מסדר זמנים. וי\"ל זה על ב' אופנים, א' י\"ל שזמן הוא מבחי' מל' מלך מלך וימלוך עבר הוה עתיד, וסדר זמנים נוכל לומר שהו\"ע מדות, ולמעלה מהזמן הו\"ע מוחין, והמן שהי' למעלה מהזמן עליו ארז\"ל מי שברא יומו ברא פרנסתו ע\"ד מי ברא אלה, פי' אלה הו\"ע ו\"ק שכלול מוא\"ו והוא בגימט' אלה, כי מדות נק' יום ויומו של הקב\"ה אלף שנה כמ\"ש אלף שנה בעיניך כיום אתמול וזהו שאדה\"ר נתקלל ביום אכלך ממנו מות תמות, ובחסד הקב\"ה נתחלף לאלף שנה, רק ע' שנה נתן לדוד המלך ע\"ה. ואין הפי' שבמדות יש זמן אלא כשנמשך הארת המדה למל' נעשה מזה למטה זמן אלף שנה, ואלף שנים הראשונים שהי' מאיר הארה ממדת החסד, הי' חסדים, דור אנוש נזונים מחסדו של הקב\"ה, חסד אל כל היום, ובאלף השני הי' הארה ממדת הגבורה הי' גבורות, אלף ותרנ\"ו הי' דור המבול ואלף ותתקצ\"ו הי' דור הפלגה, ואלף השלישי ותמ\"ח הי' מ\"ת שהי' הארה ממדת הת\"ת כמ\"ש לך הוי' הגדולה והגבורה והת\"ת, נמצא שבמדות הו\"ע סדר זמנים מקור לזמן, אבל מוחין הם למעלה מסדר זמן, כי מדות שייכים לעולמות עד\"מ מדת חסדן או נדבן אינו שייך כ\"א לזולת שיש על מי להתחסד או להתחכם, אבל בלא זולת הרי דומה כמי שאין לו המדה, כי עצם המדה הוא לשם הפעולה וכשאינו זולת הרי דומה כמו שאין לו המדה כלל. אבל ענין מוחין יכול להשכיל השכלות בפ\"ע, וכן לימוד תורה, ואדרבה יכול להשכיל השכלות עוד יותר ושיתוסף עוד אצלו השכלות, כמו רשב\"י קודם שהי' במערה הי' הוא מקשה",[["1205","1","<b>הנני ממטיר</b>: הנחת א' מהשומעים מהמאמר ד\"ה אך להבין מ\"ש למען אנסנו, הנדפס לעיל ע' שצו ואילך. והוא המשך להמאמר ד\"ה מי זאת הנשקפה דש\"פ במדבר תרל\"ט. — הנחה זו נמצאת בכת\"י 1185. וראה לעיל ע' תקצב הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה, ובהנסמן בהמ\"מ לשם."]]],[2002180403,"לרפב\"י והיה רפב\"י מתרץ לרשב\"י י\"ב פירוקי, ולאחר י\"ג שנה שהיה במערה הי' רפב\"י מקשה לרשב\"י והוה הרשב\"י מתרץ לרפב\"י כ\"ד פירוקי, והוא הי' רק עם ר\"א בנו ולא שייך לומר ומתלמידי, וכמו\"כ למעלה מדות שייכים לעולמות, הגם שלא דומה מדות שלמטה לגבי מדות שלמעלה, שמדות שלמטה הם רק גרם ההשפעה אבל מדות שלמעלה הם עצם ההשפעה כמ\"ש מכלכל חיים בחסד שהם נק' ע\"ש ההשפעה, עכ\"ז הם מקור למקור לעולמות כמ\"ש זכור רחמיך וחסדיך כי מעולם המה, כי אמרתי עולם חסד יבנה. אבל בחי' מוחין אינו שייך אפי' להיות מקור לעולמות שהוא למעלה אפי' מסדר זמן, הגם שכתי' אלפיים שנה קדמה תורה לעולם, ופי' אלפים שנה הו\"ע אאלפך חכ' אאלפך בינה, וע\"ז כתי' ואהי' אצלו שעשועים יום יום, אך זהו רק שם המושאל, אבל באמת לא שייך לומר על מוחין בחי' זמן.\n<b>ולכן</b> כל השפעות שנמשך מבחי' זמן שהוא מחודש יכול להיות נפסק לכן שייך להכין מיום לחברו, אבל המן שהי' מבחי' מוחין מדריגה שלמעלה מסדר זמן והו\"ע אני הוי' לא שניתי לכן מי שברא יומו ברא פרנסתו. ועוי\"ל אופן אחר, שזמן הו\"ע מל', וסדר זמנים הו\"ע כללות ע\"ס דאצי', ולמעלה מסדר זמן הוא בחי' אין שלמעלה מחכ' וכמ\"ש והחכ' מאין תמצא. והמן שרשו מבחי' אין שלמעלה מבחי' חכ', ופי' מי שברא יומו פי' מי ע\"ש שאינו מושג, ומפני שהמן היה מבחי' שלמעלה מסדר זמן לכן אל יותר ממנו עד בוקר רק דבר יום ביומו.\n<b>אך</b> לפי\"ז צ\"ל איך ביום הששי הי' לחם יומים, והענין הוא כי יום הששי הי' גמר מעשה, ונתחב\"ס והי' מאיר בדרך אור חוזר הארה משבת בע\"ש לכן הרי זה דבר יום ביומו. דהנה כתי' ששת ימים עשה כו' וביום השביעי שבת, ואין הפי' הוא שהשביתה הוא כעין ששת ימי המעשה, כי הששת ימים נק' ששת ימי המעשה ולמשל אדם בעת שעושה מלאכה ה\"ה מלביש המוחין והמחשבה בעשי' ואח\"כ כשגומר העשי' נעשה החזרת המוחין למקורן ושרשן, כמו\"כ למעלה ששת ימי המעשה ה\"ז בבחי' ירידת האור, ובשבת הו\"ע עליות עולמות, ובששת ימי המעשה של ע\"ש התחיל בחי' שבת עליות העולמות ולכן מאיר הארה בע\"ש ג\"כ וה\"ז דבר יום ביומו. וע\"ד דוגמא מג' אוירין, שלמעלה האויר חם ובאמצע הוא קר ולמטה הוא חם, שלכאורה הוא רחוק יותר מהשמש ולמה הוא חם, והענין הוא מאחר שלמטה הארץ מונע ודוחה חום השמש בדרך או\"ח, ולכן הוא חם למטה. וכן הו\"ע בע\"ש שבין השמשות הו\"ע שביתה ועליות העולמות ומאיר בדרך או\"ח הארה משבת בע\"ש. ולכן ה\"ז דבר יום ביומו. וזהו מ\"ש יום השישי ויכולו השמים והארץ פי' ויכולו הוא מלשון כליון ותשוקה שהו\"ע עליות שהי' ביום השישי נמצא שהי' דבר יום ביומו.\n<b>וכן</b> הוא בתורה כתי' ג\"כ דבר יום ביומו בכל יום ויום יהיו בעיניך כחדשים שהוא ג\"כ למעלה מהזמן, ומ\"ש נער הייתי וגם זקנתי, אך זה שרו של עולם אמרו"],[2002180404,"אבל מי איכא זקנה קמי' ית'. וזהו\"ע שמ\"ח מעלות<sup data-n=\"1206\">2</sup>* אפי' לד\"ת פי' כשמחשב היום ללמוד כך וכך ולמחר כך וכך ה\"ה ממשיך תורה שהוא למעלה מהזמן בזמן ולכן מועלת. וכמו שיש ב' אופנים בזמן כך הוא בתורה ג\"כ, אם כפי' הא' שמדות הוא סדר זמנים ומוחין הוא למעלה מהזמן הרי גם אורייתא מחכ' נפקת, ואם כפי' הב' שגם מוחין שייך לסדר זמן ובחי' אין שלמעלה מחכ' הוא למעלה מסדר זמנים, צ\"ל הפי' שאורייתא מחכ' נפקת, אבל שרשה הוא למעלה מחכ', כי תרי\"ג מצות דאורייתא וז\"מ דרבנן הם תר\"ך עמודי אור שהו\"ע כתר שהוא בחי' אין שלמעלה מהזמן. וכן בשבת יש ג\"כ ב' בחי' הנ\"ל, שביתה אשר עשה ושביתה אשר ברא, אם כפי' הא' שמדות הם סדר זמנים ומוחין למעלה מהזמן הוא השביתה אשר עשה שכל יומא ויומא עביד עבידתא, ואם כפי' הב' שגם מוחין שייך לסדר זמנים, ולמעלה מהזמן הוא בחי' אין שלמעלה מחכ' הוא השביתה אשר ברא, כמ\"ש בורא קדושים שגם קדושים הוא בורא.\n<b>ומעתה</b> צ\"ל מפני מה כתי' היום לא תמצאוהו בשדה למה לא ירד המן בשבת. אך הענין הוא כמ\"ש שראשי נמלא טל קווצותיו רסיסי לילה, שהמן הי' ממדריגה גבוה והי' נמשך למטה בצמצומים רבים, עד\"מ שערות שיונקים ממוחין שבראש והחיות שלהם כ\"כ מצומצם עד אפי' כשגוזזין השערות אינו מרגיש שום כאב בזה, שאינו כן בשארי אברים שמרגיש בהם כאב, כן המן הי' נמשך בצמצומים רבים, ובשבת הו\"ע עליות העולמות לכן בשבת לא תמצאוהו בשדה. והמשל לזה הוא כשאדם מצמצם שכלו ומחשב ענין א' הרי בשעה שחושב ענין זה אי אפשר לו לחשוב ענינים אחרים וה\"ז צמצום גדול לגבי עצם השכל כן המן הי' נמשך למטה ע\"י צמצומים, ובשבת שהו\"ע עליות העולמות ע\"כ לא ירד המן. ואי' במכילתא היום דוקא לא תמצאוהו בשדה אבל תמצאוהו לע\"ל, ולכאורה צ\"ל הלא לע\"ל יהי' שכולו שבת ואיך יהי' המן. והענין הוא כי לע\"ל יתעלה מל' בכתר בדרך או\"ח לכן אז יהי' המן בלא צמצומים, כי באמת בשרש יש גם עכשיו בחי' המן וכמ\"ש ויברך אלקים את יום השביעי וארז\"ל במאי ברכו ברכו במן, ומשבת נמשך בכל ז' ימי השבוע, אך עתה דאינו מושג לכן לא נמשך למטה, אבל לע\"ל שיתעלה מל' בכתר בדרך או\"ח ויהי' מושג בחי' אין יהי' המן גם למטה. וזה דכתי' היום לא תמצאוהו בשדה, בשדה דוקא שהוא בחי' חקל תפוחין קדישין, אבל בבחי' לא באל\"ף שהוא בחי' אין, יש גם עכשיו בחי' המן. ולכן לע\"ל יומשך גם למטה.\n<b>ועתה</b> צ\"ל מהו פי' אכלוהו היום, הלא בכל ימי החול אכלו המן. אך הפ' הזה קאי על ג' סעודות של שבת, אכלוהו היום הוא כנגד סעודת ליל שבת, וכתי' היום כי בשבת אין בחי' לילה כי לילה הו\"ע בירורים שמל' יורד ומברר בירורים כמ\"ש ותקם בעוד לילה ותתן טרף לביתה רפ\"ח עם הכולל גימט' טרף, שהו\"ע",[["1206","2","<b>שמ\"ח מעלות</b>: כ\"ה בהכת\"י והוא טעות המעתיק, וצ\"ל: שמחשבה מועלת."]]],[2002180405,"בירורים, ואינו שייך בירורים רק באכילה דחול כמ\"ש ובטן רשעים תחסר, מחסר הניצוצים כמ\"ש אמלאה החרבה, אבל בשבת בורר אסור ואז אתפרשת מסט\"א שדוחה הרע ונתעלה הטוב, ואז האכילה הוא ע\"ד צדיק אוכל לשובע נפשו, פי' נפשו הוא נפש דוד והוא אוכל לשובע נפשו, כמ\"ש שובע שמחות את פניך, ואכלתם לחמכם לשובע, ומשביע לכל חי רצון, הו\"ע רצון העליון, ולכן כתי' אכלוהו היום שבחי' לילה ליכא, ולכן כל ששת ימי המעשה כתי' ויהי ערב ויהי בוקר כמו שאי' במד\"ר ל\"ו שעות שמשה אותה אורה י\"ב מע\"ש וי\"ב דליל שבת וי\"ב שעות מיום שבת, ובכלל סעודת ליל שבת הוא נגד שמור לנוקבא. ופ' כי שבת היום קאי על סעודת יום שבת והוא נגד זכור לדכורא. והיום לא תמצאוהו הוא סעודה שלישית נגד זכור ושמור בד\"א נאמרו, וסעודה השלישית הוא מחולק משאר הב' סעודות כי בב' סעודות הראשונות צ\"ל האכילה כראוי ולא יוצאין בפת הבא בכיסנין, אבל בסעודה הג' יוצאין בפת הבא בכיסנין ותורגמינן<sup data-n=\"1207\">3</sup> או בד\"ת, כי בב' סעודות הראשונות כתי' בם אכילה כמ\"ש אכלוהו היום וכן כי שבת היום הוא נתינת טעם לאכלוהו היום ולכן צריך שיעור אכילה, אבל סעודה הג' כתי' לא תמצאוהו שאינו צריך כ\"כ<sup data-n=\"1208\">4</sup>, והוא ע\"ד מארז\"ל ע\"פ ישא הוי' פניו אליך איך לא אשא פנים לישראל שכתי' בתורה ואכלת ושבעת וברכת שצריך אכילה כדי שביעה והם מדקדקים ע\"ע עד כזית עד כביצה. והענין הוא כי נשיאת פנים הוא מדריגה גבוה ולכן הוא חל על שיעור קטן אך צ\"ל על מה שיחול, וכן הו\"ע סעודה שלישית שהוא מדריגה גבוה ולכן יוצאין אפי' בפת כיסנין ותורגמין, כי סעודה שלישית הו\"ע עדן כמ\"ש וקראת לשבת עונג, ענג ר\"ת עדן נהר גן, סעודה הראשונה הוא בחי' גן וסעודה השני' הו\"ע נהר וסעודה הג' הוא בחי' עדן עין לא ראתה אלקים זולתיך, והוא מדריגה גבוה ולכן יוצאין בפת כיסנין ותורגמין.\n<b>ומעתה</b> יובן מה שאי' במד\"ר א\"ר ברכי' כשאני נתתי לכם את המן נתתי עומר לכאו\"א הה\"ד עומר לגולגולת, וכשאני מבקש מכם איני מבקש אלא עומר אחד מכולכם ולא עוד אלא של שעורים, פי' ענין עומר לגלגולת כי המן הוא מבחי' תיקון עמר נקי, ועי\"ז יכול לבוא לבחי' ענין גלגולת. והענין הוא כי אית רצון ואית רצון, אית רצון שהוא עפ\"י טו\"ד, עד\"מ אדם כשמתבונן בשכלו איך שטוב לפניו הדבר הזה רוצה את זה, והו\"ע רצון עפ\"י טו\"ד, ויש בחי' רצון שלמעלה מטו\"ד, וע\"י המן מגיע לבחי' גלגולת. וזהו\"ע כשאני נותן אני נותן לפי כוחי וכשאני מבקש איני מבקש אלא לפי כוחן עומר אחד מכולכם ולא עוד אלא של שעורים. ופי' ענין שעורה הוא שיעור ה' והו\"ע חח\"ת<sup data-n=\"1209\">5</sup> גלי' דתורה והו\"ע התבוננות מי ברא אלה המוציא במספר צבאם, ועי\"ז בא לבחי' יראה כמ\"ש בזאת יבוא אהרן דא תרעא",[["1207","3","<b>ותורגמינן</b>: ראה גם להלן: ותורגמין. ואוצ\"ל: ומיני תרגימא."],["1208","4","<b>סעודה הג' כתי' לא תמצאוהו שאינו צריך כ\"כ</b>: ראה לעיל ע' ת. וש\"נ."],["1209","5","<b>והו\"ע חח\"ת</b>: חמשה חומשי תורה."]]],[2002180406,"לאעלאה כו', וכמארז\"ל כל ת\"ח שיש בו תורה ואין בו יר\"ש דומה לגזבר שמסרו לו מפתחות הפנימי' ומפתחות החיצונים לא נמסרו לו בהי עייל, וכמ\"ש ועתה ישראל מה הוי' אלקיך שואל מעמך כ\"א ליראה, ואף שחושב שם עוד כמה דברים אך ההתחלה היא ביראה.\n<b>וזהו\"ע</b> שמעת יצ\"מ עד בואם לארץ הי' המן, שהמן נותן כח לבוא לבחי' גלגולת. אבל כי תבואו אל הארץ וקצרתם את קצירה והבאתם את עומר כו', שצריך אתעדל\"ת מעצמו צ\"ל בחי' יראה, ואח\"כ יכול לבוא למדריגה גבוה יותר. ובכלל הו\"ע ג' מועדים פסח שבועות סוכות, כי פסח הוא חג האביב והו\"ע השעורה אביב שהוא בחי' יראה. ואח\"כ יכול לבוא לחג השבועות שהוא קציר חיטים כי חטה בגימט' כ\"ב שהו\"ע כ\"ב אתוון דאוריי', נגילה ונשמחה ב\"ך, שעי\"ז מגיע לבחי' א\"ס עצומ\"ה. וזהו דכתי' וספרתם לכם ממחרת השבת כו' שבע שבתות תמימות תהיינה תספרו חמשים יום, והו\"ע זפ\"ז הוא בירור ז' מדות רעות דנה\"ב, ופי' לשון ספירה הוא מלשון ספירות ובהירות שמזככין ומבררין מדות רעות מנה\"ב, ואח\"כ יכול לבוא לבחי' אהבה. וזהו דכתי' תספרו חמשים והלא אין סופרים רק שבע שבתות שהוא רק מ\"ט יום, אלא ממילא עי\"ז יבוא לבחי' שער הנו\"ן דקדושה. וזהו פי' שע\"י שאו את ראש מספר בנ\"י עי\"ז באו לבחי' ד' דגלים.\n<b>ולהבין</b> ענין ד' דגלים הוא כמ\"ש כארבע רוחות השמים פרשתי אתכם, וארז\"ל כשם שא\"א לעולם בלא רוחות כן א\"א לעולם בלא ישראל, וד' רוחות מזרח מערב צפון דרום הוא כנגד ד' דגלים, ולמעלה הו\"ע ד' מחנות שכינה מחנה מיכאל גבריאל רפאל ואוריאל, מיכאל הוא כמ\"ש מי כמוך באלים הוי', מי אל כמוך, וגבריאל הוא כמ\"ש פלא יועץ אל גבור אבי עד, ורפאל הוא כמ\"ש אל נא רפא נא לה, ואוריאל הוא כמ\"ש אל הוי' ויאר לנו. וצ\"ל איך שייך מלאכים שהם מרכבה תתאה בבריאה יקראו ע\"ש אל שהוא שמו של הקב\"ה, או מי אל כמוך שמשם נמשך סליחות עוונות, או אל נא כו' שרפואה הוא רק בחיק הבורא. אך הענין הוא דכתי' והחיות נושאות את הכסא עם דמות כמראה אדם שעל הכסא, ופי' ענין בחי' אדם למעלה הו\"ע ציור ג' קוין חסד דרועא ימינא גבורה דרועא שמאלא ת\"ת גופא, והם נושאות כו' עם דמות כמראה אדם לא\"ס כי לא אדם הוא וכמ\"ש כי אל אנכי ולא איש, ואף שכתי' הוי' איש מלחמה שנק' בש' איש, אך הפי' הוא לא איש היינו כשנמשך א\"י בשי\"ן שהו\"ע ג' קוין זה הוי' קיוינו לו, וכיון שהגיעו לבחי' לא אדם עש\"ז נקראו בש' אל, ועי\"ז י\"ל ג\"כ מי אל כמוך שמשם נמשך סליחות עוונות. וגבריאל הוא ע\"ד מארז\"ל איזהו גיבור הכובש את יצרו, א\"א מגבור, ולמעלה הוא ענין א\"א, והענין הוא למעלה כמארז\"ל על הקב\"ה הכובש את כעסו ופעם אי' ג\"כ הכובש את יצרו, והיינו שדינין ומקטרגין לא יהיו מונעים ומעכבים והו\"ע בחי' גבורה למעלה. ועוי\"ל כי גבורה בגימט' רי\"ו שהוא ג\"פ ע\"ב וע\"ב בגימט' חסד ורי\"ו הו\"ע תגבורת החסד והו\"ע ג' ידות וזהו\"ע גבריאל."],[2002180407,"<b>וכמו</b> שיש ד' דגלים למעלה כן הי' בישראל למטה כמו שאי' במד\"ר ע\"פ ודלוגו עלי אהבה, שבעת מ\"ת ראו ישראל דגלים למעלה נתאוו גם הם לדגלים וכמו שאי' עוד במד\"ר שמחנה מיכאל קפ\"ו אלף כמו שהי' למטה, אך בדגל מחנה יהודה מחולק המדרש והזהר, שבמדרש אי' שדגל יהודה מכוון נגד מחנה גבריאל כי יהודה גבר באחיו, ובזהר אי' שדגל יהודה הי' מכוון נגד מחנה אוריאל שהי' במזרח, ועכ\"פ לב' הדיעות הוא שד' דגלים שלמטה מכוון נגד ד' דגלים שלמעלה, ואדרבא בשרש ד' דגלים שלמטה הם ממדריגה יותר גבוה, כי יתרון האור הוא מן החושך דוקא כד אתכפיי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין, וכן מלאכים כשביקשו את התורה השיבו להם כלום יצה\"ר יש ביניכם וניתנה דוקא על הארץ וכמ\"ש הוי' בחכ' יסד ארץ כונן שמים בתבונה שבחי' שמים רק בבינה וארץ הוא בחכ', ואף שהתגלות עתיק הוא בבינה עכ\"ז הרי חכ' נמצא הראשון מכתר, נמצא מכ\"ז שד' דגלים שלמטה הם בשרש גבוה מד' דגלים שלמעלה.\n<b>אך</b> כ\"ז הי' בזמן שבהמ\"ק הי' קיים, אבל עתה צ\"ל מקודם מי זאת הנשקפה כמו שחר יפה כלבנה ברה כחמה איומה כנדגלות, והו\"ע ד' גליות, ופי' כמו שחר קאי על דניאל שהי' מאיר כשחר, והו\"ע גלות בבל, ויפה כלבנה קאי על אסתר שאמרה ואני לא נקראתי לבוא אל המלך זה שלשים יום, כמו שהלבנה היא שלשים יום והו\"ע גלות יון, ואיומה הוא גלות אחרון, ועי\"ז מגיע לע\"ל לבחי' כנדגלות והו\"ע כמארז\"ל ע\"פ צדקת פרזונו בישראל צדקה עשה הקב\"ה עם ישראל שפיזרן בין אוה\"ע. וע\"פ פשוט הענין הוא כמארז\"ל קטיעה בר שילם שאל לו קיסר נימא אחת יש לו ברגל נקטענה ואחי' או אניחנה ואצטער והשיבו לו לא יכלת להו כי כתי' כארבע רוחות השמים פרשתי אתכם כשם שא\"א בלא רוחות כו'. ועוד י\"ל כי כתי' ואכלת את כל העמים שהו\"ע בירור הרע, וכ\"ז שהלך המן הי' מגיעים לבחי' גולגלת אבל עתה בגלות צ\"ל בבחי' נצחון שהו\"ע הסכם אתכפי', שלזה יכול כל אדם לבוא והוא כמ\"ש וגם נצח ישראל לא ישקר כי לא אדם הוא, שע\"י בחי' נצח יכול להגיע לבחי' כי לא אדם הוא. והענין כי גם בגלות נק' ישראל בש' אל ה\"ז בחי' נצח ועי\"ז מגיע לבחי' כי לא אדם, ולמשל מלך בעד ניצוח מבזבז אוצרות רב מה שלא יוותר כן בשביל שאר הוצאותיו, כן ע\"י בחי' נצח מגיע לבחי' מאוצר מתנת חנם חננו.\n<b>ועוי\"ל</b> פי' על כשם שא\"א לעולם בלא רוחות כן א\"א לעולם בלא ישראל, כמו רוחות המנשבות זה את זה, שמהבל האדם והבהמה יכול להתעפש האויר, אבל ע\"י הרוחות שמלמעלה למטה ומלמטה למעלה נזדכך האויר, כמו\"כ יש בנש\"י ב' בחי' רוח מלמטה למעלה ומלמעלה למטה, וכמ\"ש והרוח תשוב אל האלקים אשר נתנה, ואין הפי' תשובה מן ההיפוך מחטאים ועוונות רק תשובה מהעלם והסתר להעלות למקורן ושרשן, וזהו מלמטה למעלה, וכן בחי' רוח מלמעלה למטה הו\"ע כמ\"ש אם ישיב אליו לבו רוחו ונשמתו אליו יאסוף, רוח אייתי רוח ואמשיך רוח, וכמ\"ש ונחה עליו רוח הוי' רוח חכ' ובינה רוח עצה וגבורה רוח דעת ויראת השם,"],[2002180408,"וע\"י בחי' רוח שמלמטה למעלה עי\"ז נעשה בירור הרע ועל ידי זה מגיעים לעתיד לבוא להיות ממשיך גילוי אלקות."],[2002180409,"<h3>אז תשמח</h3>\n<b></b><b>בס\"ד, פ' ראה תרל\"ט, הנחה</b>\n<b>אז</b> תשמח<sup data-n=\"1210\">1</sup> בתולה במחול, וצ\"ל מהו ענין המחול. הנה אנו אומרים בקידוש לבנה כשם שאני רוקד כנגדך כו', וצ\"ל מהו שייכות ריקוד ללבנה, וגם מהו ענין הריקוד דכנגד. אך הענין דהנה אנו רואים בריקוד גשמי למשל שני בני אדם הרוקדים זה כנגד זה שתחלה הם רחוקים זמ\"ז עד שבבואם באמצע הבית הם נעשים קרובים זה לזה ע\"י ריקודם, והגם שאח\"כ הם מתרחקים יותר כמו למשל בתחלה א' עומד לדופן מזרח והשני לדופן מערב והרי הם רחוקים וע\"י ריקודם מתקרבים באמצע הבית, ואח\"כ מתרחקים עד שאותו שהי' במזרח הולך למערב ואותו שבמערב הולך למזרח, וה\"ה רחוקים מאד מ\"מ הכוונה מהריחוק הוא בכדי שע\"י ריקודם יתקרבו עוד. וזהו סוף מעשה שהוא הקירוב הוא במחשבה תחלה בעת הריחוק. ודרך כלל הריחוק נק' אחור באחור והקירוב נק' פנים בפנים. ועד\"ז יובן בלבנה שבתחלת החדש אינו ניכר עדיין אורה כ\"א עדים שהיו רואים את החדש הם היו רואים אבל לאחרים אינו ניכר האור כי הלבנה בעצמה הוא עצם חשוך וכל האור שלה הוא מה שמקבלת מהשמש, ובתחלת החדש שהוא תחלת קבלתה אינו ניכר האור וברבות הימים עד חצי החדש מתרבה ומתגדל אורה וה\"ז קירוב, כי ריבוי האור הוא קירוב וה\"ז פב\"פ, ואחר חצי החדש היא מתמעטת, וה\"ז ריחוק וה\"ז אחור באחור. והריקוד הוא ענין הביטול כי בכדי שתקבל ההשפעה מהשמש היא נעשית נקודה תחת היסוד שהו\"ע הביטול וזהו\"ע הריקוד דלבנה.\n<b>ועד\"ז</b> יובן בנש\"י כי הנה כתי' שמש ומגן הוי' אלקים ששם הוי' נק' שמש, והנה ארז\"ל ישראל מונין ללבנה דכמו שהלבנה עיקר התקרבותה להשמש בכדי להיות פב\"פ והוא ע\"י הביטול, כמ\"כ בנש\"י כתי' פנים בפנים דיבר הוי' עמכם שעיקר הכוונה הוא בכדי להיות פב\"פ עם הקב\"ה והסימן לזה הוא דע\"י שדיבר ה' עמכם עי\"ז נעשה שם הוי' בנש\"י ג\"כ. וענין שם הוי' בנש\"י, כי היו\"ד הוא הביטול שלמעלה מהטעם ודעת, ה' ראשונה הוא ענין התבוננות לאורך ורוחב באלקות, וא\"ו הוא תורה, ה' אחרונה דבור, ודרך כלל הוא תפלה. וזהו ענין פנים בפנים, כי פי'",[["1210","1","<b>אז תשמח</b>: הנחה לא נודע למי. נדפס כאן מכת\"י מעתיק מס' 505. ולעיל ע' תריט נדפס הנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע ממאמר זה. וע\"ש בהמ\"מ."]]],[2002180410,"פנים הוא משל דכמו שבפנים הם כל החושים הנעלים ראי' ושמיעה ריח וטעם, כמו\"כ בנמשל פנים הוא ענין הפנימי' וע\"י שהאדם מקשר פנימיותו להקב\"ה. וזהו פנים בפנים מלמטה למעלה ועי\"ז נעשה ג\"כ פב\"פ מלמעלמ\"ט.\n<b>והנה</b> דכמו שבהלבנה יש כ\"ח עתים י\"ד לטובה וי\"ד להיפוך כמ\"כ בנש\"י יש מדריגות שפעם הם בעלי' דהיינו שהיו בבחי' קירוב להקב\"ה, וכמו במ\"ת דכתיב ויחן ישראל וארז\"ל שנעשו כולם כאיש אחד וה\"ז ביטול גדול שכללות נש\"י נעשו כאיש אחד שהוא המספר הקטן שבכל המספרים וכמ\"ש לפני אחד מה אתה סופר, ואח\"כ על כל דיבור פרחה נשמתן שהוא ענין התשוקה והצמאון וכליון לא\"ס ב\"ה, וה\"ז פב\"פ בנש\"י מלמטה למעלה. ועי\"ז הי' ג\"כ מלמעלה פב\"פ וניתן להם הלוחות שהי' כולו פנים וכמ\"ש משני עבריהם הם כתובים, ואיתא בירושלמי שהלוחות היו כתובים בכל הששה קצות, וה\"ז כולו פנים, ולכן הי' נצרך לשאת בכתף בכדי לחבר אותם לאחוריים, ואח\"כ בחטא העגל נתרחקו מאלקותו ית', ואח\"כ כתי' ואנכי עמדתי בהר ארבעים יום כימים הראשונים וארז\"ל מה הראשונים ברצון אף אחרונים ברצון, והוא ענין שע\"י תשובה נעשה החזרת פב\"פ וכמ\"ש בצר לך ומצאוך ושבת עד כו'.\n<b>ובדרך</b> כלל ענין הקירוב הי' בזמן בהמ\"ק ובחורבן הבית הוא ענין הריחוק, דהנה בבהמ\"ק הי' גילוי אלקות וה\"ז קירוב גדול ואח\"כ נחרב הבית ונתרחקו ישראל מהקב\"ה, אך אין זה ריחוק לגמרי שהרי אחר שבעים שנה נבנה בית שני וה\"ה עוד בבחי' קירוב, ועכשיו לאחר החורבן שהו\"ע הריחוק לגמרי, מ\"מ הכוונה מזה הריחוק הוא ג\"כ בשביל הקירוב שלאח\"כ, כי עי\"ז באים נש\"י לתשובה, ועי\"ז יהי' גדול כבוד הבית האחרון שהו\"ע בהמ\"ק שיבנה במהרה בימינו, ובספרי הקבלה מחשבים כל הזמנים שהיו נש\"י בעלי' וירידה כו'<sup data-n=\"1211\">2</sup>. וזהו ענין ישראל מונין ללבנה, דכמו שהלבנה היא תמיד בעלי' וירידה והכוונה מהירידה הוא בשביל העלי' שאח\"כ, כמ\"כ הוא בנש\"י.\n<b>והנה</b> כתי' כי פנו אלי עורף ולא פנים, שהוא ענין דרך כלל קרירות ומצות אנשים מלומדה ועד\"מ באדם שמחשיב הגשמיות ליש ודבר ומשים פנימיותו בהם, אלא בכדי לצאת בדרך מצות אנשים מלומדה מתפלל ולומד מעט לפעמים ולכן נק' בשם עורף. אך מ\"מ כתוב גם ע\"ז כי פנו אלי שנק' ג\"כ בשם פנים מעט, כי הנה יש ב' בחי' חפץ ורצון, ובעבודה הו\"ע אתכפייא ואתהפכא, חפץ הוא הפנימי' מהרצון ורצון הוא חיצוניות, וזהו פי' כי פנו אלי שהגם שפנו אלי מ\"מ ה\"ז רק בחי' עורף כי פנימיות רצונו מקושר ומשוקע בהבלי העולם, וידע אינש בנפשי' באיזה פרט הוא משוקע, אך מ\"מ בחיצוניות שהוא הרצון יש לו ג\"כ רצון לאלקות וז\"ע אתכפיי' ולכן",[["1211","2","<b>ובספרי הקבלה מחשבים כל הזמנים שהיו נש\"י בעלי' וירידה כו'</b>: ראה ע\"ח שער מיעוט הירח פ\"ב."]]],[2002180411,"נק' ג\"כ בשם פנים. אך יש אדם שאין לו רצון כלל לאלקות אפי' בחיצוניות, מ\"מ ע\"י תשובה יכול להיות החזרת פב\"פ. ועיקר החזרת פב\"פ הי' במ\"ת, כי במ\"ת פרחה נשמתן על כל דיבור, והוא ע\"ד ויחד לבבינו שנתייחד חיצוני' הלב עם פנימיות הלב עד שנעשה כולו פנימי', כי בהכליון שפרחה נשמתן אין שייך התחלקות בין חיצוניות ופנימיות, אך ע\"י התשובה נעשה ג\"כ החזרת פב\"פ.\n<b>אך</b> כל זה עכשיו בזמה\"ג שהו\"ע הריקוד שלפעמים הם בריחוק ולפעמים בקירוב, אבל לע\"ל יהי' בחי' מחול שהוא ענין עיגול אשר אין שייך בעיגול קירוב וריחוק. והענין דהנה עכשיו הוא הגילוי דממכ\"ע שהוא כמו למשל התחלקות ראש וגוף ורגל ולכן נש\"י הם ג\"כ לפעמים כך ולפעמים כך, ולכן אפי' מי שהוא עובד ה' באמת אינו יכול לעמוד במדריגה אחת, כי הרי הוא נצרך להשפיל א\"ע ברצונות גשמי' כי בע\"כ אתה חי, ולכן בשעת התפלה כאשר מתבונן אז נתפעל באהוי\"ר ואחר התפלה כאשר ישפיל א\"ע ברצונות גשמיים אז חולפת ועוברת האהבה, והיינו מפני שעכשיו הוא הגילוי דממכ\"ע, אבל לע\"ל יהי' גילוי א\"ס הסוכ\"ע אשר אין בו התחלקות ומעלה ומטה, וזהו פי' מחול שהו\"ע הריקוד דמחול שהוא בעיגול בלתי קירוב וריחוק, כי לע\"ל לא יהי' עוד ריחוק.\n<b>ופי'</b> אז תשמח, אז הוא אל\"ף זיי\"ן, שהוא מספר שמונה, שהו\"ע כינור של שמונה נימין שיהי' לע\"ל, כי כנור של בהמ\"ק הי' של ז' נימין שהוא כנגד ז' ימי בראשית ז' ימי הבנין שהוא דרך כלל עדיין סדר השתלשלות, אבל לע\"ל יהי' שמונה נימין שהוא מדריגה שלמעלה מסדר השתל', כי אל\"ף הוא מדרגה שלמעלה מסדר השתל'. ולע\"ל כאשר יהי' גילוי זה יהי' שלימות השמחה, וכמארז\"ל ישמח ישראל בעושיו, שמח לא נאמר אלא ישמח, עתידים צדיקים לשמוח במעשיו של הקב\"ה, וכן ישמח ה' במעשיו עתיד הקב\"ה לשמוח במעשה הצדיקים לע\"ל, וזהו אז תשמח שע\"י גילוי מדרגת א\"ז, יהי' שלימות השמחה.\n<b>אך</b> ע\"י מה יהי' זה הגילוי לע\"ל, הוא ע\"י שישראל יהי' במדרגה הנק' בתולה. והענין דהנה כתי' בתולה ואיש לא ידעה, דהנה כמו שיש איש בקדושה כמ\"ש ה' איש מלחמה וכמ\"ש לזאת יקרא אשה כי מאיש לוקחה זאת, ואיש הוא מדריגה גבוה מאד<sup data-n=\"1212\">3</sup> כמבואר במ\"א, שהוא אש יו\"ד, כמ\"כ בלעו\"ז יש איש שהוא איש שדה, איש יודע ציד, איש מדון, איש תהפוכות, תהפוכות היינו שמהפך מסט' דקדושה לסט' דלעו\"ז, ואיש מדון היינו כמ\"ש ונרגן מפריד אלוף, וזהו פי' בתולה כמ\"ש גן נעול אחותי כלה שהו\"ע נעילה שנעולה מאיש דלעו\"ז, שאיש דלעו\"ז לא ידעה, ועי\"ז יהי' כלי קיבול לע\"ל לקבל גילוי א\"ס הסוכ\"ע. אבל זה הגילוי יהי' לע\"ל, כי עכשיו בעבודה צ\"ל ומלתם את ערלת לבבכם, דכמו שהמילה גשמיות מגלה העור המכסה, כמ\"כ יש מילה בעבודה ברוחניות שהוא ענין כריתה לכרות כל המונעים שהם",[["1212","3","<b>ואיש הוא מדריגה גבוה מאד כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380624\" data-slug=\"likkutei-torah\" data-id=\"4001380624\">לקו\"ת פינחס עו, א</a>. ובכ\"מ."]]],[2002180412,"טמטום הלב, וטמטום הלב שלבו אטום וסתום מלקבל דבר חכמה, ועי\"ז יהי' ומל ה' אלקיך את לבבך, ומל הוא מלשון גילוי שיהי' גילוי שם הוי' שיהי' בבחי' אלקיך שהו\"ע פב\"פ. ולכן מילה ג\"כ בשמיני כדי שיעבור עליו שבת אחת שהוא ג\"כ שמונה שהוא מדרגת אז, דבכדי לבוא לגילוי אז הוא ע\"י מילה דעכשיו. ואך כ\"ז הוא עכשיו, אבל לע\"ל יהי' גילוי מדריגת בתולה וכמארז\"ל אתתא כמאן דמהילא דמי'. והענין דהנה עכשיו צ\"ל כסדר המדריגות דצ\"ל בתחלה מדריגת מילה, ובכדי לבוא למילה צ\"ל שיעבור עליו שבת אחת שהוא אותיות תשב שהו\"ע התשובה ואח\"כ מילה, אבל לע\"ל לא יהי' ההילוך במדריגות שונות, כ\"א שיהי' הגילוי במדרגת בתולה כמאן דמהילא, והוא ע\"י גילוי המחול שהוא גילוי א\"ס הסוכ\"ע עי\"ז יהי' ישראל במדריגת בתולה ואיש כו' וההילוך יהי' במדריגת בתולה."],[2002180413,"<h3>ברזל בברזל</h3>\n<b></b><b>בס\"ד, ש\"ק פ' ראה, לד\"ה וקשרתם לאות על ידך, תרל\"ט</b>\n<b>ברזל</b> בברזל יחד<sup data-n=\"1213\">1</sup> ואיש יחד פני רעהו, וארז\"ל זה שני ת\"ח המחדדים זה לזה בהלכה, וצ\"ל מפני מה נמשלו ת\"ח לברזל. אך הנה כתיב ארץ אשר אבניה ברזל כו' וארז\"ל ע\"ז אל תקרי אבניה אלא בוניה אלו ת\"ח שהם בונים את העולם, ולמדו מזה דכל ת\"ח שאינו קשה כברזל אינו ת\"ח, וזהו שנמשלו ת\"ח לברזל, אך צ\"ל מפני מה נק' בנאים. אך הנה ארז\"ל שנים שיושבין ועוסקין בתורה שכינה שרוי' ביניהם, ומנין אפי' אחד שהקב\"ה קובע לו שכר, ופי' רבינו באגה\"ק ההפרש שבין אחד לשנים כי אצל אחד אמרו קובע לו שכר, והיינו הארת א\"ס המאיר להאדם הלומד את התורה, כי הנה אוא\"ס א\"א לנברא לקבל בלתי לבוש, והלבוש הוא תורה כמ\"ש עוטה אור כשלמה וע\"י לימודו בתו' נמשך לו הארת א\"ס באו\"פ לפ\"ע הלימוד שלו, אך פי' שכינה הוא כמארז\"ל אכל בי' עשרה שכינתא שרי' שהו\"ע אור מקיף, ופי' מקיף הוא אור גדול שאינו יכול להתלבש בכלי והכלי א\"א להגבילו כי כמה שיכול להיות התיישבות בכלי ה\"ה מאיר בפנימיותו ומה שא\"א להאיר בפנימיותו נשאר בבחי' מקיף, ומ\"מ ע\"י חידוד הלכה של שנים נמשך הארת אור גם מהמקיף בבחי' פנימי.\n<b>ולהבין</b> זה הנה כתי' ואהי' אצלו אמון וארז\"ל א\"ת אמון אלא אומן אמרה תורה אני הייתי כלי אומנתו של הקב\"ה, ובזהר אי' קוב\"ה אסתכל באורייתא",[["1213","1","<b>ברזל בברזל יחד</b>: נדפס כאן מכת\"י מס' 741 תשטו, א. והוא הנחת חסיד (לא נודע מי) מהמאמר הנדפס לעיל ע' תפז וע' תצג ואילך. וע\"ש בהמ\"מ. ולעיל ע' תרכב נדפס ג\"כ הנחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע ממאמר זה."]]],[2002180414,"וברא עלמא. והענין דהנה התורה היא ממוצע בין א\"ס המאציל לנבראים, כי הנה אוא\"ס הוא בלתי בע\"ג ובלתי בעל תכלית, ונבראי' הם בע\"ג ותכלית ואין ערוך כלל, ובכדי שיתהוו הנבראים מאתו ית' הוא ע\"י התו' שהיא הממוצע. והנה ידוע שהממוצע צ\"ל כלול משניהם ולכן בתורה יש בה מבחי' אחרונה שבמאציל ומראש ומקור לנבראים, וד\"כ הוא תושב\"כ ותושבע\"פ כי על תושב\"כ איתא בזהר אורייתא מחכ' נפקת שהיא ח\"ע דאצילות, הרי יש בתושב\"כ גילוי ח\"ע ולכן אין בה השגה כי השגת השכל היא בינה, וחכ' הוא עדיין רק נקודה בלבד בלי התגלות ובלתי השגה, והתורה היא עצם נקודת החכמה ולכן אין בה השגה גמורה כ\"א העיקר בתושב\"כ הוא אותיות, ולכן אי' ברמב\"ם שתמנע היתה פלגש הוא שוה למ\"ש וידבר אלקים<sup data-n=\"1214\">2</sup> את כל הדברים כו', אבל על תושבע\"פ אמרו מל' פה תושבע\"פ קרינן לה, וזהו ענין הממוצע שבתורה כי תושב\"כ היא ח\"ע, וח\"ע היא ראשית הגילוי שבנאצלים שהוא אצי' וה\"ז שייך לבחי' תחתונה שבמאציל, כי אצילות הוא מלשון אצל וסמוך להקב\"ה, ואפי' לפי הפי' שאצילות הוא מלשון הפרשת הארה מ\"מ ה\"ה הפרשת הארה מאלקות שהוא גילוי ההעלם מאלקות וה\"ז אלקות ממש. אך לפ\"ז צ\"ל א\"כ למה נק' אצי' בשם עולם והלא פי' עולם הוא מל' העלם והסתר. אך הענין דהנה אצילות נק' אלקות ולא אלקה ממש<sup data-n=\"1215\">3</sup> (ובל\"א נק' בשם געטלכקייט), ובאלקה ממש א\"א לכנות שום שם כלל, אבל באצי' שהוא רק התפשטות אלקות יתכן לקרותו גם בשם עולם אך מ\"מ ה\"ז אלקות, ולכן התורה שהיא מקור לאצי' שייך לבחי' תחתונה שבמאציל, ותושבע\"פ היא מל' שהמל' היא מקור לנבראים וה\"ז הבחי' שבהממוצע ששייך לנבראים.\n<b>ועוד</b> אפ\"ל שבין תושב\"כ ובין תושבע\"פ שניהם נק' בשם ממוצע. והענין דהנה אנו אומרים ועל תורתך שלמדתנו, תורתך היא התו' כמו שהיא למעלה קודם שנתלבשה בגשמי', ושלמדתנו היא התורה כמו שנתלבשה בגשמיות ציצית בצמר גשמי ותפילין בקלף גשמי שנים אוחזין בטלית המחליף פרה בחמור, והתורה כמו שהיא למעלה ברוחניות היא הבחי' העליונה שבהממוצע והתורה כמו שנתלבשה בגשמיות היא בחי' התחתונה שבהממוצע. ומפני שהתורה היא הממוצע לפי שני הפי' ולכן שנים שלומדים ביחד ומפלפלים במשארז\"ל מאי טעמא אמר קרא, מנלן אמר קרא וה\"ז שני המדריגות דתושב\"כ ותושבע\"פ ביחד וזה שואל ומקשה וזה מתרץ ונתחדש הלכה ביניהם עי\"ז נעשה ג\"כ חידוש למעלה שיהי' יחוד תושב\"כ ותושבע\"פ היינו שיהי' המשכת ח\"ע במל' שהיא תושבע\"פ כי כל הכוונה מהלימוד הוא בשביל היחוד דתושב\"כ ובע\"פ. וזהו מה שארז\"ל ע\"פ ביום חתונתו זה מ\"ת,",[["1214","2","<b>ולכן אי' ברמב\"ם שתמנע היתה פלגש הוא שוה למ\"ש וידבר אלקים</b>: בפיהמ\"ש בהקדמה לפ' חלק. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380095\" data-slug=\"likkutei-torah\" data-id=\"4001380095\">לקו\"ת ויקרא ה, ב</a>. המשך תער\"ב ח\"ג ע' א'שסו. ובכ\"מ."],["1215","3","<b>אך הענין דהנה אצילות נק' אלקות ולא אלקה ממש</b>: ראה לעיל בהנחת כ\"ק אדמו\"ר מהורש\"ב של מאמר זה. וש\"נ."]]],[2002180415,"דכמו שע\"י יחוד חו\"כ למטה נעשה עי\"ז הולדה חדשה שיהי' מוליד בדומה לו, עד\"ז יובן למעלה דעיקר לימוד התורה הוא בכדי שיהי' הולדה חדשה בדומה לו היינו גילוי ח\"ע במל'.\n<b>ועוד</b> אפ\"ל כי לבד שנעשה ע\"י החידוש יחוד תושב\"כ ובע\"פ, עוד זאת שנמשך תוס' אורות גם בתושב\"כ היינו בח\"ע דאצילות. והענין דהנה ארז\"ל יפה כח הבן<sup data-n=\"1216\">4</sup> מכח האב, והנה פי' כח הוא העלם, כי יש ב' בחי' פועל וכח, פועל היינו גילוי, וכח הוא מה שהוא בהעלם, ופי' יפה כח כו' היינו שנעשה דבר חדש בהבן מה שאינו גם בהעלם אצל האב, וצ\"ל מאין בא זה להבן. ולכאורה אפ\"ל שהוא מצד חלק הקב\"ה שנותן בו נשמה, אך לשון הגמ' שאמרו כח הבן משמע מצד חלק אב ואם. אך הענין דהנה לצורך ההולדה והשפעה נותנים כח להמשפיע מה שאין בו מצ\"ע, אך במשפיע עצמו א\"א להגלות עדיין זה הכח כ\"א בהפועל דהיינו בהבן שיצא ממנו שם מתגלה הכח ההוא, וענין הכח ההוא למעלה הוא כמ\"ש כי על כל כבוד חופה שיש ב' בחי' כבוד<sup data-n=\"1217\">5</sup>, כבוד נברא וכבוד נאצל, והחופה הוא בחי' מקיף גם על כבוד נאצל ומשם נמשך התוס' אורות, כי שרש היחוד דחו\"ב נמשך ממדריגה גבוה מאד.\n<b>ויובן</b> זה דהנה כתיב המחדש בטובו בכל יום תמיד מע\"ב, והנה י\"ב צירופים הוי' הם נגד י\"ב שעות היום שבכל שעה מאיר צירוף א', ועי\"ז נעשה התחדשות מע\"ב בכל שעה, והרי אינו דומה החיות של שעה זו לחיות של שעה האחרת ושל מחר, ושרש התחדשות זו נמשך מיחוד וזיווג חיצוני דחו\"ב, ואם ע\"י יחוד חיצוני דחו\"ב נעשה התחדשות כ\"כ מכ\"ש ע\"י יחוד פנימי דחו\"ב שהוא ע\"י יחוד דתושב\"כ ובע\"פ, כי תושב\"כ נק' אב שהוא חכ' ותושבע\"פ נק' אם שהוא בינה וכמ\"ש שמע בני מוסר אביך ואל תטוש תורת אמך, והגם שנת\"ל שתושבע\"פ הוא מל' מ\"מ במ\"א נתבאר שהוא בינה, וע\"י יחוד תושב\"כ ובע\"פ שע\"י נעשה יחוד פנימי דחו\"ב עי\"ז נמשך אור חדש לגמרי שלמעלה מהשתל' שהוא אור הכתר, כי כתר הוא מקיף שאינו מאיר בבחי' אור פנימי, אבל ע\"י חידוד הלכות של שנים נמשך הארה מכ\"ע באו\"פ בחו\"ב, וזהו מארז\"ל שנים כו' שכינה שהוא המקיף דכתר עליון שרויה ביניהם בבחי' או\"פ. וזהו מארז\"ל בכל יום יהיו בעיניך כחדשים, וגם אמרו שיהי' כדיוטגמא חדשה ולא כישנה, כי ע\"י התורה נמשך אור חדש לגמרי.\n<b>ובזה</b> יובן מה שמצינו שיש נשמות שיושבים בג\"ע יותר מג' אלפים שנה ועוסקים בתורה, וא\"א לומר שהם עוסקים בכל יום באופן א' אלא שהם מחדשים שם הלכות בכ\"י, וצ\"ל מאין הוא ההתחדשות בג\"ע והלא עיקר ההתחדשות וקיום התומ\"צ הוא בעוה\"ז דוקא ולא בעוה\"ב. אלא הענין שכל א' לפי ההתחדשות שלו",[["1216","4","<b>והענין דהנה ארז\"ל יפה כח הבן</b>: נסמן לעיל שם."],["1217","5","<b>כמ\"ש כי על כל כבוד חופה שיש ב' בחי' כבוד</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381317\" data-slug=\"likkutei-torah\" data-id=\"4001381317\">לקו\"ת שה\"ש מז, ב</a> ואילך. סה\"מ תרל\"ב ח\"ב ע' תקכג. תקנא. ובכ\"מ."]]],[2002180416,"שחידש בתורה בעוה\"ז עי\"ז נמשך או\"ח בג\"ע, וז\"ש רבינו בבינונים זיו תורתן ועבודתן המאיר בג\"ע<sup data-n=\"1218\">6</sup>, כי עיקר האו\"ח נמשך ע\"י החידוש דתורה בעוה\"ז, אך בעוה\"ז א\"א להתגלות עדיין כ\"א זיו ממנו נמשך בג\"ע לכל א' לפ\"ע החידוש שלו בעוה\"ז. וזהו מצות ושננתם לבניך שיהי' שנים עוסקין בהלכה ומחדשים חידוש בהלכה עי\"ז ממשיכים או\"ח מכתר עליון.\n<b>והנה</b> אח\"כ כתיב ודברת בם בשבתך בביתך, והענין דהנה בית הוא אותיות כמ\"ש בס\"י שתי אבנים בונות שני בתים כו' דכמו שהאבנים הם דומם כמו\"כ אותיות הם ג\"כ דומם, ועד\"מ מכמה אבנים בונים בית ומריבוי בתים נבנה עיר, ועד\"ז יובן שכללות עולם הדבור נק' עיר אלקינו, וזהו ודברת בם כו' בביתך, ודברת הוא מלשון ידבר עמים שהוא לשון הנהגה וקאי על ושננתם דקודם לכן, דהיינו שע\"י לימוד התורה יומשך גילוי השכינה עד עיר אלקינו, וזהו מ\"ש בחכמה יבנה בית<sup data-n=\"1219\">7</sup> שע\"י החכ' דתורה בונים בית אלקינו, ולכן נק' ת\"ח בנאים שבונים את העולם שממשיכים המשכת א\"ס בהעולם.\n<b>והנה</b> רז\"ל דרשו ודברת בם בד\"ת ולא בתפלה, ובכדי להבין זה צ\"ל דהנה בעשה\"ד כתי' וידבר כו' האלה לאמר, וצ\"ל כפל הלשון דיבור ואמירה. אך הענין דהנה יש שני בחי' דיבור ואמירה, דהנה כאשר האדם מדבר מפנימי' לבו או איזה ענין אשר נוגע לפנימי' לבו נק' בשם דיבור כמ\"ש דיבר אדוני הארץ אתנו קשות, וכאשר מדבר דברים שאין נוגע לפנימיותו נק' בשם אמירה. וזהו ההפרש בין עש\"מ לעשה\"ד, כי בעש\"מ אי' בזהר לאו אורחא דמלכא לאשתעי במילין דהדיוטא ולכן נק' בשם אמירה, אבל בעשה\"ד כתי' קול ה' בכח שהוא המשכה פנימי', ולכן נמשלה התורה לזיווג כמ\"ש ביום חתונתו זו מ\"ת, דהנה כל ההשפעות כמו השפעות השכל או שאר השפעות אינם כ\"א שפע חיצוני, אבל ע\"י יחוד נמשך שפע פנימי', וכמ\"כ בתורה נמשך שפע הפנימי' מא\"ס ב\"ה ולכן נק' בשם דברות. ועד\"ז יובן ההפרש בין תורה לתפלה, כי הנה התפלה היא בחשאי והיא אמירה, אבל התורה צ\"ל בקול בדבור דוקא וכמארז\"ל ע\"פ ערוכה בכל ושמורה אם ערוכה בכל רמ\"ח אברים דהיינו מה שלומד בדבור יתפעלו כל האברים אזי ושמורה, וצ\"ל ההפרש ביניהם. אך הענין דהנה כתי' הקל קול יעקב, ואיתא בזהר שקלא קדמאה חסר וא\"ו הוא קול התפלה, וקלא בתראה מלא וא\"ו הוא קול דתורה. דהנה התפלה היא העלאה מלמטלמ\"ע ולכן צ\"ל בחשאי בכוונה וברעותא דלבא בביטול, ואדרבה ארז\"ל כל המשמיע קולו בתפלתו ה\"ז מקטני אמנה, ולכן הוא חסר וא\"ו, שהוא\"ו הוא המשכה מלמעלמ\"ט והתפלה הוא העלאה מלמטלמ\"ע, אבל ע\"י התורה נעשה המשכות אלקות מלמעלמ\"ט ולכן הוא מלא וא\"ו, לכן צ\"ל בדבור דוקא שהדבור מורה על",[["1218","6","<b>וז\"ש רבינו בבינונים זיו תורתן ועבודתן המאיר בג\"ע</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נב, ב</a>)."],["1219","7","<b>וזהו מ\"ש בחכמה יבנה בית</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370087\" data-slug=\"torah-or\" data-id=\"3901370087\">תו\"א תולדות יח, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381202\" data-slug=\"likkutei-torah\" data-id=\"4001381202\">לקו\"ת שה\"ש יח, ב</a>."]]],[2002180417,"המשכה. אך לפ\"ז צ\"ל למה כתיב לאמר בעשה\"ד. אך הענין דהנה בתורה יש ג\"כ אמירה אלא שאמירה זו גבהה מעלתה הרבה ממעלת הדבור, והענין דהנה ארז\"ל הא לגירסא והא לעיוני, דהנה אנו רואים בלימוד התורה שהדבר שמשיגו כשהוא בשכל הגלוי מדבר אותו בדבור בכדי שיבא לגילוי לגבי עצמו מהשכל אבל הדבר שאינו משיגו ואינו מבין אותו ע\"ז נצרך עיון, והנה העיון הוא שמעלה כלי שכלו למקור השכל שהוא משכיל שנק' בד\"כ בשם חכ' הנעלמה, ואז הדבור מבלבל אותו כ\"א שצ\"ל שתיקה וכמארז\"ל שתיק רב, אשתומם כשעה חדא, וז\"ע אמירה דתורה שהוא הגבה מהדבור שהוא המשכת שכל הגלוי, ולכן נאמר בעשה\"ד דבור ואמירה. אך מ\"מ בד\"כ נק' התורה בשם דבור, כי מה שיש בשכל הגלוי הרי צ\"ל בדבור ודאי, ומה שאינו בשכל הגלוי ע\"ז נצרך עיון, ואחר העיון כאשר מבין אותו בשכלו הרי נצרך שיתגלה ג\"ז הדבר שהי' בתחלה בבחי' עיון בדבור אח\"כ. וזהו מאמרם ודברת בם בד\"ת שעיקר המשכת אלקות הוא ע\"י התורה ולא ע\"י התפלה שהוא העלאה. וזהו מ\"ש וענו הלוים בקול רם וארז\"ל בקולו של רם, דהיינו רוממות עצמותו ומהותו שנמשך ע\"י קול דתורה.\n<b>אך</b> כ\"ז ההמשכה הוא עדיין בעיר אלקינו שהוא בחי' מל' מקור הנבראים, אבל בבי\"ע אין שם גילוי עדיין, וע\"ז בא הציווי ובלכתך בדרך. דהנה כמו למשל הדרך שהולך מעיר לעיר, כמ\"כ בנמשל דרך הוא המשכת א\"ס שנמשך מעולם לעולם עד למטה מטה ולכן יש עיר קטנה ועיר גדולה וכפרים וכרכים שהמשל מהעיר הוא לפ\"ע אותו עולם שמדברים נגדו. אך ע\"י מה ממשיכים זה למטה, הוא ע\"י מ\"ש ושמרו דרך הוי' לעשות צדקה ומשפט, שהוא הדרך דתומ\"צ עי\"ז נמשך מלמעלה ג\"כ דרך הוי' וכמ\"ש כי ישרים דרכי הוי', וכמ\"ש כי לא מחשבותי מחשבותיכם ולא דרכיכם דרכי, ואימתי לא מחשבותי מחשבותיכם כשלא דרכיכם דרכי אבל כאשר דרכיכם דרכי דהיינו הדרך דתומ\"צ עי\"ז נעשה מחשבותי מחשבותיכם. כי הנה מחדו\"מ למעלה הוא כנגד ג' עולמות בי\"ע, וע\"י מח' דתו' עי\"ז נמשך בעולם הבריאה, וע\"י הדיבור נמשך בעולם היצירה, וע\"י מעשה המצות נמשך בעולם העשי'. וזהו פי' הפ' ושננתם לבניך הו\"ע חידוש הלכות, ובעבודה הו\"ע לימוד התורה ע\"ד ודברי אשר שמתי בפיך, תען לשוני אמרתיך, ועי\"ז נמשך המקיף דכ\"ע שהוא שכינה באו\"פ, וכמארז\"ל כל הקורא ושונה הקב\"ה קורא ושונה כנגדו, וההמשכה עד עיר אלקינו, וזהו ודברת בם בשבתך בביתך, ואח\"כ צריך להמשיך עד למטה מטה וזהו ובלכתך בדרך."],[2002180418,"<h3>תפלה לעני</h3>\n<b>בס\"ד, ר\"ה ש' תר\"מ</b>\n<b>תפלה</b> לעני<sup data-n=\"1220\">1</sup> כי יעטוף ולפני ה' ישפוך שיחו, הנה לכאורה צ\"ל מהו\"ע כי יעטוף, גם צ\"ל ענין לפני ה' ישפוך שיחו. הנה שיחו הוא לשון תרעומות, ומשמעות הכתוב משמע שתרעומות העני מגיע עוד לפני ה' שלמעלה משם הוי'. וצ\"ל מפני מה תרעומות העני מגיע לפני ה' כו'. להבין זאת צ\"ל תחלה הנה כתי' תקעו בחודש שופר בכסה ליום חגינו. וי\"ל למה נאמר בחדש סתם ולא נאמר באיזה חדש, הי' צריך לכתוב בחודש השביעי. ורז\"ל למדו מזה לפי שנאמר בכסה ליום חגינו איזהו חג שהחודש מתכסה בו הוי אומר זה ר\"ה, לפי שכל המועדים הם באמצע החודש שאז הלבנה במילואה, ויו\"ט של ר\"ה הוא בתחלת החודש שאז הלבנה מתכסה וע\"כ נאמר בחודש סתם מפני שקאי על בכסה. אך עדיין אינו מובן למה נאמר תקעו בחדש סתם וצריך ליתן סימן באיזה חדש, בכסה שאז הלבנה נתכסה, למה לא נאמר בפירוש בחודש השביעי, כמו שמצינו בתורה שנאמר בחודש השביעי באחד לחודש יום תרועה יהי' לכם, כך כאן הי' צריך לכתוב תקעו בחודש השביעי ואז לא הי' צריך הסימן של בכסה כו', אלא מפני שנאמר בחודש סתם ונאמר אח\"כ הסימן של בכסה מוכרח לומר שיש שייכות בין תקיעת שופר למה שהחודש מתכסה, וצ\"ל מהו השייכות בין תקיעת שופר לתיבת בכסה כו'.\n<b>אך</b> הענין הוא הנה כתי' ארץ אשר ה' אלקיך דורש אותה גו' מרשית השנה ועד אחרית שנה, הנה תיבת מרשית כתי' חסר ולמדו רז\"ל מזה בגמ' ר\"ה דט\"ז כל שנה שרשה בתחלתה מתעשרת בסופה, שנאמר מראשית השנה ועד אחרית שנה סופה שיש לה אחרית, ע\"ד מ\"ש ואחריתך ישגה מאד, וע\"ד יש תקוה לאחריתך, כי אחרית ע\"ה<sup data-n=\"1221\">2</sup> גימט' כתר, ופרש\"י שרשה בתחלתה שישראל עושין עצמן רשין ודלים ושפילים בר\"ה לדבר תחנונים ותפלה כענין שנאמר תחנונים ידבר רש. היוצא מזה שר\"ה צ\"ל בחי' רש כו', הגם שארז\"ל אל תעש תפלתך קבע אלא רחמים ותחנונים לפני המקום א\"כ בכל השנה צ\"ל ג\"כ בחי' רחמים ותחנונים, אך עיקר הרחמים צ\"ל בר\"ה שבר\"ה צ\"ל בחי' רש כו'.\n<b>ולהבין</b> זה צ\"ל מקודם מ\"ש תפלה לדוד הטה ה' אזנך ענני כי עני ואביון אני שמרה נפשי כי חסיד אני. וי\"ל הלא עני וחסיד רחוקים זמ\"ז, שקרוב לומר",[["1220","1","<b>תפלה לעני</b>: הוא הנחה מד\"ה תקעו בחודש הנדפס לעיל (פרקים א-ד), וכאן הוא באריכות הביאור. — לשון המאמר כאן הוא ע\"פ לשון המאמר ד\"ה תקעו הנ\"ל בהוספות רבות [וניכר שהי' לפני המניח את המאמר ד\"ה תקעו כפי שנמצא בבוך גוכי\"ק, והוסיף ע\"ז את ההוספות שהוסיף כ\"ק אדמו\"ר מהר\"ש בעת אמירת המאמר. ומסגנון ההנחה אולי י\"ל שהוא הנחת הרה\"ח ר' אהרן זעליגסאהן — ראה אודותיו קונטרס ”חנוך לנער\" ע' 24. סה\"מ פר\"ת ע' שדמ]. וראה לעיל ע' תרמד הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה (שם נמצא רק חלק מהמאמר).\nהמ\"מ והציונים למאמר זה כבר נסמנו לעיל בד\"ה תקעו."],["1221","2","<b>ע\"ה</b>: עם הכולל."]]],[2002180419,"שעני הוא היפך מחסיד, כי הרי ארז\"ל אין עני אלא בדעת, וא\"א לומר שפי' עני ממש כי דוד הי' מלך ישראל, אלא צ\"ל כמארז\"ל עני בדעת, וחסיד היינו כמארז\"ל איזהו חסיד המתחסד עם קונו עם קן דילי', א\"כ הם רחוקים זמ\"ז ולמה קרא עצמו עני כיון שהי' חסיד, ממ\"נ אם הי' עני לא יתכן שיקרא עצמו חסיד, ואם הי' חסיד לא יתכן שיקרא עצמו עני כו'. וגם מהו\"ע שאמר הטה ה' אזנך ענני כי עני ואביון אני שמשמע שמה שמבקש שיטה ה' אזנו לענות לו על בקשתו זהו מחמת הטעם להיותו עני ואביון כו', ומהו גודל מעלת העני כ\"כ. אך הנה אמרו רז\"ל יאה עניותא לישראל כברזא סומקא לסוסי' חיוורא, ובמד\"ר מבואר יותר יאה עניותא לברתא דיעקב כערקא סומקא לרישי' דסוסיא חיוורא, א\"כ יש מעלה בעניות. אך זהו רק יאה עניותא. אבל אינו מובן מפני מה עי\"ז הטה ה' אזנך ענני. אך להבין זאת הנה בסדר התפלה יש שני בחי' תפלה למשה איש האלקים ותפלה לעני כי יעטוף, ואיתא בזוהר שהשני בחי' כחדא נינהו. וצ\"ל איך הם שוים, הלא משה הי' בחי' עשיר עמודא דאמצעיתא איש האלקים, ואיך הוא שוה לעני, וא\"כ מהו המעלה של משה אם הוא שוה לעני כו'.\n<b>הנה</b> כתי' זה עני קרא וה' שמע דלכאורה אינו מובן הלא תיבת זה הוא מיותר שהי' צריך לכתוב עני קרא וה' שמע, ולמה נא' זה עני קרא, אלא לפי שזה קאי על משה וכמשארז\"ל כל הנביאים נתנבאו בכה ומשה נתנבא בזה, וכתי' כי זה משה האיש, וכן איתא במנחות יבא זה ויקבל זאת מזה לעם זו, שמשה נק' זה, וזהו זה עני קרא וה' שמע, דהיינו שזה שהוא משה היינו תפלה למשה, ועני היינו תפלה לעני, קרא וה' שמע, אם משה קרא או עני קרא שניהם שוים ממש כו'. אך באמת א\"ל<sup data-n=\"1222\">3</sup> שזה עני קרא היינו ע\"ד מ\"ש אל זה אביט אל עני ונכה רוח, לכאורה משמע שעני ונכה רוח הם שני דברים, אך באמת זהו ד\"א<sup data-n=\"1223\">4</sup>, שזה שהוא בחי' עני הוא מפני שהוא נכה רוח, הגם שבא ע\"י עבודה לבחי' זה מ\"מ הוא נחשב אצלו בחי' עני מפני שהוא נכה רוח, כי מה שהוא עני היינו לא מפני שהוא עני בדעת אלא הגם שיש לו השגה וידיעה באלקות מ\"מ הוא בחי' עני שאינו מחשיב א\"ע לדבר, והיינו כמו שמצינו בדוד והייתי שפל בעיני ועם האמהות אשר אמרת עמם אכבדה. כי הנה תכלית הידיעה שלא נדע, שא\"א להיות השגה באלקות, מ\"מ כמה שאפשר להיות השגה צריך להשיג, כי באם לאו אינו שייך עבודה, אך אחר השגה צריך לידע שא\"א להשיג באלקות, הנה יש פי' בידיעה לשון התקשרות, היינו התקשרות הנפש באלקות, מ\"מ צריך לידע שתכלית הידיעה שלא נדע, כי הנה פי' עשיר ועני, עשיר היינו עשיר בדעת ועני היינו בדעת, שזהו רק ידיעה, אבל באמת תכלית הידיעה שלא נדע, ואפי' לפי פי' ידיעה לשון התקשרות כמ\"ש וידעת היום והשבות אל לבבך כו', דע את אלקי אביך ועבדהו בלב שלם, מ\"מ צריך להבין שלא נדע שא\"א להיות השגה באלקות. וזהו אל זה אביט אל עני ונכה רוח, הגם שבא ע\"י עבודה לבחי' זה מ\"מ",[["1222","3","<b>באמת א\"ל</b>: אפשר לומר."],["1223","4","<b>באמת זהו ד\"א</b>: דבר אחד."]]],[2002180420,"הוא עני ע\"כ עי\"ז א\"ל שא\"א<sup data-n=\"1224\">5</sup> להשיג באלקות ועי\"ז מנחיל לו מלמעלה ג\"כ שיומשך בחי' לא נדע למטה.\n<b>וזהו</b> אדם ובהמה תושיע ה', וארז\"ל בנ\"א שהם ערומים בדעת כאדם הראשון שהוא בחי' ח\"ס כמ\"ש אני חכמה שכנתי ערמה, פי' חכמה היינו חכמה הגלוי', וחכמה הגלוי' הוא בחי' שכן לערמה פי' ערמומית היינו שמסתיר הענין, כמו שאנו רואים למטה בגשמיות שמסתיר הענין שחבירו אינו מבין כלל ועי\"ז כובש המנגד, כי אם הי' מגלה לו הי' עומד כנגד, אלא שמסתיר הענין, וכמו שיש ערמומית בלעו\"ז והנחש הי' ערום כך יש ערמומית בקדושה בא אחיך במרמה ויקח ברכתך, והיינו בחי' ח\"ס, וזהו ערומים בדעת כאדם מ\"מ משימים א\"ע כבהמה ופרש\"י דכאי הרוח כעני שהוא נכה הרוח, כי ההפרש בין אדם לבהמה שאדם יש לו דעת ובהמה אין לה דעת ע\"כ משימים עצמם כבהמה שאין לה דעת, וזהו אל זה אביט אל עני ונכה רוח, הגם שבא ע\"י עבודה לבחי' זה מ\"מ הוא מחשיב עצמו כעני מפני שהוא נכה רוח, וכן זה עני קרא הגם שהוא בחי' זה מ\"מ הוא מחשיב א\"ע לעני כו'.\n<b>והנה</b> פעם איתא בזוהר שתפלת העני קודם לתפלת משה וראייתו מתפילין של יד כי תפילין ש\"י מניחים על יד כהה שיד כהה לגבי יד ימין נק' עני, כמו שעני הוא מחוסר לגבי עשיר שלעשיר יש ולעני מחוסר זאת, כן יד כהה מחוסר כח לגבי יד ימין, ע\"כ נק' עני, ועוד תפילין של ראש יש ד' פרשיות בד' בתים שזהו הוראה ששם הוא בשפע ובתפילין ש\"י הגם שיש כל מה שיש בתפילין ש\"ר מ\"מ כל הד' פרשיות הם בב\"א<sup data-n=\"1225\">6</sup> שהשפעה שם בצמצום ע\"כ תפילין ש\"ר הוא בחי' תפלה למשה, ואעפי\"כ מקדימין תפילין ש\"י לתפילין ש\"ר כך תפלה לעני צריך להיות קודם תפלה למשה כו'. ולכאורה אינו מובן למה תפלה לעני קודם תפלה למשה, שהרי אף לפי דעה זו ששניהם שוים ג\"כ קשה איך יהיו שוים וכ\"ש שתפלה לעני יהי' קודם לתפלה למשה זה אינו מובן כלל, למה יהי' תפלה לעני קודם כו'.\n<b>אך</b> הענין הוא הנה מתחלה י\"ל למה ברא הקב\"ה עניים והעני צריך לקבל מהעשיר למה לא ברא שיהיו הכל שוים, ולכה\"פ שלא יהי' העני צריך לקבל מהעשיר, אלא שיקבלו כולם השפעתם מלמעלה, כי הקב\"ה ברא את האדם וכיון שהוא ברא אותו הי' צריך ליתן לו כל הצטרכות שנצרך לו, כמו שיהי' לע\"ל שיהי' כל א' תחת גפנו ותחת תאנתו כך הי' נצרך שיהי' עכשיו ג\"כ כן ולא שיקבל מעשיר, אך מ\"מ אנו רואים דכתי' כי לא יחדל אביון מקרב הארץ משמע שצריך להיות בחי' אביון. והגמ' משני לפי שנא' מלוה ה' חונן דל כי הקב\"ה כאשר ברא את העני הי' צריך ליתן לו כל ההצטרכות שנצרך לו וכאשר העשיר נותן להעני הוא מלוה ה', שחונן דל הוא",[["1224","5","<b>ע\"כ עי\"ז א\"ל שא\"א</b>: על כן על ידי זה אפשר להבין שאי אפשר."],["1225","6","<b>בב\"א</b>: בבית אחד."]]],[2002180421,"מלוה ה', ועי\"ז הקב\"ה משלם לו בכפלים כמ\"ש עשר תעשר, בשביל שתתעשר, שעי\"ז שנותן מעשר עי\"ז תתעשר, שהקב\"ה נותן לו בכפליים. אבל גם זה אינו מובן למה צריך הקב\"ה ללוות ממון ואח\"כ לשלם לו הי' לו ליתן לכתחלה להעני ולא הי' צריך ללוות מהעשיר. אך במד\"ר משני כדי שיזכו זל\"ז שהעשיר יזכה להעני והעני מזכה להעשיר, כמו שהעשיר מזכה להעני השפעה גשמיות כך העני מזכה להעשיר השפעה רוחניות, וגשמיות לגבי רוחניות אין ערוך כי מזכה לו שעי\"ז עושה העשיר מצות צדקה וצדקה הוא כללות כל המצות כמ\"ש וצדקה תהי' לנו כו', וכמ\"ש ברות אשר עשיתי עמו, הגם שרות קיבלה מבועז מ\"מ אמרה אשר עשיתי עמו שעי\"ז היא מזכה לבועז. ותירוץ זה הוא תירוץ עיקר, כי לפי תירוץ הגמ' משמע רק שהעשיר מזכה לעני אבל שהעני יזכה לעשיר אינו מובן משם, אבל לפי תירוץ הרבות מובן שגם העני מזכה לעשיר ג\"כ כמו שית' להלן כו'.\n<b>והנה</b> באמת יש בזה כוונה עמוקה למה נבראו עניים, דהנה למעלה בכל סדר השתל' יש בחי' משפיע ומקבל, כמו שמים וארץ ששמים הוא בחי' משפיע וארץ הוא בחי' מקבל, כמ\"ש אני אענה את השמים והם יענו את הארץ, כי כאשר ירד הגשם והשלג מן השמים ושמה לא ישוב כי אם הרוה את הארץ והולידה והצמיחה, שכדי שיהי' צמיחה צריך להיות המשכה מלמעלה בחי' גשם, וכן הוא בבחי' שמו\"א הרוחני', שמים הוא בחי' ז\"א מדות, וארץ הוא בחי' דיבור, שענין מדות ודיבור ששפע הדיבור נמשך מבחי' מדות שבלב, שמה שיש במדה שבלב כך הוא מדבר שזהו משפיע ומקבל. ועד\"ז למעלה יותר בבחי' חו\"ב הוא ג\"כ בדרך משפיע ומקבל שחכמה נק' אב בחי' משפיע ובינה בחי' אם בחי' מקבל, וכן למעלה יותר בעת\"י דאיתא בע\"ח דעת\"י דאצי' כל עצמותו הוא משני בחי' מ\"ה וב\"ן, מ\"ה שבו הוא בחי' עתיק דדכורא וב\"ן שבו הוא בחי' נוק' דעתיק. ונמצא אפי' בע\"ק שעת\"י הוא בחי' המתנשא מימות עולם שמרומם מעולם מ\"מ גם שם יש בחי' משפיע ומקבל. ואפי' בכללות השתלשלות בחי' הקו הוא השפעה כדי שיהי' התהוות ד' עולמות אבי\"ע, כשעלה ברצונו שיהי' התהוות העולמות סילק אור עצמותו ואח\"כ נמשך המשכת הקו, שהצמצום שהי' בתחלה הי' סובל בתוכו כל ד' עולמות אבי\"ע, ומי הוא הגורם שיומשך מלפני הצמצום ויהי' התהוות ד' עולמות אבי\"ע היינו ע\"י המשכת הקו, א\"כ אפי' בכללות עולמות דכללות השתלשלות גם שם יש בחי' משפיע ומקבל. ואפי' עולמות א\"ס כיון שנק' בשם עולם צריך להיות ע\"י הצמצום א\"כ גם שם יש בחי' משפיע ומקבל. ובלשון השמות היינו שם הוי' ושם אלקים, שם הוי' הוא בחי' משפיע, ושם אלקים הוא בחי' מקבל, כמ\"ש וה' בהיכל קדשו היכל בגימט' אד', כוס בגימט' אלקים, וכמו שההיכל הוא בחי' מקבל וכן כוס הוא מקבל המשקה כך שם אלקים הוא בחי' מקבל משם ה'.\n<b>ובזוהר</b> נק' בשם יחוד שמשא וסיהרא, שמש הוא בחי' שמש ה' משפיע, וסיהרא הוא בחי' מקבל, דהנה סיהרא לית לה מגרמה שאין לה שום אור בפ\"ע ע\"כ נק' עני, וע\"י שסיהרא מקבלת משמש עי\"ז נמשך תוס' בשמש, כידוע במשפיע"]]});
